insert into public.exams(slug,title,source,year) values ('pmsp-soldado-2026','PM São Paulo · Soldado · 2026 · 20/09/2026','pmerj','2026') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Língua Portuguesa','Para o cronista, a preparação do calulu desencadeou','Leia o texto para responder às questões de 01 a 08: Domingo do calulu Há regressos assim. Sem sair do lugar, me dou por regressado a Benguela¹ através da cozinha, juntando no refogado restos de uma identidade adormecida. A minha cultura! Afinal, de que sou feito?, ainda ontem me perguntaram; deve ser por causa do sotaque, ou da falta dele. Pode vos parecer disparatado e absurdo, mas a verdade é que me questionam várias vezes sobre a minha angolanidade: há quanto tempo não vais a Angola?, qual foi a última vez que lá foste? A receita nunca me foi ensinada, por isso vou acrescentando, improvisando, tal como o cozinhador João Carlos Silva, tal qual um Avillez, manuseando a faca com a mestria de um samurai. Tenho o tacho de boca larga, inoxidável e um tanto reluzente demais, comparando com aquelas velhas panelas pretas, calcinadas de tanto irem ao fogo, e que passavam de geração em geração, encerrando em si histórias de refeições memoráveis que duravam tardes inteiras. Começo por refogar metade de uma cebola picada em óleo de palma, depois o tomate maduro cortado aos cubos, as postas de corvina seca e fresca, as beringelas aos quadrados, a folha de louro. Deixo repousar sobre o lume brando alguns instantes antes de colocar o resto da cebola e do tomate, assim como os espinafres, que, apesar de aparecerem a substituir as folhas de rama (impossíveis de encontrar fora de Angola), ainda assim quebram o galho. Já cheira a calulu², já consigo viajar até Benguela. Às vezes, pergunto-me como consigo resistir à distância, eu que nem sou de me entregar à saudade, que vivo bem sem o funge³, a bandeira gastronômica dos angolanos. Não sei responder e foi preciso implorarem-me para cozinhar algo tipicamente angolano para revisitar velhas receitas familiares que agora, tal como um álbum de fotografias, me trazem lugares, rostos, conversas que julgava perdidas. (Kalaf Epalanga. Minha pátria é a língua pretuguesa: Crônicas, 218. Adaptado) Vocabulário: ¹ Benguela: província de Angola, na África. ² calulu: espécie de ensopado de peixe preparado com quiabo, abóbora, beringela, temperos e azeite de dendê. ³ funge: pirão de farinha de mandioca ou milho com um caldo.',null,'["a sua história adormecida, com resgate de certas tristezas vividas na infância.", "a sua resistência às lembranças, com o evidente desconforto para cozinhar.", "a sua memória afetiva, com reminiscências da vida pregressa em Benguela.", "a sua fragilidade emocional, com saudade e tristeza ao pensar em Benguela.", "a sua alegria, por preparar uma comida diferente da sua tradição familiar."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2026' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Língua Portuguesa','Em seu relato, o cronista recorre a uma comparação para referir-se a uma ação na passagem:','Leia o texto para responder às questões de 01 a 08: Domingo do calulu Há regressos assim. Sem sair do lugar, me dou por regressado a Benguela¹ através da cozinha, juntando no refogado restos de uma identidade adormecida. A minha cultura! Afinal, de que sou feito?, ainda ontem me perguntaram; deve ser por causa do sotaque, ou da falta dele. Pode vos parecer disparatado e absurdo, mas a verdade é que me questionam várias vezes sobre a minha angolanidade: há quanto tempo não vais a Angola?, qual foi a última vez que lá foste? A receita nunca me foi ensinada, por isso vou acrescentando, improvisando, tal como o cozinhador João Carlos Silva, tal qual um Avillez, manuseando a faca com a mestria de um samurai. Tenho o tacho de boca larga, inoxidável e um tanto reluzente demais, comparando com aquelas velhas panelas pretas, calcinadas de tanto irem ao fogo, e que passavam de geração em geração, encerrando em si histórias de refeições memoráveis que duravam tardes inteiras. Começo por refogar metade de uma cebola picada em óleo de palma, depois o tomate maduro cortado aos cubos, as postas de corvina seca e fresca, as beringelas aos quadrados, a folha de louro. Deixo repousar sobre o lume brando alguns instantes antes de colocar o resto da cebola e do tomate, assim como os espinafres, que, apesar de aparecerem a substituir as folhas de rama (impossíveis de encontrar fora de Angola), ainda assim quebram o galho. Já cheira a calulu², já consigo viajar até Benguela. Às vezes, pergunto-me como consigo resistir à distância, eu que nem sou de me entregar à saudade, que vivo bem sem o funge³, a bandeira gastronômica dos angolanos. Não sei responder e foi preciso implorarem-me para cozinhar algo tipicamente angolano para revisitar velhas receitas familiares que agora, tal como um álbum de fotografias, me trazem lugares, rostos, conversas que julgava perdidas. (Kalaf Epalanga. Minha pátria é a língua pretuguesa: Crônicas, 218. Adaptado) Vocabulário: ¹ Benguela: província de Angola, na África. ² calulu: espécie de ensopado de peixe preparado com quiabo, abóbora, beringela, temperos e azeite de dendê. ³ funge: pirão de farinha de mandioca ou milho com um caldo.',null,'["Começo por refogar metade de uma cebola picada em óleo de palma... (2o parágrafo)", "Não sei responder e foi preciso implorarem-me para cozinhar algo... (3o parágrafo)", "... ainda ontem me perguntaram; deve ser por causa do sotaque, ou da falta dele. (1o parágrafo)", "... tal qual um Avillez, manuseando a faca com a mestria de um samurai. (2o parágrafo)", "... há quanto tempo não vais a Angola?, qual foi a última vez que lá foste? (1o parágrafo)"]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2026' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
