insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Língua Portuguesa','Assinale a alternativa com a informação implícita que provoca o efeito de humor da tira.','Leia a tira para responder às questões 01 e 02:','["/pmsp/soldado-2025-11/apoio-1-2-2-1.png"]','["O pai de Mafalda passou de carro na frente da padaria e foi visto por uma mulher que o desprezou.", "Mafalda não sabia que seu pai havia comprado um carro novo, por isso questiona a informação da amiga.", "A expressão “pé-rapado” pode ser usada para descrever muitas pessoas, mas não o pai de Mafalda.", "A senhora que chamou o pai de Mafalda de “pé- -rapado” não tem como conhecer a real situação financeira dele.", "A amiga considera que “pé-rapado” seja uma expressão adequada para se referir ao pai de Mafalda."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Língua Portuguesa','Em – ...hoje seu pai passou de carro na frente da padaria... –, a expressão destacada pode ser substi tuída, em conformidade com a norma-padrão, por:','Leia a tira para responder às questões 01 e 02:','["/pmsp/soldado-2025-11/apoio-1-2-2-1.png", "/pmsp/soldado-2025-11/q2-2-figura-1.png"]','["diante à", "defronte na", "a frente da", "diante da", "adiante à (Quino. 10 anos com Mafalda. São Paulo: Martins Fontes, 2018. Adaptado)"]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Língua Portuguesa','A partir da leitura do poema, é correto afirmar que o eu lírico expressa','Leia o poema para responder às questões 03 e 04: Há estes dias em que pressentimos na casa a ruína da casa e no corpo a morte do corpo e no amor o fim do amor estes dias em que tomar o ônibus é no entanto perdê-lo e chegar a tempo é já chegar demasiado tarde não são coisas que se expliquem apenas são dias em que de repente sabemos o que sempre soubemos e todos sabem que a madeira é apenas o que vem logo antes da cinza e por mais vidas que tenha cada gato é o cadáver de um gato (Ana Martins Marques. O livro das semelhanças. São Paulo: Companhia das Letras, 2015)',null,'["desencantamento pelas circunstâncias presentes e tentativa de recuperar o passado.", "consciência sobre a impermanência de todos os seres, sejam eles animados ou inanimados.", "preocupação pelo descaso com que os humanos tratam suas vidas e as dos demais seres.", "dificuldade em aceitar os obstáculos encontrados no cotidiano, como a perda de um ônibus.", "nostalgia de coisas que marcaram sua vida, como as casas e os amores do passado."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Língua Portuguesa','Assinale a alternativa em que o acréscimo de vírgula(s) está em conformidade com a norma-padrão de emprego desse sinal de pontuação.','Leia o poema para responder às questões 03 e 04: Há estes dias em que pressentimos na casa a ruína da casa e no corpo a morte do corpo e no amor o fim do amor estes dias em que tomar o ônibus é no entanto perdê-lo e chegar a tempo é já chegar demasiado tarde não são coisas que se expliquem apenas são dias em que de repente sabemos o que sempre soubemos e todos sabem que a madeira é apenas o que vem logo antes da cinza e por mais vidas que tenha cada gato é o cadáver de um gato (Ana Martins Marques. O livro das semelhanças. São Paulo: Companhia das Letras, 2015)',null,'["Há, estes dias em que pressentimos, na casa", "apenas são, dias em que, de repente sabemos", "em que tomar o ônibus é, no entanto, perdê-lo", "e chegar a tempo, é já chegar demasiado tarde", "que a madeira, é apenas o que vem logo antes"]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Língua Portuguesa','Em relação à “cadeia de solidariedade intergeracional” (1o parágrafo), é correto afirmar, com base no texto, que esta','Leia o texto para responder às questões de 05 a 08: Nos últimos tempos, rompeu-se o elo colaborativo entre gerações. Nas famílias tradicionais, por milhares de anos, ter filhos significava que, quando os pais envelhecessem e não pudessem mais trabalhar, os filhos adultos cuidariam deles. Assim, garantia-se um equilíbrio entre a idade adulta produtiva e os dependentes (crianças e idosos) em uma cadeia de solidariedade intergeracional. Mas o que acontece quando a maioria dos adultos não tem filhos, como vem acontecendo? Nos países nórdicos, políticas públicas garantem lares dignos para idosos e saúde gratuita para a população envelhecida. O que antes era responsabilidade das famílias, agora é assegurado em escala coletiva. Nos apartamentos exíguos da família nuclear, não há espaço para os avós, mas ao menos há apoio público. Já em países como EUA, e sobretudo no Brasil, os idosos enfrentam apoio familiar declinante e políticas sociais precárias. Os asilos privados? Caríssimos e mal administrados – quando não criminosamente negligenciados. Sistemas que só visam lucro máximo não são opção de gestão adequada – pra dizer o mínimo. E a ansiedade acerca de nosso futuro quando idosos já é sentida quando estamos na meia idade. (Ladislau Dowbor. Disponível em: https://outraspalavras.net/crise-civilizatoria/ dowbor-pra-nos-tirar-da-solidao/. Acesso em 28/09/2025. Adaptado)',null,'["tem se mostrado mais forte nos países nórdicos, em que a taxa de natalidade segue estável como no passado.", "fica afetada quando nascem menos crianças, fazendo com que os países devam criar estratégias de cuidado com os idosos.", "depende de decisões individuais e familiares, motivo pelo qual os países têm dificuldade em promovê-la.", "é particularmente preocupante em países como o Brasil e os Estados Unidos, lugares em que o número de idosos é baixo.", "está baseada, tradicionalmente, na criação de filhos autônomos que possam trabalhar para sustentar a si próprios."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Língua Portuguesa','Quanto à comparação feita no texto entre o Brasil e outros países, é correto afirmar:','Leia o texto para responder às questões de 05 a 08: Nos últimos tempos, rompeu-se o elo colaborativo entre gerações. Nas famílias tradicionais, por milhares de anos, ter filhos significava que, quando os pais envelhecessem e não pudessem mais trabalhar, os filhos adultos cuidariam deles. Assim, garantia-se um equilíbrio entre a idade adulta produtiva e os dependentes (crianças e idosos) em uma cadeia de solidariedade intergeracional. Mas o que acontece quando a maioria dos adultos não tem filhos, como vem acontecendo? Nos países nórdicos, políticas públicas garantem lares dignos para idosos e saúde gratuita para a população envelhecida. O que antes era responsabilidade das famílias, agora é assegurado em escala coletiva. Nos apartamentos exíguos da família nuclear, não há espaço para os avós, mas ao menos há apoio público. Já em países como EUA, e sobretudo no Brasil, os idosos enfrentam apoio familiar declinante e políticas sociais precárias. Os asilos privados? Caríssimos e mal administrados – quando não criminosamente negligenciados. Sistemas que só visam lucro máximo não são opção de gestão adequada – pra dizer o mínimo. E a ansiedade acerca de nosso futuro quando idosos já é sentida quando estamos na meia idade. (Ladislau Dowbor. Disponível em: https://outraspalavras.net/crise-civilizatoria/ dowbor-pra-nos-tirar-da-solidao/. Acesso em 28/09/2025. Adaptado)',null,'["Os países nórdicos e o Brasil negligenciam tanto o papel do Estado quanto o da família no cuidado com os mais velhos.", "Nos países nórdicos, a responsabilidade com os idosos permanece majoritariamente com as famílias, enquanto no Brasil o Estado complementa a assistência.", "Os asilos privados tanto no Brasil quanto nos EUA são em geral bem administrados, mas inacessíveis para a maioria da população.", "A atuação das políticas públicas nos países nórdicos assegura dignidade aos idosos, enquanto no Brasil os asilos são opções insatisfatórias.", "Os modelos de gestão baseados no lucro máximo vigoram nos países nórdicos, mas não no Brasil, e são uma solução adequada para o cuidado dos idosos."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Língua Portuguesa','Considere os trechos: • Nos apartamentos exíguos da família nuclear, não há espaço para os avós... (2o parágrafo) • ... sobretudo no Brasil, os idosos enfrentam apoio familiar declinante... (2o parágrafo) No contexto em que foram empregadas, as palavras destacadas têm como sinônimos, respectivamente,','Leia o texto para responder às questões de 05 a 08: Nos últimos tempos, rompeu-se o elo colaborativo entre gerações. Nas famílias tradicionais, por milhares de anos, ter filhos significava que, quando os pais envelhecessem e não pudessem mais trabalhar, os filhos adultos cuidariam deles. Assim, garantia-se um equilíbrio entre a idade adulta produtiva e os dependentes (crianças e idosos) em uma cadeia de solidariedade intergeracional. Mas o que acontece quando a maioria dos adultos não tem filhos, como vem acontecendo? Nos países nórdicos, políticas públicas garantem lares dignos para idosos e saúde gratuita para a população envelhecida. O que antes era responsabilidade das famílias, agora é assegurado em escala coletiva. Nos apartamentos exíguos da família nuclear, não há espaço para os avós, mas ao menos há apoio público. Já em países como EUA, e sobretudo no Brasil, os idosos enfrentam apoio familiar declinante e políticas sociais precárias. Os asilos privados? Caríssimos e mal administrados – quando não criminosamente negligenciados. Sistemas que só visam lucro máximo não são opção de gestão adequada – pra dizer o mínimo. E a ansiedade acerca de nosso futuro quando idosos já é sentida quando estamos na meia idade. (Ladislau Dowbor. Disponível em: https://outraspalavras.net/crise-civilizatoria/ dowbor-pra-nos-tirar-da-solidao/. Acesso em 28/09/2025. Adaptado)',null,'["íntimos e descendente.", "extensos e grave.", "apertados e excludente.", "reduzidos e crescente.", "pequenos e decadente."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Língua Portuguesa','Foi empregada em sentido figurado a palavra destacada em:','Leia o texto para responder às questões de 05 a 08: Nos últimos tempos, rompeu-se o elo colaborativo entre gerações. Nas famílias tradicionais, por milhares de anos, ter filhos significava que, quando os pais envelhecessem e não pudessem mais trabalhar, os filhos adultos cuidariam deles. Assim, garantia-se um equilíbrio entre a idade adulta produtiva e os dependentes (crianças e idosos) em uma cadeia de solidariedade intergeracional. Mas o que acontece quando a maioria dos adultos não tem filhos, como vem acontecendo? Nos países nórdicos, políticas públicas garantem lares dignos para idosos e saúde gratuita para a população envelhecida. O que antes era responsabilidade das famílias, agora é assegurado em escala coletiva. Nos apartamentos exíguos da família nuclear, não há espaço para os avós, mas ao menos há apoio público. Já em países como EUA, e sobretudo no Brasil, os idosos enfrentam apoio familiar declinante e políticas sociais precárias. Os asilos privados? Caríssimos e mal administrados – quando não criminosamente negligenciados. Sistemas que só visam lucro máximo não são opção de gestão adequada – pra dizer o mínimo. E a ansiedade acerca de nosso futuro quando idosos já é sentida quando estamos na meia idade. (Ladislau Dowbor. Disponível em: https://outraspalavras.net/crise-civilizatoria/ dowbor-pra-nos-tirar-da-solidao/. Acesso em 28/09/2025. Adaptado)',null,'["Nos países nórdicos, políticas públicas garantem lares dignos para idosos... (2o parágrafo)", "... quando os pais envelhecessem e não pudessem mais trabalhar... (1o parágrafo)", "Caríssimos e mal administrados – quando não criminosamente negligenciados. (2o parágrafo)", "Nos últimos tempos, rompeu-se o elo colaborativo entre gerações. (1o parágrafo)", "E a ansiedade acerca de nosso futuro quando idosos já é sentida... (2o parágrafo)"]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Língua Portuguesa','A respeito das transformações nas formas de relacionamento interpessoal com as tecnologias digitais, o autor do texto','Leia o texto a seguir para responder às questões de 09 a 12: Assassinato digital Ao contrário de tempos passados, quando sumir com alguém exigia certo grau de dificuldade e até risco criminal, hoje tornou-se facílimo dar fim a uma pessoa. Bastam um dedo e algumas teclas. É possível mudar completamente o círculo de amizades, sumir da turma, buscar novos ares, sem grandes enfrentamentos. Um amigo estava falando de sua ex: “Bloqueei”. Explicou que bloqueou em tudo: no WhatsApp, no Instagram, no Face. Em qualquer outra rede social, uma pessoa existe ou não existe. Se é bloqueada em todos os canais em que pode se comunicar com a outra, tecnicamente não existe mais. Simplesmente deixa de estar presente. Mesmo porque, na atualidade, a presença é mais digital que física em um número imenso de casos. Houve um tempo em que eu me admirava ao dar uma “limpa” no celular. Por que tanta gente, com quem nunca converso, tantos endereços que já não fazem parte do meu dia a dia? Para meu susto, recebi reclamações: “Por que você me deletou?”, “Me bloqueou?”. Na prática, respondia: “Porque a gente não se falava mais”. Descobri que estar na minha rede mesmo sem papo era um modo de afirmar a existência da pessoa em minha vida. Portanto, era ofensivo ser excluído. Parecia sem sentido. Mas entendi. Se a pessoa for deletada ou, pior, bloqueada, simplesmente deixa de existir. A comparação é forte, mas inevitável: morre. Eu ainda acredito nas relações de carne e osso, nos abraços, nos encontros longos e profundos. Mas descubro que os relacionamentos digitais tomaram um espaço impressionante. Deletar equivale a dizer adeus. E dizer adeus é sempre uma forma de luto. (Walcyr Carrasco. Disponível em: https://veja.abril.com.br/coluna/walcyrcarrasco/assassinato-digital/. Acesso em 28/09/2025. Adaptado)',null,'["reconhece o impacto das redes sociais, mas valoriza, acima delas, as relações presenciais e concretas.", "afirma que, no passado, as relações humanas eram menos sólidas, pois não havia redes sociais para mantê-las.", "considera que o bloqueio em redes sociais não gera maiores consequências para a percepção da existência do outro.", "entende que excluir alguém das redes sociais, nos dias de hoje, é um crime mais grave do que matar uma pessoa.", "defende que as relações digitais substituíram de forma saudável e definitiva os vínculos presenciais."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Língua Portuguesa','É correto afirmar que no trecho “Deletar equivale a dizer adeus. E dizer adeus é sempre uma forma de luto” (3o parágrafo), o autor procura','Leia o texto a seguir para responder às questões de 09 a 12: Assassinato digital Ao contrário de tempos passados, quando sumir com alguém exigia certo grau de dificuldade e até risco criminal, hoje tornou-se facílimo dar fim a uma pessoa. Bastam um dedo e algumas teclas. É possível mudar completamente o círculo de amizades, sumir da turma, buscar novos ares, sem grandes enfrentamentos. Um amigo estava falando de sua ex: “Bloqueei”. Explicou que bloqueou em tudo: no WhatsApp, no Instagram, no Face. Em qualquer outra rede social, uma pessoa existe ou não existe. Se é bloqueada em todos os canais em que pode se comunicar com a outra, tecnicamente não existe mais. Simplesmente deixa de estar presente. Mesmo porque, na atualidade, a presença é mais digital que física em um número imenso de casos. Houve um tempo em que eu me admirava ao dar uma “limpa” no celular. Por que tanta gente, com quem nunca converso, tantos endereços que já não fazem parte do meu dia a dia? Para meu susto, recebi reclamações: “Por que você me deletou?”, “Me bloqueou?”. Na prática, respondia: “Porque a gente não se falava mais”. Descobri que estar na minha rede mesmo sem papo era um modo de afirmar a existência da pessoa em minha vida. Portanto, era ofensivo ser excluído. Parecia sem sentido. Mas entendi. Se a pessoa for deletada ou, pior, bloqueada, simplesmente deixa de existir. A comparação é forte, mas inevitável: morre. Eu ainda acredito nas relações de carne e osso, nos abraços, nos encontros longos e profundos. Mas descubro que os relacionamentos digitais tomaram um espaço impressionante. Deletar equivale a dizer adeus. E dizer adeus é sempre uma forma de luto. (Walcyr Carrasco. Disponível em: https://veja.abril.com.br/coluna/walcyrcarrasco/assassinato-digital/. Acesso em 28/09/2025. Adaptado)',null,'["sugerir que o luto digital é uma experiência que afeta principalmente os mais jovens, que desconhecem lutos reais.", "criticar aqueles indivíduos que não reconhecem o peso emocional dos vínculos virtuais nos dias de hoje.", "enfatizar que a exclusão digital tem valor simbólico equivalente ao rompimento definitivo de laços afetivos.", "suavizar o impacto das relações digitais, apresentando-as como menos intensas do que as presenciais.", "ilustrar que as despedidas virtuais são passageiras, visto que as pessoas não estão verdadeiramente mortas."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Língua Portuguesa','Considere os trechos do 2o parágrafo: • ... estar na minha rede mesmo sem papo era um modo de afirmar a existência da pessoa em minha vida. Portanto, era ofensivo ser excluído. • Se a pessoa for deletada ou, pior, bloqueada, simplesmente deixa de existir. É correto afirmar que os termos destacados estabe lecem, respectivamente, relações de sentido de','Leia o texto a seguir para responder às questões de 09 a 12: Assassinato digital Ao contrário de tempos passados, quando sumir com alguém exigia certo grau de dificuldade e até risco criminal, hoje tornou-se facílimo dar fim a uma pessoa. Bastam um dedo e algumas teclas. É possível mudar completamente o círculo de amizades, sumir da turma, buscar novos ares, sem grandes enfrentamentos. Um amigo estava falando de sua ex: “Bloqueei”. Explicou que bloqueou em tudo: no WhatsApp, no Instagram, no Face. Em qualquer outra rede social, uma pessoa existe ou não existe. Se é bloqueada em todos os canais em que pode se comunicar com a outra, tecnicamente não existe mais. Simplesmente deixa de estar presente. Mesmo porque, na atualidade, a presença é mais digital que física em um número imenso de casos. Houve um tempo em que eu me admirava ao dar uma “limpa” no celular. Por que tanta gente, com quem nunca converso, tantos endereços que já não fazem parte do meu dia a dia? Para meu susto, recebi reclamações: “Por que você me deletou?”, “Me bloqueou?”. Na prática, respondia: “Porque a gente não se falava mais”. Descobri que estar na minha rede mesmo sem papo era um modo de afirmar a existência da pessoa em minha vida. Portanto, era ofensivo ser excluído. Parecia sem sentido. Mas entendi. Se a pessoa for deletada ou, pior, bloqueada, simplesmente deixa de existir. A comparação é forte, mas inevitável: morre. Eu ainda acredito nas relações de carne e osso, nos abraços, nos encontros longos e profundos. Mas descubro que os relacionamentos digitais tomaram um espaço impressionante. Deletar equivale a dizer adeus. E dizer adeus é sempre uma forma de luto. (Walcyr Carrasco. Disponível em: https://veja.abril.com.br/coluna/walcyrcarrasco/assassinato-digital/. Acesso em 28/09/2025. Adaptado)',null,'["conclusão e concessão.", "conclusão e condição.", "concessão e condição.", "condição e conclusão.", "condição e concessão."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Língua Portuguesa','Considere o trecho: • Houve um tempo em que eu me admirava ao dar uma “limpa” no celular. Por que tanta gente, com quem nunca converso, tantos endereços que já não fazem parte do meu dia a dia? As expressões destacadas podem ser substituídas, respectivamente e em conformidade com a norma-padrão de emprego dos pronomes, por:','Leia o texto a seguir para responder às questões de 09 a 12: Assassinato digital Ao contrário de tempos passados, quando sumir com alguém exigia certo grau de dificuldade e até risco criminal, hoje tornou-se facílimo dar fim a uma pessoa. Bastam um dedo e algumas teclas. É possível mudar completamente o círculo de amizades, sumir da turma, buscar novos ares, sem grandes enfrentamentos. Um amigo estava falando de sua ex: “Bloqueei”. Explicou que bloqueou em tudo: no WhatsApp, no Instagram, no Face. Em qualquer outra rede social, uma pessoa existe ou não existe. Se é bloqueada em todos os canais em que pode se comunicar com a outra, tecnicamente não existe mais. Simplesmente deixa de estar presente. Mesmo porque, na atualidade, a presença é mais digital que física em um número imenso de casos. Houve um tempo em que eu me admirava ao dar uma “limpa” no celular. Por que tanta gente, com quem nunca converso, tantos endereços que já não fazem parte do meu dia a dia? Para meu susto, recebi reclamações: “Por que você me deletou?”, “Me bloqueou?”. Na prática, respondia: “Porque a gente não se falava mais”. Descobri que estar na minha rede mesmo sem papo era um modo de afirmar a existência da pessoa em minha vida. Portanto, era ofensivo ser excluído. Parecia sem sentido. Mas entendi. Se a pessoa for deletada ou, pior, bloqueada, simplesmente deixa de existir. A comparação é forte, mas inevitável: morre. Eu ainda acredito nas relações de carne e osso, nos abraços, nos encontros longos e profundos. Mas descubro que os relacionamentos digitais tomaram um espaço impressionante. Deletar equivale a dizer adeus. E dizer adeus é sempre uma forma de luto. (Walcyr Carrasco. Disponível em: https://veja.abril.com.br/coluna/walcyrcarrasco/assassinato-digital/. Acesso em 28/09/2025. Adaptado)',null,'["no qual … que … onde", "de que … com as quais … nos quais", "onde … que … os quais", "onde … de quem … nos quais", "no qual … com a qual … os quais"]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Língua Portuguesa','A partir da leitura da tira, é correto afirmar que seu efeito de humor deriva do fato de que a menina que fala','Leia a tira a seguir para responder às questões de 13 a 15: (Eduardo Arruda. Disponivel em: https://x.com/ed_arruda/ status/1894695844282093685/photo/1. Acesso em 01/10/2025)','["/pmsp/soldado-2025-11/apoio-13-15-8-1.png"]','["encara com extremo rigor uma circunstância da qual se espera divertimento.", "dissimula sua aversão ao balanço com uma postura severa frente à brincadeira.", "profere insultos às demais crianças, incitando-as a pararem de se balançar.", "irrita-se com a aversão das crianças a regras morais de comportamento.", "emprega a austeridade necessária para as crianças aprenderem a se balançar."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Língua Portuguesa','Em – Ajeitem a coluna – (1o quadro), a palavra destacada está conjugada no mesmo modo verbal que aquela destacada em:','Leia a tira a seguir para responder às questões de 13 a 15: (Eduardo Arruda. Disponivel em: https://x.com/ed_arruda/ status/1894695844282093685/photo/1. Acesso em 01/10/2025)','["/pmsp/soldado-2025-11/apoio-13-15-8-1.png"]','["É preciso que as crianças aprendam a respeitar as diferenças desde muito cedo na vida.", "Reconhecem-se as brincadeiras que são importantes para o desenvolvimento da criança.", "Para que se divertissem, as crianças deveriam ter acesso a parques públicos na cidade.", "As crianças ainda estão aprendendo, então sejam pacientes com elas, por favor.", "Nunca se sabe se as crianças conseguem fazer amizades com outras da mesma idade."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Língua Portuguesa','Assinale a alternativa redigida em conformidade com a norma-padrão de concordância.','Leia a tira a seguir para responder às questões de 13 a 15: (Eduardo Arruda. Disponivel em: https://x.com/ed_arruda/ status/1894695844282093685/photo/1. Acesso em 01/10/2025)','["/pmsp/soldado-2025-11/apoio-13-15-8-1.png"]','["Durante a nossa infância era comum brincadeiras em que se respeitava as regras do jogo.", "Haviam muitas crianças que brincavam no parque junto à professora que a acompanhava.", "Foi preciso que as crianças permanecessem no parque depois daquele fatídico intervalo.", "Comprou-se para o pátio da escola alguns brinquedos novos que foi alvo de depredação.", "Para aprender a se balançar bem, é necessário muita prudência nas primeiras tentativas."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Língua Portuguesa','De acordo com as informações texto, é correto afirmar que foi um fator determinante para o aumento dos casos de dependência de jogos de azar no Brasil, nos últimos anos,','Leia o texto a seguir para responder as questões de 16 a 19: Quando apostar vira um problema Em 2023, cerca de 28 milhões de brasileiros de 14 anos ou mais (ou 17,6% da população nesta faixa de idade) diziam ter apostado no ano anterior, segundo estudo publicado pela Universidade Federal de São Paulo (Unifesp), em parceria com o Ministério da Justiça e Segurança Pública, em abril deste ano. Entre os apostadores, 10,9 milhões apresentavam características de jogo de risco ou problemático — número equivalente a 38,6% do total de apostadores e 7,3% da população em geral. Dentro desse grupo dos apostadores problemáticos, 1,4 milhão de brasileiros apresentava um padrão de apostas compatível com o diagnóstico de transtorno do jogo, enfermidade caracterizada pelo desejo incontrolável de apostar mesmo diante de prejuízos — contingente equivalente a 5% dos jogadores e 0,8% da população total acima de 14 anos. “Há mais de 30 anos, a ciência entendeu que o cérebro não fica só dependente de substâncias químicas, mas também de comportamentos muito ativadores das áreas que processam prazer no cérebro”, diz Rodrigo Machado, psiquiatra do Programa de Transtornos do Impulso do Instituto de Psiquiatria (IPq) do Hospital das Clínicas da Universidade de São Paulo (FMUSP). Mas houve uma mudança no perfil dos jogos de azar que levou à explosão dos casos de dependência no Brasil, especialmente desde 2018. “Com a tecnologia e a extrema difusão dos cassinos online, passamos a ter cassinos no bolso 24 horas. Qualquer pessoa consegue acessar as plataformas de apostas, bets esportivas etc., quando antes você precisava se deslocar fisicamente até um determinado lugar”, afirma o especialista em jogo compulsivo. Outra mudança, diz ele, foi na própria dinâmica do jogo de azar através das plataformas digitais. Por exemplo, apostas em jogos de futebol sempre existiram, mas antes só se apostava no resultado final. Já nas plataformas de apostas, é possível fazer as chamadas “apostas in-play”, enquanto o jogo está acontecendo. “Quando você promove um ciclo ultrarrápido de apostas, você encurta a distância entre o ato de apostar e o resultado final, fazendo com que as pessoas entrem num loop de compulsividade e, consequentemente, de hiperestimulação dos centros que processam o prazer no cérebro”, afirma Machado. (Thais Carrança. Disponivel em: https://www.bbc.com/portuguese/ articles/ckgzk0g8317o. Acesso em: 01/10/2025. Adaptado)',null,'["a chegada à juventude e à vida adulta de uma população que nasceu num contexto totalmente tecnológico e cresceu envolvida com jogos eletrônicos.", "a investigação do padrão comportamental dos jogadores, o que possibilitou a identificação do diagnóstico de transtorno do jogo em milhares de apostadores.", "a propagação de inúmeras plataformas digitais de apostas, em decorrência do avanço tecnológico, que proporciona facilidade de acesso a praticamente qualquer pessoa.", "a fiscalização dos jogos de azar pelo governo federal, que acabou por evidenciar os dados que, anteriormente, sequer eram coletados.", "o aumento do número de cassinos físicos em território nacional motivado pela adesão popular decorrente do aumento de plataformas digitais."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Língua Portuguesa','Assinale a alternativa que está de acordo com a opinião expressa no texto pelo psiquiatra Rodrigo Machado.','Leia o texto a seguir para responder as questões de 16 a 19: Quando apostar vira um problema Em 2023, cerca de 28 milhões de brasileiros de 14 anos ou mais (ou 17,6% da população nesta faixa de idade) diziam ter apostado no ano anterior, segundo estudo publicado pela Universidade Federal de São Paulo (Unifesp), em parceria com o Ministério da Justiça e Segurança Pública, em abril deste ano. Entre os apostadores, 10,9 milhões apresentavam características de jogo de risco ou problemático — número equivalente a 38,6% do total de apostadores e 7,3% da população em geral. Dentro desse grupo dos apostadores problemáticos, 1,4 milhão de brasileiros apresentava um padrão de apostas compatível com o diagnóstico de transtorno do jogo, enfermidade caracterizada pelo desejo incontrolável de apostar mesmo diante de prejuízos — contingente equivalente a 5% dos jogadores e 0,8% da população total acima de 14 anos. “Há mais de 30 anos, a ciência entendeu que o cérebro não fica só dependente de substâncias químicas, mas também de comportamentos muito ativadores das áreas que processam prazer no cérebro”, diz Rodrigo Machado, psiquiatra do Programa de Transtornos do Impulso do Instituto de Psiquiatria (IPq) do Hospital das Clínicas da Universidade de São Paulo (FMUSP). Mas houve uma mudança no perfil dos jogos de azar que levou à explosão dos casos de dependência no Brasil, especialmente desde 2018. “Com a tecnologia e a extrema difusão dos cassinos online, passamos a ter cassinos no bolso 24 horas. Qualquer pessoa consegue acessar as plataformas de apostas, bets esportivas etc., quando antes você precisava se deslocar fisicamente até um determinado lugar”, afirma o especialista em jogo compulsivo. Outra mudança, diz ele, foi na própria dinâmica do jogo de azar através das plataformas digitais. Por exemplo, apostas em jogos de futebol sempre existiram, mas antes só se apostava no resultado final. Já nas plataformas de apostas, é possível fazer as chamadas “apostas in-play”, enquanto o jogo está acontecendo. “Quando você promove um ciclo ultrarrápido de apostas, você encurta a distância entre o ato de apostar e o resultado final, fazendo com que as pessoas entrem num loop de compulsividade e, consequentemente, de hiperestimulação dos centros que processam o prazer no cérebro”, afirma Machado. (Thais Carrança. Disponivel em: https://www.bbc.com/portuguese/ articles/ckgzk0g8317o. Acesso em: 01/10/2025. Adaptado)',null,'["A celeridade do ciclo das apostas é capaz de aplacar as chances de prejuízo financeiro aos apostadores.", "O ciclo acelerado de apostas costuma frustrar mais os apostadores, prejudicando sua permanência nas plataformas.", "As apostas esportivas, como as de jogos de futebol, tendem a ser menos perigosas do que outras modalidades.", "A velocidade do resultado das apostas é inversamente proporcional à estimulação de áreas cerebrais ligadas ao prazer.", "O tempo de intervalo entre a aposta e seu resultado influencia significativamente o nível de prazer e de compulsão."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Língua Portuguesa','De acordo com os dados apresentados no texto, é correto afirmar que','Leia o texto a seguir para responder as questões de 16 a 19: Quando apostar vira um problema Em 2023, cerca de 28 milhões de brasileiros de 14 anos ou mais (ou 17,6% da população nesta faixa de idade) diziam ter apostado no ano anterior, segundo estudo publicado pela Universidade Federal de São Paulo (Unifesp), em parceria com o Ministério da Justiça e Segurança Pública, em abril deste ano. Entre os apostadores, 10,9 milhões apresentavam características de jogo de risco ou problemático — número equivalente a 38,6% do total de apostadores e 7,3% da população em geral. Dentro desse grupo dos apostadores problemáticos, 1,4 milhão de brasileiros apresentava um padrão de apostas compatível com o diagnóstico de transtorno do jogo, enfermidade caracterizada pelo desejo incontrolável de apostar mesmo diante de prejuízos — contingente equivalente a 5% dos jogadores e 0,8% da população total acima de 14 anos. “Há mais de 30 anos, a ciência entendeu que o cérebro não fica só dependente de substâncias químicas, mas também de comportamentos muito ativadores das áreas que processam prazer no cérebro”, diz Rodrigo Machado, psiquiatra do Programa de Transtornos do Impulso do Instituto de Psiquiatria (IPq) do Hospital das Clínicas da Universidade de São Paulo (FMUSP). Mas houve uma mudança no perfil dos jogos de azar que levou à explosão dos casos de dependência no Brasil, especialmente desde 2018. “Com a tecnologia e a extrema difusão dos cassinos online, passamos a ter cassinos no bolso 24 horas. Qualquer pessoa consegue acessar as plataformas de apostas, bets esportivas etc., quando antes você precisava se deslocar fisicamente até um determinado lugar”, afirma o especialista em jogo compulsivo. Outra mudança, diz ele, foi na própria dinâmica do jogo de azar através das plataformas digitais. Por exemplo, apostas em jogos de futebol sempre existiram, mas antes só se apostava no resultado final. Já nas plataformas de apostas, é possível fazer as chamadas “apostas in-play”, enquanto o jogo está acontecendo. “Quando você promove um ciclo ultrarrápido de apostas, você encurta a distância entre o ato de apostar e o resultado final, fazendo com que as pessoas entrem num loop de compulsividade e, consequentemente, de hiperestimulação dos centros que processam o prazer no cérebro”, afirma Machado. (Thais Carrança. Disponivel em: https://www.bbc.com/portuguese/ articles/ckgzk0g8317o. Acesso em: 01/10/2025. Adaptado)',null,'["o número de apostadores com transtorno do jogo representa 38,6% dos que apostaram.", "a maioria dos que apostaram em 2022 foi diagnosticada com algum tipo de dependência.", "os comportamentos de jogo de risco já atingem mais de 5% da população em geral.", "menos de 10% da população brasileira acima de 14 anos realizou algum tipo de aposta em 2022.", "entre os apostadores, menos de um terço apresentou comportamento de risco ou problemático."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Língua Portuguesa','Considere as frases: • Mas houve uma mudança no perfil dos jogos de azar que levou à explosão dos casos de dependência no Brasil, especialmente desde 2018. (4o parágrafo) • “Já nas plataformas de apostas, é possível fazer as chamadas apostas ‘in-play’, enquanto o jogo está acontecendo.” (5o parágrafo) É correto afirmar, a respeito das palavras destacadas, que','Leia o texto a seguir para responder as questões de 16 a 19: Quando apostar vira um problema Em 2023, cerca de 28 milhões de brasileiros de 14 anos ou mais (ou 17,6% da população nesta faixa de idade) diziam ter apostado no ano anterior, segundo estudo publicado pela Universidade Federal de São Paulo (Unifesp), em parceria com o Ministério da Justiça e Segurança Pública, em abril deste ano. Entre os apostadores, 10,9 milhões apresentavam características de jogo de risco ou problemático — número equivalente a 38,6% do total de apostadores e 7,3% da população em geral. Dentro desse grupo dos apostadores problemáticos, 1,4 milhão de brasileiros apresentava um padrão de apostas compatível com o diagnóstico de transtorno do jogo, enfermidade caracterizada pelo desejo incontrolável de apostar mesmo diante de prejuízos — contingente equivalente a 5% dos jogadores e 0,8% da população total acima de 14 anos. “Há mais de 30 anos, a ciência entendeu que o cérebro não fica só dependente de substâncias químicas, mas também de comportamentos muito ativadores das áreas que processam prazer no cérebro”, diz Rodrigo Machado, psiquiatra do Programa de Transtornos do Impulso do Instituto de Psiquiatria (IPq) do Hospital das Clínicas da Universidade de São Paulo (FMUSP). Mas houve uma mudança no perfil dos jogos de azar que levou à explosão dos casos de dependência no Brasil, especialmente desde 2018. “Com a tecnologia e a extrema difusão dos cassinos online, passamos a ter cassinos no bolso 24 horas. Qualquer pessoa consegue acessar as plataformas de apostas, bets esportivas etc., quando antes você precisava se deslocar fisicamente até um determinado lugar”, afirma o especialista em jogo compulsivo. Outra mudança, diz ele, foi na própria dinâmica do jogo de azar através das plataformas digitais. Por exemplo, apostas em jogos de futebol sempre existiram, mas antes só se apostava no resultado final. Já nas plataformas de apostas, é possível fazer as chamadas “apostas in-play”, enquanto o jogo está acontecendo. “Quando você promove um ciclo ultrarrápido de apostas, você encurta a distância entre o ato de apostar e o resultado final, fazendo com que as pessoas entrem num loop de compulsividade e, consequentemente, de hiperestimulação dos centros que processam o prazer no cérebro”, afirma Machado. (Thais Carrança. Disponivel em: https://www.bbc.com/portuguese/ articles/ckgzk0g8317o. Acesso em: 01/10/2025. Adaptado)',null,'["“especialmente” expressa circunstância de ordem, com sentido de “primeiramente”; e “enquanto” estabelece relação de conformidade, sendo equivalente a “na qualidade de”.", "“especialmente” expressa circunstância de modo, com sentido de “particularmente”; e “enquanto” estabelece relação temporal, sendo equivalente a “durante o tempo em que”.", "“especialmente” expressa circunstância de dúvida, com sentido de “possivelmente”; e “enquanto” estabelece relação proporcional, sendo equivalente a “à medida que”.", "“especialmente” expressa circunstância de tempo, com sentido de “outrora”; e “enquanto” estabelece relação proporcional, sendo equivalente a “ao passo que”.", "“especialmente” expressa circunstância de intensidade, com sentido de “muito”; e “enquanto” estabelece relação temporal, sendo equivalente a “quando”."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Língua Portuguesa','Considere a frase: Devido facilidade de acessar as plataformas online, vem crescendo o número de brasileiros expostos atividades como as apostas, que são prejudiciais saúde mental. Assinale a alternativa que preenche, respectivamente, as lacunas, de acordo com a norma-padrão de emprego do acento indicativo de crase.',null,null,'["à … a … à", "à … à … a", "a … às … a", "à … à … à", "a … as … à"]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Matemática','Ao iniciar mais um dia de trabalho, um pequeno comércio tinha R$ 1.280,00 de dinheiro em caixa na loja. Durante esse dia, aconteceram os seguintes eventos: • Pagamento de fornecedor: R$ 675,00 • Recebimento ao realizar venda: R$ 42,00 • Recebimento ao realizar venda: R$ 67,00 • Recebimento ao realizar venda: R$ 148,00 • Recebimento ao realizar venda: R$ 95,00 • Pagamento de fornecedor: R$ 742,00 • Recebimento ao realizar venda: R$ 127,00 • Pagamento de fornecedor: R$ 159,00 Considerando que todos esses pagamentos e recebimentos foram feitos utilizando apenas o dinheiro do caixa, é correto afirmar que o saldo em caixa, após essas movimentações, foi de',null,null,'["R$ 189,00.", "R$ 183,00.", "R$ 175,00.", "R$ 192,00.", "R$ 178,00."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Matemática','O resultado do censo populacional em um município mostrou que 17.076 habitantes são pessoas do sexo feminino, representando 3/5 da população total. O censo também indicou que 1/3 das pessoas do sexo feminino do município tem menos de 30 anos de idade e que 3/8 das pessoas do sexo masculino do município têm 30 anos de idade ou mais. A Secretaria de Saúde desse município encomendou 15 mil doses de uma vacina para ser aplicada na população com menos de 30 anos de idade; logo, se todas as pessoas nessa faixa etária receberem uma dose dessa vacina, o número de doses que sobrará da encomenda será',null,null,'["4.822.", "2.268.", "2.794.", "2.193.", "5.039."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Matemática','Três amigos trabalham em empresas diferentes, e cada um deles tem uma escala de trabalho diferente. Para um deles, a escala é 2 x 1, que significa 2 dias trabalhados consecutivamente seguidos de 1 dia de folga. Para os outros dois amigos, a escala é 4 x 1 para um e 5 x 1 para o outro. Em um domingo, os três amigos tiveram folga no mesmo dia e almoçaram juntos. Combinaram que, na folga seguinte comum aos três, eles almoçariam juntos novamente, o que aconteceu em',null,null,'["uma terça-feira.", "uma quarta-feira.", "uma quinta-feira.", "uma sexta-feira.", "um sábado."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Matemática','O gerente de um escritório resolveu distribuir para três de seus funcionários os 378 processos que precisavam ser arquivados. A quantidade de processos que cada funcionário arquivará será diretamente proporcional às horas que cada um deles tem disponíveis para o trabalho, sendo que um deles dispõe de 3 horas, outro dispõe de 5 horas e outro dispõe de 6 horas. Distribuídos dessa maneira, a quantidade somada de processos que os dois funcionários com menos horas disponíveis receberão para arquivar supera a quantidade a ser recebida pelo outro funcionário em',null,null,'["65.", "70.", "58.", "54.", "48."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Matemática','Sabe-se que o preço de um produto na loja A é o triplo do preço do mesmo produto na loja B. O lojista da loja A aplicou um desconto de x% no preço desse produto, o lojista da loja B aplicou um aumento também de x% no preço desse produto, e, após esses reajustes, o novo preço da loja A passou a ser o dobro do novo preço da loja B. Com essas informações, é correto afirmar que o valor de x é',null,null,'["25.", "10.", "30.", "15.", "20."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Matemática','Para executar uma tarefa, três funcionários gastaram 3 horas e 15 minutos. No dia seguinte, foram destacados cinco funcionários para executar a mesma tarefa. Esses cinco funcionários possuem a mesma capacidade de trabalho que os anteriores. Dessa maneira, é correto afirmar que o tempo a menos que esses 5 funcionários gastaram para executar a tarefa foi de',null,null,'["1 hora e 57 minutos.", "1 hora e 35 minutos.", "1 hora e 18 minutos.", "1 hora e 43 minutos.", "1 hora e 22 minutos."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Matemática','Para ter acesso à última prova de uma gincana, os componentes de cada equipe devem abrir um determinado envelope numerado que está em uma caixa na qual há 50 envelopes numerados, respectivamente, de 1 a 50. Para obter o número correto e abrir o envelope, é necessário calcular o valor numérico da seguinte expressão: 2 · J + 7 · K + 7 · L – M Os valores das letras utilizadas na expressão podem ser obtidos por meio da resolução dos seguintes sistemas de equações: O número do envelope correto é','Sistemas de equações:
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Matemática','A tabela a seguir mostra exemplos de 4 famílias, relacionando os ganhos mensais e os gastos mensais de cada uma com alimentação. Tabela de ganhos e gastos com alimentação - mensal Família Ganhos (R$) Gastos (R$) A 1.800,00 480,00 B 2.600,00 520,00 C 4.500,00 740,00 D 8.100,00 1.120,00 Seja R a média aritmética simples dos ganhos mensais dessas quatro famílias e seja T a média aritmética simples dos gastos com alimentação. Em comparação com R, o valor de T equivale a uma porcentagem mais próxima de',null,null,'["16%", "18%", "17%", "15%", "19%"]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Matemática','Após uma denúncia, a polícia encontrou em um depósito três vasilhames contendo azeite adulterado. Cada vasilhame continha 56 litros desse azeite, que seriam envasados em vasilhames de 350 mL. Sendo V o número de vasilhames de 350 mL necessários para envasar todo esse azeite, a soma dos algarismos de V é igual a',null,null,'["8.", "11.", "13.", "12.", "9."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Matemática','Um terreno retangular precisa ser vasculhado detalhadamente à procura de indícios de atividades ilícitas. Esse terreno tem 1,2 km de comprimento e 0,9 km de largura e será dividido em 300 quadrados de mesma área para facilitar o trabalho da polícia. A medida do lado de cada um desses 300 quadrados é',null,null,'["48 m.", "55 m.", "72 m.", "60 m.", "35 m."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Matemática','O gráfico a seguir deveria mostrar apenas os valores arrecadados por quatro pessoas em uma campanha de solidariedade: Distribuição da arrecadação (R$) 81º 182 49 141 Fabiana Luiz Mateus Cristina No entanto, a informação registrada no setor circular do gráfico que corresponde a Cristina não é do quanto ela arrecadou, mas sim de que esse setor tem 81o de abertura. A partir dos dados disponíveis, a diferença entre o valor arrecadado por Cristina e o valor arrecadado por Mateus é igual a',null,'["/pmsp/soldado-2025-11/q31-20-figura-1.png"]','["48.", "52.", "45.", "63.", "59."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Matemática','O perímetro desse terreno é igual a','Utilize as informações a seguir para responder às questões 32 e 33: O polígono ABCDEFG a seguir, desenhado fora de escala, representa um terreno. Os pontos H, I e J representam pontos fora do terreno tais que AHIJ é um retângulo. São conhecidas as seguintes medidas, em metros: AB = 16; BH = 24; HC = 7; CD = 15; DI = 8; IE = 15; EF = 22; FJ = 3; JG = 4; GA = 26. A B H C G D J F E I','["/pmsp/soldado-2025-11/apoio-32-33-20-1.png"]','["126 m.", "101 m.", "104 m.", "109 m.", "121 m."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Matemática','Qual é a área desse terreno?','Utilize as informações a seguir para responder às questões 32 e 33: O polígono ABCDEFG a seguir, desenhado fora de escala, representa um terreno. Os pontos H, I e J representam pontos fora do terreno tais que AHIJ é um retângulo. São conhecidas as seguintes medidas, em metros: AB = 16; BH = 24; HC = 7; CD = 15; DI = 8; IE = 15; EF = 22; FJ = 3; JG = 4; GA = 26. A B H C G D J F E I','["/pmsp/soldado-2025-11/apoio-32-33-20-1.png"]','["1.038 m²", "1.116 m²", "1.160 m²", "1.056 m²", "1.050 m²"]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Matemática','A sequência a seguir foi criada com um padrão lógico matemático: 5, 5, 10, 20, 60, 10, 10, 20, 40, 120, 15, 15, 30, 60, 180, 20, 20, 40, ... Seja J o 35o elemento dessa sequência, K o 44o elemento e L o 51o elemento. O valor numérico da expressão J – K – L é igual a',null,null,'["175.", "180.", "170.", "185.", "165."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Matemática','Considere que as afirmações a seguir são verdadeiras: I. Todo jogador de futebol é um atleta. II. Há pessoas que gostam de música e que são jogadores de futebol. A partir dessas informações, é logicamente correto concluir que',null,null,'["há algum atleta que gosta de música.", "não há pessoa que seja jogador de futebol e goste de música.", "os atletas que gostam de música não são jogadores de futebol.", "todo atleta gosta de música.", "qualquer pessoa que gosta de música é um atleta."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Conhecimentos Gerais','Em relação às trincheiras na Primeira Guerra Mundial, é correto afirmar que','Leia o texto a seguir: Quando falamos da Primeira Guerra Mundial, falamos muito sobre as batalhas, os novos armamentos, as estratégias militares, as origens e os desdobramentos do conflito. Isso tudo é muito importante. Mas precisamos falar mais da vida cotidiana, da história social, explorar a vida e os sentimentos dos soldados que participaram dos combates. Eles têm muito a dizer, e a partir dessas falas podemos compreender melhor as nuances da Grande Guerra. Mais do que um sistema de posição e fortificação, as trincheiras eram um ecossistema cultural, extremamente dinâmico e complexo. (Bruno Leal, em “A vida cotidiana nas trincheiras da Primeira Guerra Mundial”, Boletim Café História. Disponível em: https://cafehistoria.substack.com/p/ a-vida-cotidiana-nas-trincheiras. Adaptado)',null,'["surgiram a partir das convenções de guerra, que estabeleceram limites para os conflitos entre os exércitos e a população civil e restringiram o enfrentamento armado à linha de frente da guerra, reduzindo drasticamente a mortalidade dos civis.", "revelaram as ambiguidades da guerra, pois expressavam, ao mesmo tempo, o ódio nacionalista dos militares e o reconhecimento empático entre soldados de exércitos rivais, como no caso da trégua de Natal de 1914.", "se restringiram aos combates de guerra ocorridos fora do continente europeu, especialmente na África e na Ásia, enquanto o conflito na Europa ficou marcado pelo avanço por terra da Alemanha em relação à França.", "se constituíram como um espaço privilegiado de representação dos interesses nacionais de cada país envolvido no conflito, tendo em vista a participação equânime de todas as classes sociais na linha de frente da guerra.", "marcaram a última grande guerra antes do desenvolvimento tecnológico da indústria bélica, em um conflito caracterizado pela utilização de armas não automáticas e pela inexistência de granadas ou bombardeios aéreos."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Conhecimentos Gerais','O expansionismo alemão apresentado no trecho está relacionado','Leia o texto a seguir: No dia 1o de setembro de 1939, as Forças Armadas da Alemanha nazista cruzaram a fronteira polonesa sob as ordens de Hitler. Essa agressão sem declaração de guerra marcou o início da Segunda Guerra Mundial. Hitler justificou a invasão como Guerra Defensiva, acusando os poloneses de terem iniciado o conflito contra os alemães. Na verdade, o exército alemão usou de estratagemas para acusar os poloneses de terem iniciado o ataque à Alemanha. (Joelza Ester Domingues, “Início da Segunda Guerra Mundial”, Ensinar História. Disponível em: https://ensinarhistoria.com.br/ linha-do-tempo/inicio-da-segunda-guerra-mundial-2/. Adaptado)',null,'["ao eixo Roma-Berlim, acordo firmado entre a Itália fascista e a Alemanha nazista que garantia aos italianos o controle de parte dos territórios no leste europeu que fossem conquistados pelo Terceiro Reich ao longo da década de 1930.", "à ambição nazista de enfrentar a União Soviética, reconhecida como a principal inimiga do Terceiro Reich, o que permitiria à Alemanha derrotar o comunismo e se expandir para o leste sem enfrentar as potências capitalistas ocidentais.", "ao final da Primeira Guerra Mundial, quando a Alemanha teve o seu território dividido em duas partes em razão da criação do estado nacional polonês e da abertura de um corredor que permitia o acesso da Polônia ao mar Báltico.", "à política antissemita da Alemanha, na medida em que o povo polonês era majoritariamente pertencente ao povo judeu, o que contribuiria para o projeto nazista de explorar a mão de obra judaica escravizada e depois exterminar os judeus.", "ao acordo estabelecido entre a Alemanha, a Inglaterra e a França depois da anexação da Áustria e da Tchecoslováquia pelos nazistas, quando as potências ocidentais concordaram em aceitar o expansionismo do Terceiro Reich para o leste europeu."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Conhecimentos Gerais','A cerimônia a que o texto faz referência','Leia o texto a seguir: Getúlio Vargas mandou realizar a cerimônia da queima das bandeiras estaduais, que teve lugar no Rio de Janeiro. Nessa cerimônia, foram hasteadas vinte e uma bandeiras nacionais em substituição às vinte e uma bandeiras estaduais que foram incineradas numa grande pira erguida no meio da praça, ao som do Hino Nacional tocado por várias bandas e cantado por milhares de colegiais, sob a regência do maestro Heitor Villa-Lobos. (Luís Nassif, “A cremação das bandeiras estaduais...”, Jornal GGN. Disponível em: https://jornalggn.com.br/historia/a-cremacao-das- -bandeiras-estaduais-no-estado-novo/. Adaptado)',null,'["evidenciou a importância da política de desenvolvimento econômico nacional levada adiante pelo governo Vargas, no momento em que Getúlio anunciava a criação da Petrobrás e da Vale do Rio Doce.", "simbolizou o enfraquecimento dos poderes locais, regionais e estaduais e coincidiu com o início do Estado Novo, regime ditatorial marcado pela centralização política e pelo discurso nacionalista.", "marcou a resposta imediata do governo ao movimento comunista de 1935, reforçando os símbolos nacionais com o objetivo de combater as influências do internacionalismo soviético em solo nacional.", "representou o momento em que o Brasil decidiu ingressar na Segunda Guerra Mundial ao lado dos Aliados, fazendo uso de um forte discurso nacionalista para mobilizar a população contra o nazifascismo.", "ocorreu no início da Era Vargas, quando Getúlio tentou a conciliação com as elites estaduais derrotadas em 1930, ainda que o fracasso dessa política tenha culminado na Revolução Constitucionalista de 1932."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Conhecimentos Gerais','Ainda que tenha reforçado direitos políticos, a Constituição de 1946 não assegurou o voto','Leia o texto a seguir: As Constituições de 1934 e de 1946 marcaram períodos democráticos no país. A Carta de 1934 dava amplos poderes aos Estados e assegurava preponderância do Poder Legislativo. A de 1946, elaborada após o período autoritário do Estado Novo, reforçou direitos individuais e políticos e estabeleceu independência dos Poderes Judiciário e Legislativo e separação entre igreja e Estado. (Agência Senado, “Constituições de 1934 e de 1946 marcam períodos democráticos”. Disponível em: https://www12.senado.leg.br/noticias/ videos/2023/04/constituicoes-de-1934-e-de-1946-marcam-periodosdemocraticos. Adaptado)',null,'["das mulheres.", "obrigatório.", "secreto.", "dos analfabetos.", "direto."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Conhecimentos Gerais','O movimento citado no texto foi','Leia o texto a seguir: Criado em 1973, a partir dos Clubes de Mães e das Comunidades Eclesiais de Base (CEB) da Igreja Católica na periferia sul de São Paulo, o Movimento do Custo de Vida (MCV) incorporou outras forças políticas, cresceu em número e articulação e, em 1978, colocou nas ruas mais de 20 mil pessoas, em um ato público realizado na Praça da Sé, em pleno período militar. (José Tadeu Arantes, “Estudo resgata a história do movimento do Custo de Vida”, Agência Fapesp. Disponível em: https://agencia.fapesp.br/estudoresgata-a-historia-do-movimento-do-custo-de-vida/26791. Adaptado)',null,'["um desdobramento da estratégia da esquerda armada, que manteve a guerrilha e adentrou os movimentos sociais, passando a influenciá-los.", "uma mobilização das lideranças políticas do MDB em busca de base social, com o objetivo de derrotar o regime militar nas urnas e ampliar a oposição.", "o resultado do enfraquecimento das lutas de oposição na política institucional, o que levou os trabalhadores a construírem alternativas populares.", "uma consequência da política econômica do período do milagre, que resultou em retração econômica e decrescimento do PIB.", "a resposta a um processo inflacionário que corroía o poder aquisitivo das camadas populares, sem que houvesse a contrapartida de elevações salariais."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Conhecimentos Gerais','O contexto político em questão resultou','Leia o texto a seguir: Tancredo Neves apoiou a campanha das Diretas Já, pela volta da eleição direta para presidente, porém entendia que o caminho viável para vitória da oposição seria o voto indireto no colégio eleitoral, conforme relatou em 1983 ao Jornal do Brasil: “A campanha pelas diretas é necessária, mas lírica. E o PMDB necessita instrumentalizar-se para a negociação possível”. (Guilherme Mazui e outros, “Há 40 anos morria Tancredo Neves, peça-chave da redemocratização”, G1. Disponível em: https://g1.globo.com/politica/ noticia/2025/04/21/ha-40-anos-morria-tancredo-neves-presidente-que-naotomou-posse-mas-virou-peca-chave-da-redemocratizacao.ghtml. Adaptado)',null,'["na derrota da emenda das Diretas Já no Congresso e na eleição indireta de Tancredo Neves como o primeiro presidente civil depois de 21 anos de regime militar.", "na eleição direta de Tancredo à presidência, ainda que a esquerda tivesse alguma desconfiança em relação ao candidato, considerado muito conservador.", "no fracasso das negociações entre Tancredo e os militares, o que empurrou o político mineiro para uma base social de esquerda em busca de voto e apoio.", "na perseguição dos militares a Tancredo, na medida em que ele se tornou o principal líder da oposição ao regime militar, o que resultou na cassação de seus direitos políticos.", "na ampliação das lutas sociais que fortaleceram o apoio à candidatura de Tancredo Neves, transformando-o no primeiro presidente civil a cumprir o mandato desde o início do regime militar."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Conhecimentos Gerais','Em 1949, durante o contexto da Guerra Fria, foi criada uma aliança militar que reunia países capitalistas liderados pelos Estados Unidos, com o objetivo de garantir defesa mútua contra possíveis ataques do bloco socialista. Após o fim da Guerra Fria, essa aliança passou por reestruturações e ampliou sua área de atuação, incluindo intervenções em diferentes partes do mundo. O texto faz referência',null,null,'["à Organização do Tratado de Segurança Coletiva.", "à Organização Mundial do Comércio.", "à Organização do Tratado do Atlântico Norte.", "à Organização das Nações Unidas.", "ao Pacto de Varsóvia."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Conhecimentos Gerais','Fenômeno essencial para a manutenção da vida na Terra, que consiste na retenção de grande parte do calor irradiado pela superfície terrestre nas partículas de gases presentes na atmosfera, que absorvem a radiação infravermelha emitida pela Terra, impedindo que todo esse calor se dissipe para o espaço. O conceito apresentado refere-se',null,null,'["ao aquecimento global.", "ao efeito estufa.", "à inversão térmica.", "ao saldo de radiação de onda curta.", "à camada de ozônio."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Conhecimentos Gerais','O processo histórico que marcou a transição do trabalho escravo para o sistema de colonato e impulsionou a reorganização fundiária, especialmente com a ocupação de áreas do Sul do Brasil por imigrantes camponeses europeus, está associado com',null,null,'["a expansão pecuária no Centro-Sul.", "a expansão cafeeira nos séculos XIX e início do XX.", "o surto industrial brasileiro da Era Vargas.", "o ciclo do ouro no século XVIII.", "o ciclo da borracha na Amazônia."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Conhecimentos Gerais','Corresponde ao tamanho das áreas produtivas de terra e de mar necessárias para gerar produtos, bens e serviços que sustentam determinados estilos de vida. Em outras palavras, trata-se de uma forma de traduzir, em hectares (ha), a extensão de território que uma pessoa ou toda uma sociedade utiliza, em média, para se sustentar. É, ainda, considerada uma metodologia de contabilidade ambiental que avalia o impacto do consumo sobre os recursos naturais. O texto aborda o conceito de',null,null,'["capacidade de carga ambiental.", "desenvolvimento sustentável.", "biocapacidade.", "pegada ecológica.", "sustentabilidade ambiental."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Conhecimentos Gerais','A floresta é responsável pela geração, por meio do processo de evapotranspiração, de grande parte da umidade disponível nela. Parte dessa umidade é carregada pelos ventos, provocando chuvas nos biomas Cerrado e Pantanal. Esse processo é também conhecido como',null,null,'["zona de convergência intertropical.", "aquíferos porosos.", "linhas de instabilidade.", "ciclo hidrológico local.", "rios voadores."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Conhecimentos Gerais','Região de aproximadamente 400 mil quilômetros quadrados de área, sujeita a climas subtropicais úmidos de planaltos com invernos relativamente brandos. Em sua acepção mais ampla, coincide com o setor do Planalto Meridional brasileiro. O texto refere-se ao domínio morfoclimático:',null,null,'["araucárias.", "caatinga.", "mares de morros.", "amazônico.", "cerrado."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Conhecimentos Gerais','Entre os pilares do Plano Brasileiro de Inteligência Artificial está o de','O Ministério da Ciência, Tecnologia e Inovação publicou em junho de 2025 a versão final do Plano Brasileiro de Inteligência Artificial, que estabelece as diretrizes para o desenvolvimento ético e sustentável da inteligência artificial no país até 2028. O plano prevê R$ 23,03 bilhões em investimentos públicos e privados, distribuídos entre ações de curto prazo e programas estruturantes de médio e longo prazo. (telesintese. Disponível em: https://shre.ink/oN7C. Adaptado)',null,'["concentrar a pesquisa em inteligência artificial no setor militar.", "permitir a livre exploração de dados pessoais por empresas estrangeiras.", "garantir a soberania tecnológica nacional com inclusão social.", "promover a substituição de empregos humanos por sistemas autônomos.", "ampliar o uso de sistemas automatizados desconsiderando impactos ambientais."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Conhecimentos Gerais','Com base nas informações apresentadas nos dois textos, o resultado mostrado na tabela expressa uma','Observe a tabela a seguir, elaborada a partir de dados do Instituto Nacional de Pesquisas Espaciais (INPE), acerca do número de queimadas no Brasil, e leia o texto: Texto 1 Comparativo histórico Queimadas em agosto 2025 18 451 2024 68 635 2023 28 054 2022 47 507 2021 51 711 2020 50 694 2013 21 410 (recorde anterior) (Gov. Disponível em: https://shre.ink/oi6z. Adaptado) Texto 2 O Governo Federal afirma o aumento anual de 26% no número de brigadistas de órgãos federais, a ampliação em 75% da capacidade de transporte de agentes e a assinatura do decreto no 12.189, que aumenta as punições por incêndios florestais no país. (CNN. Disponível em: https://shre.ink/oAgV. Adaptado)',null,'["queda abrupta nas atividades agrícolas que costumam usar fogo controlado.", "subnotificação forçada de incêndios por pressão política em regiões remotas.", "mudança no regime de chuvas, cujo aumento recorde reduziu os focos de queimadas.", "redução temporária das queimadas em razão do aumento de atividades agropecuárias.", "efetividade ampliada nas ações de prevenção e combate ao fogo no país."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Conhecimentos Gerais','Entre as causas que contribuíram para o avanço dessa doença, encontram-se','O Brasil responde por quase 96% dos casos de chikungunya confirmados neste ano nas Américas, segundo dados divulgados pela Organização Mundial da Saúde (OMS). O País também contabiliza cerca de 72% das mortes pela doença no mundo. A OMS relaciona o avanço da doença impulsionada pela urbanização desordenada, falta de saneamento, falhas em programas de controle dos vetores e pelas mudanças climáticas. (CNN. Disponível em: https://shre.ink/oF67. Adaptado)',null,'["a poluição atmosférica, o crescimento industrial e a escassez de recursos hídricos.", "a urbanização desordenada, a falta de saneamento básico e o aumento do comércio internacional.", "a expansão das áreas rurais, o uso de pesticidas e a criação extensiva de gado.", "o desmatamento amazônico, o aumento da exportação de commodities e a redução da umidade do ar.", "o excesso de chuvas, o uso de agrotóxicos e a concentração de atividades agrícolas."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,51,'Noções de Informática','Em uma planilha de escala de serviço no MS-Excel 2016 (versão em português brasileiro), a coluna A contém o identificador do policial, a coluna B contém as horas cumpridas pelo policial no mês, em formato numérico, e a coluna C indica o pelotão (“A”, “B” ou “C”). A primeira linha contém o cabeçalho das colunas (A1:C1) e os dados estão completamente preenchidos no intervalo de células A2:C31, sendo que cada uma das 30 linhas representa um policial diferente. O comandante pede a quantidade de policiais do pelotão A que cumpriram 160 horas ou mais no mês e o soldado decide usar uma fórmula em E2. Considerando o separador ponto e vírgula (;) no Excel em pt-BR, qual fórmula atende ao pedido sem criar colunas auxiliares?',null,null,'["=CONT.SE(C2:C31; A )", "=CONT.VALORES(B2:B31; A )", "=SE(C2:C31= A ;B2:B31>=160)", "=CONT.SES(C2:C31; A ;B2:B31; >=160 )", "=SOMASE(B2:B31; >=160 )"]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,52,'Noções de Informática','Para enviar fotos de local de ocorrência ao setor de inteligência, o soldado criou uma nova mensagem no aplicativo de desktop MS-Outlook 2016, em sua configuração padrão, e clicou em Anexar arquivo, localizando D:\Operacionais\ Fotos*.jpg. Ele selecionou três fotos de 9 MB cada, totalizando 27 MB de anexos. O servidor de e-mail da corporação possui uma política que define o limite máximo de tamanho de mensagem em 25 MB. Com base nesse cenário, o que acontece quando o usuário clicar no botão “Enviar”?',null,null,'["A mensagem é dividida automaticamente em múltiplas mensagens menores.", "O e-mail é enviado normalmente, mas os anexos acima do limite são removidos automaticamente.", "O Outlook converte automaticamente as imagens para o formato .png para reduzir o tamanho.", "O setor de inteligência não recebe a mensagem devido ao tamanho dos anexos exceder o limite permitido.", "As imagens são automaticamente compactadas pelo Outlook em .jpeg para caber no limite."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,53,'Noções de Informática','No Microsoft Word 2016 (em português do Brasil), um soldado está editando um relatório fotográfico com 12 imagens. As legendas das figuras foram inseridas por meio do comando Referências → Inserir legenda, e um Índice de Ilustrações foi criado ao final do documento. A opção “Controlar Alterações” (Rastrear Alterações) está desativada e não existem campos em cabeçalhos, rodapés, notas de rodapé ou caixas de texto. Após mover duas imagens de posição, o usuário percebe que a numeração das legendas automáticas e o Índice de Ilustrações ficaram desatualizados. Para atualizar todas as legendas automáticas e o Índice de Ilustrações, o usuário deve pressionar para selecionar todo o conteúdo do corpo do documento, depois pressionar para atualizar todos os campos selecionados e, por fim, clicar sobre o Índice de Ilustrações e escolher Atualizar índice inteiro. Assinale a alternativa que preenche, correta e respectivamente, as lacunas do enunciado.',null,null,'["Ctrl+Shift+End … F5", "Ctrl+E ... F9", "Ctrl+A ... F9", "Ctrl+U ... F5", "Ctrl+S … F5"]'::jsonb,'A/B/C/D/E','Questão anulada no gabarito definitivo.' from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,54,'Noções de Informática','O soldado precisa imprimir a página de um mapa on-line com rotas de deslocamento e quer checar o layout antes de gastar papel e tinta. Ele acessa o site institucional (via URL https://…) no navegador Google Chrome (Versão 141.0.7390.108 - 64 bits) em um computador com sistema operacional Windows, em configuração padrão. Nos navegadores modernos, existe um atalho de teclado que abre diretamente a interface de impressão com visualização prévia automática do documento, permitindo verificar como o conteúdo será impresso no papel e ajustar configurações como Orientação e Margens antes de enviar para a impressora física. Nesse contexto, qual atalho de teclado o soldado deve utilizar para acessar diretamente a interface padrão de impressão com visualização prévia no Google Chrome?',null,null,'["Ctrl+P", "Ctrl+F", "Ctrl+S", "Ctrl+N", "Ctrl+I"]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,55,'Noções de Informática','Durante a preparação de uma apresentação sobre as atividades do departamento, o usuário criou um slide no MS-PowerPoint 2016, em sua configuração padrão, com uma única caixa de texto contendo três parágrafos: “Ensino”, “Pesquisa” e “Extensão”. Ele aplica o efeito “Aparecer” (guia Animações) à caixa de texto e define “Iniciar”: “Ao clicar”. Para que cada parágrafo dessa mesma caixa de texto seja animado individualmente, um por clique, o assistente deve clicar no botão , na guia “Animações”, e configurar a animação do texto como “Por Parágrafo”. Assinale a alternativa que preenche corretamente a lacuna do texto.',null,null,'["Mais Trajetórias de Animação", "Gatilho", "Copiar Animação", "Opções de Efeito", "Adicionar Animação"]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,56,'Noções de Administração Pública','Diante da instauração de uma grave crise nacional de segurança pública impulsionada pela atuação de uma máfia, a Presidência da República, por meio do Ministério da Defesa, avalia a possibilidade do acionamento das forças auxiliares e reserva para apoiar o Exército Brasileiro na atuação terrestre. Caso sejam acionadas, além das polícias militares, o exército poderá contar também com',null,null,'["as guardas metropolitanas.", "os corpos de bombeiros militares.", "as polícias civis.", "a polícia federal.", "as polícias penais."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,57,'Noções de Administração Pública','Após sentença transitada em julgado, um oficial da Polícia Militar foi condenado na Justiça comum à pena privativa de liberdade por dois anos. Posteriormente, por meio de decisão do Tribunal de Justiça Militar do Estado, esse mesmo oficial foi julgado indigno do oficialato. Dada essa situação, o oficial militar',null,null,'["perderá o posto, mas não a patente, pois já recebeu como punição a privação da liberdade.", "não perderá nem o posto nem a patente, pois foi condenado pela Justiça comum.", "perderá a patente, mas não o posto, pois a condenação à pena privativa de liberdade foi inferior a três anos.", "não perderá nem o posto nem a patente, pois não cabe ao Tribunal de Justiça Militar do Estado essa decisão.", "perderá o posto e a patente, uma vez que os elementos necessários para tanto estão presentes."]'::jsonb,'A/B/C/D/E','Questão anulada no gabarito definitivo.' from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,58,'Noções de Administração Pública','Recentemente, em solenidade na Academia de Polícia Militar do Barro Branco, na capital paulista, o Governo do Estado de São Paulo oficializou a troca do Comando Geral da Polícia Militar. Para a nomeação a esse cargo, o oficial do Quadro de Oficiais Policiais Militares',null,null,'["pode estar na ativa ou na reserva.", "precisa ter experiência prévia como Chefe da Casa Militar.", "deve ocupar o último posto do referido quadro.", "requer aprovação em escrutínio entre seus pares.", "necessariamente integra o Tribunal de Justiça Militar Estadual."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,59,'Noções de Administração Pública','Os direitos e garantias fundamentais, nos quais estão incluídos os direitos e deveres individuais e coletivos e os direitos políticos, são um conjunto de preceitos que buscam assegurar a dignidade da pessoa humana e que estão presentes na Constituição Federal brasileira de 1988. Frente ao exposto, é correto afirmar que',null,null,'["o conscrito pode alistar-se como eleitor, mas não como elegível, durante o período do serviço militar obrigatório.", "é assegurada a prestação de assistência religiosa nas entidades civis, mas não militares, de internação coletiva.", "é plena a liberdade de associação de caráter paramilitar, desde que tenha como objetivo fins lícitos.", "é admitida prisão em caso de transgressão militar sem flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente.", "a ação de grupo armado militar contra a ordem constitucional e o Estado Democrático, apesar de ser um crime inafiançável, é prescritível."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,60,'Noções de Administração Pública','Por meio da plataforma Fala.SP, um cidadão apresentou pedido de acesso a informações de interesse público destinadas à Polícia Militar do Estado de São Paulo. Dentro do prazo legal, o pedido formulado por esse cidadão foi indeferido pelo órgão militar. No inteiro teor de decisão de negativa de acesso, verificou-se que a disponibilização das informações requeridas comprometeria atividades de inteligência, bem como de investigação ou fiscalização em andamento, relacionadas com a prevenção de infrações. Como consequência desse motivo, as informações requeridas apresentavam graus de sigilo ultrassecreto, secreto e reservado, o que corresponde, respectivamente, aos seguintes prazos máximos:',null,null,'["25, 20 e 15 anos.", "20, 15 e 10 anos.", "25, 15 e 5 anos.", "20, 10 e 5 anos.", "25, 10 e 5 anos."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-11' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exams(slug,title,source,year) values ('pmsp-soldado-2025-02','PM São Paulo · Soldado · 2025 · 16/02/2025','pmerj','2025') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Língua Portuguesa','Há uma série de palavras que correspondem a frases, em suas situações comunicativas. Assinale a palavra que mostra convencionalmente uma frase equivalente.',null,null,'["Perigo! / aviso de trabalho na estrada.", "Fogo! / ordem para parar de atirar.", "Devagar! / conselho para dirigir lentamente.", "Chega! / aviso de chegada a algum lugar.", "Depressa! / pedido de ajuda."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Língua Portuguesa','As frases a seguir mostram um termo sublinhado que foi substituído por outro termo de valor pejorativo. Assinale a opção em que isso não ocorre.',null,'["/pmsp/soldado-2025-02/q2-0-figura-1.png"]','["Suas roupas eram de outro país / seus trajes.", "Seus pés tinham mau cheiro / fedor.", "O quarto se mostrava desarrumado / bagunçado.", "Ele não pôde escapar de suas mãos / garras.", "A capa do livro ficou pegajosa / grudenta."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Língua Portuguesa','A subjetividade é particularmente expressa pelos pronomes de primeira pessoa. Assinale a frase em que outro pronome se encarrega da subjetividade, equivalente aos pronomes de primeira pessoa.',null,null,'["Na Idade Média, preferia-se o campo à cidade.", "Afinal de contas, vai-se ao teatro ou não?", "Então, você vai participar do concurso?", "O ministro tem a honra de convidá-lo para o cargo.", "Os cidadãos honestos, esses devem enfrentar a realidade."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Língua Portuguesa','As frases a seguir foram reescritas de forma a se eliminarem delas as marcas de subjetividade do emissor. Assinale a frase em que isso foi realizado de forma inadequada.',null,null,'["A televisão mostrou o triste fim de um episódio lamentável / A televisão mostrou o fim do episódio.", "A deplorável atitude do árbitro prejudicou a boa partida / A atitude do árbitro prejudicou a partida.", "Infelizmente, a atriz, inadequada para o papel, continua na peça interessante / Infelizmente a atriz continua na peça.", "Marcos emocionou-se com aquelas belas palavras / Marcos emocionou-se com aquelas palavras.", "A paisagem, romântica e agreste, estava mudando / A paisagem estava mudando."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Língua Portuguesa','Nas opções a seguir, as frases iniciais foram desenvolvidas de forma a explicitar a informação. Assinale aquela em que o desenvolvimento não tem essa função.',null,null,'["O congresso será realizado entre os dias 25 e 30 de agosto / O congresso de literatura francesa será realizado entre os dias 25 e 30 de agosto.", "O deputado apresentou um projeto de lei / O deputado Francisco Mendes apresentou um projeto de lei sobre a adoção de crianças.", "A rua tinha ficado cheia de crianças / A rua, entre as avenidas principais do bairro, tinha ficado cheia de crianças.", "A lagoa Rodrigo de Freitas está situada no Rio de Janeiro / A lagoa Rodrigo de Freitas e a praia de Copacabana estão situadas no Rio de Janeiro.", "O pianista interpretou uma sonata / O pianista interpretou uma sonata de um moderno músico francês."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Língua Portuguesa','Assinale a frase que mostra a presença de antônimos.',null,null,'["Em certa idade da vida, se sua casa não se encher de crianças, ela se encherá de manias e de vícios.", "Às vezes você precisa conhecer alguém muito bem para saber que vocês não se conhecem.", "O suicídio foi a melhor cousa que ele fez enquanto vivo.", "Ganhei o prêmio porque os outros indicados já morreram.", "Seja a vida longa ou curta, depende completamente para que ela serviu."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Língua Portuguesa','As frases a seguir mostram termos sublinhados e desses termos foram mostrados sinônimos. Assinale a frase em que o sinônimo indicado está incorreto.',null,null,'["Gatos são peritos em conforto. / especialistas.", "É praticamente impossível olhar para um pinguim e sentir raiva. / objetivamente.", "Um cão nunca demonstra intolerância quando escolhe um dono. / rejeição.", "Vimos até pegadas de onça, mas felizmente não chegamos a encarar a fera. / enfrentar.", "Não acho justo que minha cachorrinha ande solta por aí. / correto."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Língua Portuguesa','Observe as duas frases a seguir. 1. O policial entrou na viatura. 2. A viatura policial era nova. Nessas frases a palavra “policial” pertence a duas classes diferentes (substantivo e adjetivo). O mesmo acontece com as palavras sublinhadas nas seguintes frases:',null,null,'["A roupa do mendigo estava suja. / O mendigo tinha pouca roupa.", "Era um povoado tranquilo. / O povo tranquilo do povoado estava presente na festa.", "Os mortais são impacientes. / Nós, mortais, somos impacientes.", "A máquina de costura estava na sala. / Estava na cozinha a máquina de café.", "Todos somos brasileiros. / Eu sou brasileiro do Ceará."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Língua Portuguesa','Assinale a frase cuja pontuação está inteiramente correta.',null,null,'["Uma sociedade, sem religião é como um navio, sem bússola.", "A noite é uma bela crença, na luz.", "Nenhum homem chegou a ser grande senão impelido, por divina inspiração.", "Algumas das maiores dádivas de Deus são preces, não atendidas.", "Ensina-me a vencer, se puderes."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Língua Portuguesa','Assinale a frase em que o emprego do acento grave indicativo da crase está correto.',null,null,'["Meu objetivo principal na vida é fazer às pessoas felizes.", "Encontre a paz e à preencha.", "Fique atento à tartaruga: ela sai do casco.", "Agora sei à metade do que já soube.", "Eu cheguei à iludir a velhice, mas parei."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Língua Portuguesa','Assinale a frase em que a forma verbal está conjugada corretamente.',null,null,'["O policial interviu na discussão.", "Nunca ouve nada igual.", "Espero que eles vão bem na prova.", "Não sei se haverão novas oportunidades.", "Quando você as ver, fale com elas."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Língua Portuguesa','Nas frases a seguir, a forma do infinitivo foi substituída por um substantivo correspondente. Assinale a frase em que essa correspondência está correta.',null,null,'["Demolir o prédio / demolição do prédio.", "Prevenir o desastre / previsão do desastre.", "Ler o livro / legibilidade do livro.", "Intervir na briga / interação na briga.", "Observar a cena / observamento da cena."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Língua Portuguesa','Assinale a frase em que o pronome demonstrativo sublinhado está corretamente empregado, segundo a tradição gramatical.',null,'["/pmsp/soldado-2025-02/q13-2-figura-1.png"]','["Dê-me essa camisa que está nas suas mãos.", "João e Maria entraram na floresta; esta de botas, este de tênis.", "Eis aqui essa bolsa: a quem ela pertence?", "Aqueles dias de agora são mais longos.", "Maria e Anita vieram cantar; este de roupa social, aquele de roupa esporte."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Língua Portuguesa','Assinale a frase em que a palavra meio/meia está bem empregada.',null,null,'["Minha irmã está meia adoentada.", "Nós estamos meios cansados.", "É meio-dia e meio.", "A chuva chegou meio fraca.", "A bola chegou ao gol meia fraca."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Língua Portuguesa','Assinale a frase em que a preposição DE tem valor de origem.',null,null,'["A caixa de papelão contém lápis.", "O vinho de Portugal é do tipo verde.", "Sapatos de couro são caros.", "De real em real, ele ficou rico.", "O depósito de bebidas estava cheio."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Língua Portuguesa','Assinale a frase em que o verbo preferir está corretamente utilizado.',null,null,'["Prefiro queijo do que presunto.", "Prefiro mais queijo do que presunto.", "Prefiro o queijo do que o presunto.", "Prefiro queijo a presunto.", "Mais prefiro queijo do que presunto."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Língua Portuguesa','Assinale a frase em que a colocação do pronome pessoal oblíquo está correta.',null,null,'["Me deram o presente antes da data.", "Não deram-me o presente que pedi.", "O presente que foi-me dado é caro.", "Quem me deu esse presente?", "Quando viram-me em casa, ficaram tristes."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Língua Portuguesa','Assinale a frase em que a palavra sublinhada está no sentido figurado.',null,null,'["Nada mais comum do que julgar mal as coisas.", "Muitos são bons porque não sabem ser justos.", "Cada cabeça, uma sentença!", "Mais vale bem de longe, que mal de perto.", "Felicidade é um subproduto."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Língua Portuguesa','Sobre o significado e a estruturação dessa frase, assinale a afirmação correta.','Ele é tão ganancioso que não passaria 24 horas numa ilha habitada sem meter a mão nos bolsos dos selvagens nus. (Político britânico)',null,'["A oração precedida pela conjunção “que” tem valor de causa.", "A abreviatura de horas está feita de forma correta.", "O pronome “Ele” no início da frase vai se referir a alguém presente no futuro do discurso.", "A crítica da frase se dirige aos políticos britânicos em geral.", "Há uma contradição lógica no final da frase."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Língua Portuguesa','Creio na liberdade, esse vínculo entre o homem e a eternidade, essa condição indispensável para situar o ser à imagem e semelhança de seu criador. Sobre o significado e a estruturação dessa frase, assinale a afirmação correta.',null,null,'["A frase mostra um tom filosófico-materialista.", "Após a palavra “liberdade”, todo o restante da frase funciona como explicação dessa palavra.", "Todo o texto mostra a causa de o autor crer na liberdade.", "As duas orações finais mostram paralelismo em sua construção.", "O texto não mostra a opinião do emissor da frase, mas sim a do autor do texto religioso onde ele se fundamenta."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Matemática','Um carro da PM transportou o major Roberto de São Paulo para Araçatuba e retornou, no dia seguinte, pela mesma estrada. A distância rodoviária entre essas duas cidades é de 520 km e o moderno carro que transportou o major percorreu 13 km por litro de gasolina. Nessa época, o litro de gasolina custava, em São Paulo, 6,10 reais por litro. O gasto com combustível dessa viagem foi de, aproximadamente,',null,null,'["245 reais.", "350 reais.", "390 reais.", "460 reais.", "490 reais."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Matemática','O soldado Rafael dedica uma hora e quinze minutos por dia a seu treinamento físico, todos os dias, exceto aos domingos. No mês de agosto de 2024 Rafael cumpriu seu treinamento, e esse mês teve cinco domingos. No mês de agosto de 2024, o tempo total que Rafael dedicou a seu treinamento foi de',null,null,'["trinta e uma horas e quinze minutos.", "trinta e uma horas e quarenta e cinco minutos.", "trinta e duas horas e trinta minutos.", "trinta e duas horas e cinquenta minutos.", "trinta e três horas e trinta minutos."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Matemática','Para receber o novo comandante, o 1º Tenente Ramiro deverá organizar, no pátio do quartel da PM, uma formação retangular com 72 soldados dispostos regularmente em linhas (horizontais) e colunas (verticais). Sabe-se que essa formação retangular deve ter, no mínimo, três linhas e, no mínimo, oito colunas. O número de arrumações diferentes que Ramiro poderá fazer é igual a',null,null,'["2.", "3.", "4.", "5.", "6."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Matemática','Ricardo gasta atualmente 60% de seu salário em gastos essenciais. Segundo alguns especialistas, o ideal é que os gastos essenciais representem, no máximo, 50% do salário. Sem alterar seus gastos atuais de qualquer espécie, para que Ricardo passasse a ter os gastos essenciais dentro do que é considerado ideal, ele teria que ter um aumento salarial de, no mínimo,',null,null,'["50%.", "40%.", "30%.", "20%.", "10%."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Matemática','Para elaborar o orçamento da reforma do piso do pátio do quartel, o sargento Raul precisa saber sua área. A forma do pátio está apresentada na figura a seguir, na qual todos os ângulos são retos e as medidas dadas em metros. A área desse pátio em metros quadrados é',null,'["/pmsp/soldado-2025-02/q25-5-figura-1.png"]','["930.", "956.", "982.", "1024.", "1118."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Matemática','Um carro da PM precisa se deslocar do ponto A ao ponto B do Estado de São Paulo, no menor tempo possível. A figura a seguir mostra os pontos A e B, as estradas disponíveis e o tempo, em minutos, para percorrer cada trecho no momento da partida do carro. O menor tempo para o deslocamento de A até B é de',null,'["/pmsp/soldado-2025-02/q26-5-figura-1.png"]','["80 minutos.", "85 minutos.", "90 minutos.", "95 minutos.", "100 minutos."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Matemática','Vicente foi encarregado de pintar o piso de uma área de estacionamento com 160 m². A tinta que Vicente escolheu tem um rendimento de 14 m² por litro de tinta, por demão. Vicente fará uma pintura com três demãos. O número mínimo de galões de 3,6 litros que deverá ser comprado para a pintura é igual a',null,null,'["7.", "8.", "9.", "10.", "11."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Matemática','A tabela abaixo mostra alguns dados de estatística criminal do Estado de São Paulo, comparando os números de 2023 com os de 2024. 2023 2024 Nº de homicídios culposos 3.200 3.560 por acidente de trânsito Nº de infratores presos por 57.000 65.500 mandado Nº de veículos recuperados 38.000 46.800 Nº de armas de fogo 9.300 11.800 apreendidas Nº de autos de apreensão 5.700 6.400 Fonte: Dados da Secretaria de Segurança Pública do Estado de SP com valores ligeiramente arredondados para facilitar os cálculos. Acesso em 16/12/2024. A linha da tabela que mostra o maior crescimento percentual de 2023 para 2024 foi a de',null,'["/pmsp/soldado-2025-02/q28-6-figura-1.png"]','["Nº de homicídios culposos por acidente de trânsito.", "Nº de infratores presos por mandado.", "Nº de veículos recuperados.", "Nº de armas de fogo apreendidas.", "Nº de autos de apreensão."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Matemática','No site da Polícia Militar de SP pode-se observar, no Programa de Policiamento de Trânsito, o seguinte texto: Os policiais militares deste programa de policiamento são preparados e recebem instrução sobre legislação de trânsito e de técnicas e procedimentos operacionais padrão voltados ao melhor desempenho na atividade. Este programa atua em pontos previamente selecionados e estudados criteriosamente, visando também à redução de índices criminais. Adaptado do site da PM-SP, Programa de Policiamento de Trânsito. Acesso em 18/12/2024. Suponha que os policiais de certo ponto de fiscalização tenham recebido, entre diversas instruções, a seguinte ordem: Todos os caminhões transportando madeira devem ser revistados. A partir da ordem dada acima, considere as afirmativas a seguir. I. Se um caminhão não transporta madeira ele não deve ser revistado. II. Se um caminhão foi revistado então ele estava transportando madeira. III. Se um caminhão não foi revistado então ele não estava transportando madeira. Das afirmativas acima, aquela(s) que decorre(m) logicamente da ordem dada é(são):',null,null,'["I, apenas.", "II, apenas.", "III, apenas.", "I e II, apenas.", "II e III, apenas."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Matemática','Em certa fazenda há um lago e, para reunir dados sobre a investigação de uma ocorrência criminal nessa fazenda, o tenente Renato foi encarregado de determinar a distância aproximada entre dois pontos A e B nas margens desse lago. A figura a seguir mostra o lago e os dois pontos A e B. Para determinar a distância entre A e B, Renato fixou estacas em três pontos C, D e E, de forma que os ângulos ACD, CDE e DEB fossem retos, como mostra a figura. Em seguida, com uma trena, Renato mediu as seguintes distâncias: AC = 40 m, CD = 84 m, DE = 76 m e EB = 24 m. A distância, em metros, entre os pontos A e B é, aproximadamente,',null,'["/pmsp/soldado-2025-02/q30-7-figura-1.png"]','["63.", "66.", "70.", "73.", "77."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Matemática','Três soldados pintam uma área de 45 m² de um muro em um determinado tempo. No mesmo tempo, e com a mesma eficiência, a área em m² que cinco soldados pintam é',null,null,'["75.", "60.", "55.", "45.", "40."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Matemática','Rosilene faz flexões todo dia ao acordar. A tabela a seguir mostra o número de flexões que Rosilene fez em cada dia de uma determinada semana. Domingo 89 Segunda-feira 63 Terça-feira 77 Quarta-feira 89 Quinta-feira 100 Sexta-feira 104 Sábado 99 Nessa semana, o número de dias em que Rosilene fez mais flexões do que a média da semana foi',null,'["/pmsp/soldado-2025-02/q32-7-figura-1.png"]','["2.", "3.", "4.", "5.", "6."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Matemática','Durante uma missão, o soldado Ryan se viu em uma posição vulnerável e, portanto, precisando de resgate. O soldado Ryan se encontra em uma esquina, em um bairro no qual as ruas são todas de mão dupla e formam quarteirões retangulares, cada um com 100 metros na direção Leste-Oeste e 80 metros na direção Norte- Sul. O veículo para o resgate do soldado Ryan está em uma esquina na mesma rua em que Ryan está, mas a quatro quarteirões a oeste da posição de Ryan. Entretanto, no meio de um dos quarteirões entre o veículo de resgate e Ryan há um bloqueio que impede a passagem do veículo. Assim, o veículo precisará fazer um desvio para chegar até a posição do soldado Ryan. A menor distância, em metros, que o veículo de resgate precisará percorrer para ir da sua posição inicial até a posição do soldado Ryan é igual a',null,null,'["400.", "460.", "480.", "540.", "560."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Matemática','Rafaela e Mariana ficaram de plantão juntas hoje, uma terça-feira. Rafaela fica de plantão de 4 em 4 dias e Mariana de 6 em 6 dias. Sem contar o dia de hoje, após 100 dias, o próximo dia em que Rafaela e Mariana ficarão de plantão juntas será',null,null,'["segunda-feira.", "terça-feira.", "quarta-feira.", "quinta-feira.", "sexta-feira."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Matemática','O soldado Arquimedes precisa encher de água um recipiente com capacidade de 80 litros e dispõe de um vasilhame cujo formato é um paralelepípedo com base quadrada de lado 15 cm e 18 cm de altura. Arquimedes deverá encher o vasilhame em uma bica e despejar a água no recipiente. Para encher o recipiente, o número de vezes que Arquimedes deverá encher e despejar a água do vasilhame no recipiente é igual a',null,null,'["20.", "25.", "30.", "40.", "45."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Conhecimentos Gerais','Avalie as afirmativas a seguir, que apresentam fatores que contribuíram para o início da Primeira Guerra Mundial e assinale (V) para a verdadeira e (F) para a falsa. ( ) O crescente ideal do pan-eslavismo, que buscava a unificação dos territórios eslavos, e o pangermanismo, que buscava a unificação dos povos germânicos. ( ) As disputas imperialistas por territórios coloniais na África e na Ásia contribuíram para a intensificação das rivalidades entre os países europeus. ( ) O sentimento revanchista prussiano, surgido após a derrota da Prússia na Guerra Franco-Prussiana, especialmente pela perda do território da Alsácia-Lorena. As afirmativas são, respectivamente,',null,null,'["V – V – F.", "V – F – V.", "F – F – V.", "F – V – F.", "V – V – V."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Conhecimentos Gerais','Assinale a afirmativa que apresenta corretamente uma das medidas estabelecidas pela Constituição de 1891.','A Constituição de 1891 evidencia, no plano das instituições, que a classe dominante consegue alcançar seus objetivos políticos já no início da República, e é um índice de sua capacidade para promover a integração do país, na medida de tais objetivos. (Fonte: FAUSTO, Boris. A revolução de 1930. História e historiografia. São Paulo: Companhia das Letras, 1997, p. 120.)',null,'["Criou o poder moderador, que tinha a função de intervir para restaurar o equilíbrio entre os poderes Executivo, Judiciário e Legislativo, sempre que houvesse desarmonia entre eles.", "Permitiu a participação democrática dos analfabetos, ao conceder-lhes o direito de votar nas eleições para cargos políticos.", "Concentrou o poder na figura do presidente, retirando qualquer autonomia dos estados, que passaram a ser subordinados ao governo federal.", "Estabeleceu a laicização do Estado, separando o Estado da Igreja Católica, e garantiu a liberdade de culto de todas as religiões.", "Implementou o parlamentarismo como sistema político, inspirando-se no modelo inglês como referência para promover a estabilidade política."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Conhecimentos Gerais','Assinale a afirmativa que apresenta corretamente a interpretação dos dois fragmentos sobre o antissemitismo na Alemanha nazista.','Leia os fragmentos de texto a seguir. I. Uma parte da mobilização emocional, uma herança do descartado programa nacional-socialista, foi o antissemitismo, a marca de todos os movimentos nacionalistas. Mas logo veio a servir a um propósito mais sinistro. Os judeus tornaram-se os objetos indefesos sobre os quais milhões de alemães exerceram pela primeira vez a brutalidade essencial para que a Alemanha dominasse toda a Europa. Eles eram o campo de prática, a escola de treinamento de batalha, para as virtudes nórdicas, que mais tarde encontrariam sua plena expressão na Polônia, na França e na Rússia ocupada. Se os alemães tinham estômago para isso, eles podiam suportar qualquer coisa. Nenhuma voz de protesto foi levantada, em nenhum caso uma Igreja Cristã, seja Católica Romana ou Protestante, abriu suas portas para os judeus em refúgio, nenhum bispo alemão colocou a estrela de Davi. Os alemães passaram no teste com louvor: eles estavam de fato unidos. (Adaptado de: TAYLOR, A. J. P. The Course of German History: A survey of the development of Germany since 1815. New York: Coward McCann, 1962.) II. O hitlerismo, por outro lado, trouxe de repente no mercado mundial um novo artigo de exportação que tinha técnicas refinadas e rapidamente adaptáveis a todos os países. A matéria-prima deste artigo consistiu em certo grau de ideologia racial com seu ponto central de ódio contra os judeus. Disto já havia uma certa quantidade em cada país, ou poderia ser estimulado. Mas o refinamento dessa matéria-prima ocorreu na organização hierárquica nazista. Visava conquistar as massas. Quando a ideologia racial e o ódio aos judeus eram um tanto ineficazes como matéria-prima para as necessidades das massas, alguma outra ideologia, engendrada por teóricos ou seitas, poderia substitui-la e ser devidamente estimulada. (Adaptado de: MEINECKE, Friedrich. The German Catastrophe. Boston: Beacon Press, 1969, p. 59.)',null,'["O texto I defende que a resistência da população alemã e de outras instituições foi fundamental para conter as intenções nazistas, e o texto II argumenta que a sociedade permaneceu apática diante do novo movimento.", "O texto I defende que o ódio aos judeus foi um fenômeno novo criado pelo nazismo, e o texto II argumenta que esse ódio já existia entre os alemães antes da ascensão do regime nazista.", "Os textos I e II defendem que a violência e o ódio contra os judeus foram utilizados como uma ideologia para justificar e alcançar os interesses políticos da Alemanha durante o regime nazista.", "Os textos I e II defendem que o antissemitismo entre os alemães foi um elemento introduzido por Hitler, representando um fenômeno completamente novo e fora do contexto histórico da Alemanha.", "Os textos I e II defendem que o ódio aos judeus foi uma característica particular dos alemães, desconhecida em outros países, e que atingiu seu auge durante o regime nazista."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Conhecimentos Gerais','Observe a imagem a seguir. Fonte: Revista Careta, 05/01/1935. Disponível em https://memoria.bn.gov.br/DocReader/DocReader.aspx?bib=083712&pagfis=55970 A imagem, intitulada “ISSO NÃO É COMNOSCO”, retrata três personagens: o primeiro, com um violão, canta “Você me pareceu sincera! Mas não era! Mas não era! ...”; a segunda personagem é uma mulher de biquíni, usando um chapéu com a inscrição “1930”; e o terceiro personagem é o presidente Getúlio Vargas, que, segurando a segunda personagem, lhe diz: “Não faças caso. São as novas cantigas de carnaval...”. A imagem destaca',null,'["/pmsp/soldado-2025-02/q39-11-figura-1.png"]','["a ampla aprovação popular à permanência de Getúlio Vargas como presidente após a Revolução de 1930, mostrando o apoio da população às mudanças que ele propunha e realizava.", "a proibição, durante o governo de Getúlio Vargas, do direito de as mulheres votarem em eleições para cargos políticos, o que representou a continuidade do machismo presente nas oligarquias da República Velha.", "o incentivo à cultura promovido pelo governo de Getúlio Vargas, que, ao longo de toda a Era Vargas, ficou conhecido pela valorização da liberdade de expressão artística, como exemplificado nas cantigas de carnaval.", "o desprezo do governo de Getúlio Vargas pelos mais pobres e trabalhadores, ao negligenciar suas necessidades e direcionar suas políticas exclusivamente para beneficiar as classes empresariais.", "a decepção de certos setores diante das promessas de Getúlio Vargas de uma nova realidade após a Revolução de 1930, ao perceberem a persistência dos mesmos problemas e estruturas do passado."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Conhecimentos Gerais','Observe a imagem a seguir. Fonte: Memorial da Democracia. Disponível em https://memorialdademocracia.com.br/card/ a-grande-greve-dos-trabalhadores-do-abc A foto retrata um grande grupo de pessoas, predominantemente homens, com os braços erguidos em protesto, sendo que um deles segura uma placa com a inscrição: “‘Volks’ trabalhadores unidos até a vitória”, fazendo referência à fábrica de automóveis Volkswagen. A foto mostra a assembleia dos operários em greve na região do ABC paulista, em 1979. As greves gerais dos metalúrgicos, que ficaram conhecidas com esse nome, começaram em 1978 e se estenderam por 1979 e 1980, durante a ditadura militar no Brasil, e mobilizaram cerca de 200 mil trabalhadores. A respeito desse movimento social, avalie as afirmativas a seguir. I. As greves representaram o ressurgimento do movimento trabalhista brasileiro e o início do processo de redemocratização. II. As greves não alcançaram o resultado esperado, e os salários dos grevistas continuaram congelados devido ao fim do período conhecido como Milagre Econômico. III. As greves tiveram a adesão da maioria dos trabalhadores do setor metalúrgico, mas não conseguiram o apoio de outros segmentos trabalhistas e populares. Está correto o que se afirma em',null,'["/pmsp/soldado-2025-02/q40-12-figura-1.png"]','["I, apenas.", "I e II, apenas.", "I e III, apenas.", "II e III, apenas.", "I, II e III."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Conhecimentos Gerais','Em relação às ações policiais num contexto de generalização da insegurança e da reativação de estigmas socioespaciais que associam diretamente a pobreza com a violência, podemos observar que as periferias pobres das diferentes cidades são os espaços nos quais as violências legitimadas socialmente podem e são praticadas, em grande parte das vezes de forma indiscriminada – pelo simples fato de morar em um bairro pobre, o citadino está sujeito à suspeição do restante da sociedade e da polícia, o que faz com que seja tratado a priori como bandido. MAGRINI, Maria. A gestão da (in)segurança urbana pelo estado: fragmentação das identidades e das sociabilidades cotidianas. Ariús, Campina Grande, v. 20, n.2, pp. 39- 57, jul./dez. 2014. Para superar o problema socioespacial apresentado no texto, avalie se é necessário que os profissionais em ação: I. respeitem a dignidade da pessoa humana dependendo de sua classe social, moradia, zona em que reside e cor da sua pele; II. acatem a integridade física, moral e psíquica da pessoa do preso ou de quem seja objeto de incriminação; III. exerçam a função pública, seja em zona central ou periférica, com honestidade, não aceitando vantagem indevida de qualquer espécie. Está correto o que se afirma em',null,null,'["I, apenas.", "I e II, apenas.", "I e III, apenas.", "II e III, apenas.", "I, II e III."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Conhecimentos Gerais','Ela é frequentemente apontada como um dos principais vilões da poluição atmosférica. Enquanto as fontes poluidoras podem variar suas emissões, são as condições meteorológicas que determinam se esses poluentes permanecerão concentrados em níveis prejudiciais ou serão dispersos. Em baixa altitude, por exemplo, são mais comuns durante o inverno. Nessas situações, a temperatura do ar próximo à superfície esfria rapidamente, levando à formação de uma camada de ar mais fria e densa logo acima do solo, que fica “aprisionada” sob uma camada mais quente e menos densa. Isso cria uma barreira que impede a dispersão dos poluentes, contribuindo para o aumento da poluição atmosférica. Disponível em: https://cetesb.sp.gov.br/blog/2023/11/07/impacto-na-qualidade-doar/ Acesso: 22 de dez. 2024. Comum na Região Metropolitana de São Paulo, o fenômeno descrito no texto é denominado',null,null,'["aquecimento global.", "efeito estufa.", "inversão térmica.", "chuva ácida.", "destruição da camada de ozônio."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Conhecimentos Gerais','Os objetivos são transformar favelas e loteamentos irregulares em bairros, garantindo a seus moradores o acesso à cidade formal, com ruas asfaltadas, saneamento básico, iluminação e serviços públicos. Disponível em: https://capital.sp.gov.br/web/habitacao/w/programas/237077 Acesso: 22 de dez. 2024. Correlacione os temas a seguir às respectivas ações. 1. Ações sobre o relevo 2. Combate às enchentes 3. Mobilidade urbana 4. Minimização de ilhas de calor ( ) Executar obras de recuperação ambiental e paisagismo. ( ) Ampliar redes de drenagem de águas pluviais e programas de desobstrução de córregos. ( ) Realizar obras para contenção e estabilização de encostas. ( ) Construir corredores expressos e abrir vias para tráfego de ambulâncias, caminhões de lixo e veículos policiais. A correlação correta, na ordem apresentada, é','O Programa de Urbanização de Favelas é desenvolvido pela Secretaria Municipal de Habitação e tem como foco a urbanização e a regularização fundiária de áreas degradadas, ocupadas desordenadamente e sem infraestrutura. (...)',null,'["4 – 2 – 1 – 3.", "4 – 1 – 2 – 3.", "3 – 1 – 2 – 4.", "2 – 3 – 4 – 1.", "1 – 4 – 3 – 2."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Conhecimentos Gerais','A Região Metropolitana de São Paulo é marcada pela presença do contraste social e pela constituição de espaços fragmentados. Em partes específicas de seu território, ocorre o surgimento de áreas separadas, condomínios fechados, como Alphaville, Tamboré e Granja Viana, que podem ser considerados exemplos de suburbanização de altas e médias rendas, assim como a expansão da população em condições bastante precárias de vida em áreas centrais e deterioradas do Município de São Paulo. Nesse espaço diferenciado e desigual, as maneiras como os grupos sociais resolvem a relação habitar-trabalhar, as estratégias utilizadas, tornam-se diferenciadas, atingindo-os de modo distinto. ÂNTICO, Cláudia. Deslocamentos pendulares na região metropolitana de São Paulo. Disponível em: https://www.scielo.br/j/spp/a/tJPPNLfJmTZLWyh7S5KH8BJ/ A partir da temática do texto, avalie se os itens a seguir representam características da Região Metropolitana de São Paulo. I. Ocorrência da migração pendular II. Prática do êxodo rural III. Existência de autossegregação e da segregação induzida Está correto o que se apresenta em',null,null,'["I, apenas.", "I e III, apenas.", "II e III, apenas.", "I e II, apenas.", "I, II e III."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Conhecimentos Gerais','Em 1996, o geógrafo brasileiro Milton Santos escreveu o livro “A Natureza do Espaço: técnica e tempo, razão e emoção”. A obra aponta (muito antes da existência da internet atual e das redes sociais) que o controle das técnicas que permitem a circulação das informações representaria o domínio da tecnologia mais decisiva de nossa época. (...) Hoje é indiscutível o tamanho do poder de empresas como a META, de Zuckerberg, que controla o Facebook, o Instagram, o WhatsApp, o Threads e outras. Essas empresas detêm os dados e informações de bilhões de pessoas que circulam nessas redes e, com o devido trabalho de direcionamento, conseguem veicular mensagens particularizadas por meio de algoritmos, visando influenciar nossas percepções e decisões econômicas, políticas e sociais. Santos, M. A Natureza do Espaço: Técnica e Tempo, Razão e Emoção. São Paulo: Editora da Universidade de São Paulo, 2006. (Adaptado) Avalie se, na visão de Milton Santos, todo esse poder não é usado de forma neutra porque I. o meio por onde circula esse turbilhão de fluxos é impregnado de comando e ideologia, atendendo aos interesses de grupos específicos; II. a acelerada adoção da tecnologia de reconhecimento facial, placas de veículos e câmeras em policiais, desperta uma série de questionamentos sobre os limites de seu uso no contexto da segurança pública e de outros campos; III. esse amontoado de práticas, processos e técnicas que agruparam “ciência + tecnologia + informação” no mundo contemporâneo, denominado de “meio técnico-científicoinformacional”, possui acesso irrestrito para todos. Está correto o que se afirma em',null,null,'["II, apenas.", "I e II, apenas.", "I e III, apenas.", "II e III, apenas.", "I, II e III."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Conhecimentos Gerais','Após 27 denúncias em quatro dias, um vídeo falso com a imagem de Marcos Mion foi o catalisador da investigação [da Polícia Civil do Distrito Federal]. Na “propaganda” gerada por IA, o apresentador divulga uma promoção do restaurante Outback. No entanto, ao clicar no link, as vítimas eram redirecionadas a um site falso. De acordo com a apuração, o objetivo do golpe era coletar dados pessoais para a aplicação de fraudes financeiras. “Figuras públicas são alvos preferenciais pois seus nomes geram mais engajamento e repercussão. Criadores de deepfakes maliciosas buscam causar o maior impacto possível, seja para prejudicar a imagem da pessoa alvo ou para aumentar visualizações e aplicar golpes”, explica Fabrício Carraro, especialista em IA e program manager da Alura. A lista de personalidades brasileiras que já foram “clonadas” pela IA é extensa e inclui nomes como Neymar, Anitta, Eliana, Ana Maria Braga, William Bonner, Drauzio Varella, Ivete Sangalo, Mano Brown e Jade Picon – além de figuras da política nacional. DE TILIA, C. Após golpe com Marcos Mion, deepfakes entram na mira da Justiça brasileira. Forbes Brasil, 17 jan. 2025. Disponível em: https://forbes.com.br/forbestech/2025/01/apos-golpe-com-marcos-mion-deepfakes-entram-na-mira-da-justicabrasileira/ A matéria em questão chama atenção para o risco das deepfakes. Para além das já conhecidas notícias falsas, esse novo tipo de prática é capaz de manipular voz e imagem de pessoas públicas de maneira convincente para fins maliciosos. Assinale a opção que indica corretamente um modo eficaz de prevenção contra deepfakes.',null,null,'["Confiar em vídeos ou mensagens que estejam de acordo com o comportamento esperado da figura pública em questão.", "Priorizar conteúdo audiovisual que pareça profissional e bem editado, assegurando-se de sua boa procedência.", "Verificar diretamente nos canais oficiais das figuras públicas a autenticidade de anúncios ou promoções.", "Encaminhar o conteúdo recebido publicamente para confirmar com outras pessoas se o link ou vídeo é confiável.", "Interagir apenas com conteúdo compartilhado por terceiros confiáveis, como amigos e familiares."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Conhecimentos Gerais','O vício em apostas é uma condição psiquiátrica denominada clinicamente como “jogo patológico” ou “transtorno do jogo”. Trata-se de um problema de saúde mental reconhecido pela Organização Mundial da Saúde (OMS) e previsto tanto na Classificação Internacional de Doenças (CID) quanto no Manual Diagnóstico e Estatístico de Transtornos Mentais (DSM). Considerada um transtorno dos hábitos e dos impulsos, a condição tem como principal característica a ocorrência de episódios repetidos e frequentes de jogo, que dominam a vida da pessoa. Com isso, ela torna-se incapaz de controlar o tempo e o dinheiro gastos, mesmo em situações em que isso leva a prejuízos sociais, profissionais e familiares. Embora esse tipo de dependência já seja documentado há décadas pelos especialistas, com a popularização das plataformas de apostas online – as famosas bets –, esse comportamento danoso ganhou nova roupagem e proporção. HOSPITAL ISRAELITA ALBERT EINSTEIN. O risco das “bets”: 5 pontos para entender o vício em apostar. Vida Saudável, 15 jan. 2025. Disponível em: https://vidasaudavel.einstein.br/o-risco-das-bets-5-pontos-para-entender-o-vicioem-apostar/ O vício em plataformas de aposta tem gerado preocupação entre autoridades, e os brasileiros podem ter perdido até 35,9 bilhões de reais com essa prática em 2024, segundo estudos. Com base no texto, assinale a opção que melhor reflete um aspecto relevante associado ao vício em apostas.',null,null,'["O vício em apostas envolve outras pessoas além do jogador, criando problemas sociais, familiares e financeiros.", "A solução para o vício está associada à força de vontade, de modo que o indivíduo controle seu tempo e dinheiro.", "O problema do vício é próprio de pessoas que possuem recursos financeiros para arcar com perdas nas plataformas.", "As plataformas de apostas online repetem a mesma situação problemática do vício em jogos tradicionais.", "O vício em apostas deve ser encarado como um problema mental e com solução individualizada."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Conhecimentos Gerais','Neste ano, os riscos de racionamento de energia são baixos. Os preços mais altos em comparação com a Ásia significam que as remessas de GNL [gás natural liquefeito] estão chegando. Mas um inverno frio em outro lugar poderia criar mais concorrência por suprimentos e aumentar ainda mais os preços, o que causaria problemas para a região. “Há um risco maior de que a sorte da Europa, em relação ao clima ameno, possa se esgotar no próximo inverno”, disse Hansen, do Saxo Bank. “Em outras palavras, somos forçados a depender das importações de GNL e, com isso, da necessidade de nos mantermos competitivos em relação à Ásia.” SHIRYAEVSKAYA, Anna; AZEVEDO ROCHA, Priscila. Europa enfrenta nova crise de energia com chegada do frio e pode piorar em 2025. Bloomberg Línea, 23 nov. 2024. Disponível em: https://www.bloomberglinea.com.br/esg/europa-enfrenta-novacrise-de-energia-com-chegada-do-frio-e-pode-piorar-em-2025/ As economias europeias apresentam uma forte dependência de combustíveis fósseis, tanto para sustentar suas atividades industriais quanto para atender às necessidades de uso doméstico. A crise energética dos últimos anos se deve, em grande medida, às consequências','No auge da crise energética em 2022, a Alemanha ordenou compras rápidas obrigatórias de gás para armazenamento no mercado global a preços recordes. Para tentar recuperar parte do custo extra, Berlim introduziu uma taxa de armazenamento de gás, paga por comerciantes ou empresas de serviços públicos para entregas através da Alemanha. (...)',null,'["do colapso do acordo comercial entre o Mercosul e a União Europeia, afetando exportações agrícolas.", "da proibição de importação de gás natural, imposta pelos Estados Unidos sobre os países da Europa.", "do aumento significativo da produção de gás natural pelo Irã, reduzindo a dependência em relação à Europa.", "da interrupção parcial do fornecimento de gás natural pela Rússia devido à guerra na Ucrânia.", "do conflito Israel-Palestina, gerando instabilidades na relação com os principais fornecedores de petróleo."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Conhecimentos Gerais','Para tentar garantir o sucesso do Acordo de Paris, esta geração terá a árdua missão de remover da atmosfera uma enorme quantidade de GEE (Gases do Efeito Estufa). Ainda não é claro, porém, se tecnologias para remoção de GEE existirão na escala necessária para que essa geração possa evitar um colapso climático ao final deste século. (...) Países como o Brasil têm uma prerrogativa legítima de querer alcançar o ''nível de país desenvolvido''. Com base nisso, o governo atual, ao invés de defender a redução, defende a ampliação da exploração de petróleo. A Organização Nacional da Indústria do Petróleo chegou mesmo a sugerir que a exploração na Margem Equatorial brasileira seria de suma importância para as ''futuras gerações''. VEJA. Crise climática já condena uma geração inteira a viver no calor extremo. Disponível em: https://veja.abril.com.br/agenda-verde/crise-climatica-ja-condenauma-geracao-inteira-a-viver-no-calor-extremo O trecho menciona o Acordo de Paris, que completa 10 anos em 2025 e visa reduzir os impactos da atividade humana no planeta. O texto evidencia que há um conflito entre',null,null,'["a remoção de gases do efeito estufa e a proibição de tecnologias de captura de carbono.", "o desenvolvimento econômico e os limites planetários impostos pela crise climática.", "a necessidade de atingir neutralidade climática e a eliminação nacional de energias renováveis.", "o compromisso do Brasil com o Acordo e a decisão de abandonar a exploração de petróleo.", "a preservação da camada de ozônio e a exploração de minerais de alto valor no Brasil."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Conhecimentos Gerais','O Brasil assume pela quarta vez a presidência rotativa do BRICS em meio a expansão do bloco que, em 2025, vai contar com ao menos nove novos membros. Reforma da governança global e desenvolvimento sustentável com inclusão social são algumas das agendas que o Brasil buscará promover. Com o lema Fortalecendo a Cooperação do Sul Global para uma Governança mais Inclusiva e Sustentável, o governo brasileiro tem, entre os desafios, o de articular a participação dos novos membros e dar continuidade à construção do sistema de pagamento com moedas locais no comércio entre os países, substituindo o dólar. AGÊNCIA BRASIL. Brasil assume presidência do Brics em meio à expansão do bloco. Disponível em: https://agenciabrasil.ebc.com.br/internacional/noticia/2024- 12/brasil-assume-presidencia-do-brics-em-meio-expansao-do-bloco O redesenho das relações internacionais passa pelo BRICS, bloco integrado pelo Brasil e que vem em ritmo de expansão das atividades. Os dois países mais geopoliticamente relevantes do bloco são:',null,null,'["Turquia e Israel.", "Brasil e África do Sul.", "Alemanha e Coreia do Sul.", "Arábia Saudita e Índia.", "China e Rússia."]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,51,'Noções de Informática','Um usuário do MS-Windows 10 versão BR acessou uma pasta e acionou o atalho Crtl + Shift + N com o objetivo de',null,null,'["fechar a pasta atual.", "criar uma nova pasta.", "abrir uma nova janela.", "imprimir arquivos da pasta.", "organizar arquivos da pasta."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,52,'Noções de Informática','Um usuário do MS Excel 2016 BR, tomando por base dados no site da Secretaria de Segurança Pública do Estado de São Paulo, criou a planilha a seguir: Com base nos dados apresentados, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O resultado da fórmula =MED(B3:C3) é maior do que o resultado da fórmula =MÉDIA(B4:B6). ( ) O resultado da fórmula =CONT.SE(B3:B13;”>1600”) é maior do que o resultado da fórmula =CONT.NÚM(C3:C13). ( ) O resultado da fórmula =SOMA(B8:B13) é menor do que o resultado da fórmula =SOMARPRODUTO(C3:C7). As afirmativas são, respectivamente,',null,'["/pmsp/soldado-2025-02/q52-20-figura-1.png"]','["F – V – V.", "V – F – V.", "F – V – F.", "V – F – F.", "V – V – F."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,53,'Noções de Informática','Um usuário do Gmail deseja enviar um e-mail com um arquivo anexo e em modo confidencial. Para isso, na janela “Nova mensagem”, ele deve clicar nos seguintes botões:','Figuras das alternativas A, B, C, D e E, nessa ordem.','["/pmsp/soldado-2025-02/q53-21-alternativa-1.png", "/pmsp/soldado-2025-02/q53-21-alternativa-2.png", "/pmsp/soldado-2025-02/q53-21-alternativa-3.png", "/pmsp/soldado-2025-02/q53-21-alternativa-4.png", "/pmsp/soldado-2025-02/q53-21-alternativa-5.png"]','["Figura da alternativa A (ver apoio).", "Figura da alternativa B (ver apoio).", "Figura da alternativa C (ver apoio).", "Figura da alternativa D (ver apoio).", "Figura da alternativa E (ver apoio)."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,54,'Noções de Informática','As opções a seguir apresentam extensões de tipos de arquivos que podem ser salvos no MS PowerPoint 2016 BR, à exceção de uma. Assinale-a.',null,null,'[".pptx", ".pptm", ".ppsm", ".wmv", ".cmx"]'::jsonb,'E',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,55,'Noções de Informática','No MS Word 2016 BR, a Guia Revisão contém, como padrão, os botões listados a seguir, à exceção de um. Assinale-o.','Figuras das alternativas A, B, C, D e E, nessa ordem.','["/pmsp/soldado-2025-02/q55-21-alternativa-1.png", "/pmsp/soldado-2025-02/q55-21-alternativa-2.png", "/pmsp/soldado-2025-02/q55-21-alternativa-3.png", "/pmsp/soldado-2025-02/q55-21-alternativa-4.png", "/pmsp/soldado-2025-02/q55-21-alternativa-5.png"]','["Figura da alternativa A (ver apoio).", "Figura da alternativa B (ver apoio).", "Figura da alternativa C (ver apoio).", "Figura da alternativa D (ver apoio).", "Figura da alternativa E (ver apoio)."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,56,'Noções de Administração Pública','Um grupo de policiais militares foi convidado por certo militar reformado a formar uma associação civil sem fins lucrativos. O objetivo era permitir que os associados, todos com porte legal de arma de fogo, pudessem participar de patrulhamento voluntário das vias públicas, devidamente uniformizados com trajes contendo as cores e o símbolo da associação, de modo a dissuadir os interessados na prática de ilícitos e prender aqueles que se encontrassem em flagrante delito, submetendo-os à autoridade competente. Ao analisarem a Constituição da República, os policiais militares convidados concluíram corretamente que é',null,null,'["vedada a formação de associação com essas características, por ter caráter paramilitar.", "vedada a formação de uma associação por militares, salvo se houver autorização dos respectivos comandantes.", "vedada a formação de associação com o objetivo almejado, pois a prisão em flagrante somente pode ser realizada pelo militar em serviço.", "permitida a formação da referida associação, independentemente de qualquer balizamento legal, pois o direito de associação é de natureza fundamental.", "permitida a formação de associação com essas características, independentemente de autorização dos respectivos comandantes, desde que os policiais militares atuem fora do horário de serviço."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,57,'Noções de Administração Pública','João, membro da Polícia Militar do Estado Alfa atuando como médico, foi aprovado em concurso público de provas e títulos para outro cargo efetivo de médico, no Município Beta. Como João não almejava deixar a Polícia Militar em razão da sólida carreira que construíra, consultou a Constituição da República em relação à possibilidade de acumular o cargo que já ocupava e o referido emprego público. João concluiu corretamente que a acumulação é',null,null,'["possível, desde que haja compatibilidade de horários, com prevalência da atividade militar.", "impossível, pois apenas seria viável se ocorresse junto ao mesmo ente federativo.", "vedada, pois o novo cargo efetivo não é da área da educação.", "vedada, pois os policiais militares não podem cumular outro cargo ou emprego público.", "possível, desde que haja compatibilidade de horários e a carga horária somada, não ultrapasse 40 horas semanais."]'::jsonb,'A',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,58,'Noções de Administração Pública','João, policial militar, estava conduzindo veículo da corporação durante o horário de expediente quando atropelou e matou Pedro, transeunte que atravessava a via pública no momento dos fatos. Irresignados, os familiares de Pedro informaram a alguns meios de comunicação social que ingressariam com ação de reparação de danos em face de João e do Estado Alfa, ao qual estava vinculada a sua corporação. À luz da Constituição da República, é correto afirmar que',null,null,'["João e o Estado Alfa somente podem ser responsabilizados com a demonstração da culpa daquele.", "somente o Estado Alfa pode ser responsabilizado independentemente da demonstração da culpa de João.", "João pode ser responsabilizado independentemente da demonstração de culpa, o mesmo ocorrendo com o Estado Alfa.", "somente será possível a responsabilização de João e do Estado Alfa caso a família da vítima demonstre que esta última não teve culpa no atropelamento.", "como João estava conduzindo o veículo da corporação durante o horário de expediente, cumprindo um dever legal, não é possível a sua responsabilização pelo atropelamento."]'::jsonb,'B',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,59,'Noções de Administração Pública','Ângelo, soldado da Polícia Militar do Estado de São Paulo, foi denunciado, pelo Ministério Público, pela alegada prática de crime militar contra civil. Ao tomar conhecimento do ocorrido, consultou a Constituição do Estado de São Paulo para verificar a autoridade ou órgão competente para processá-lo e julgá-lo. Ao fim de sua análise, Ângelo concluiu corretamente que a referida autoridade é',null,null,'["o Conselho de Justificação.", "o Tribunal de Justiça Militar.", "um juiz de direito do juízo militar.", "um juiz de direito do juízo comum, não militar.", "o Conselho de Justiça, sob presidência do juiz de direito."]'::jsonb,'C',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,60,'Noções de Administração Pública','Uma pessoa, credora de Pedro, soldado da Polícia Militar do Estado de São Paulo, encaminhou requerimento ao Comandante- Geral da corporação solicitando que fosse informado o valor da renda mensal do referido agente. Acresceu que o objetivo era utilizar essa informação na montagem da estratégia a ser utilizada para promover a cobrança do crédito que tinha com Pedro. O Comandante-Geral, após analisar a sistemática vigente, concluiu corretamente que a informação solicitada',null,null,'["diz respeito à intimidade de Pedro, logo, não pode ser fornecida.", "somente pode ser fornecida se a pessoa for titular de um crédito alimentar.", "somente pode ser fornecida se os documentos apresentados comprovarem que a pessoa, de fato, é credora de Pedro.", "deve ser divulgada, o que independe até mesmo de requerimento, por ser de interesse geral.", "deve ser divulgada, pois a administração pública não pode invocar sigilo em relação a nenhum requerimento de acesso à informação."]'::jsonb,'D',null from public.exams where slug='pmsp-soldado-2025-02' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exams(slug,title,source,year) values ('pmsp-oficial-2026-ingles','PM São Paulo · Oficial · 2026 · 16/08/2026 · Inglês','pmerj','2026') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'História','No contexto de formação do sistema feudal, o processo descrito no excerto','Para consolidar o Estado franco, Carlos Magno multiplicou as concessões de terras — ou benefícios — aos personagens cuja fidelidade queria garantir e obrigou-os a lhe prestar juramento e a se tornarem seus vassalos. [...] Para que o conjunto da sociedade, pelo menos as pessoas que importavam, se ligasse ao rei ou ao imperador por uma rede tão estreita quanto possível de subordinações pessoais, ele incentivou os vassalos a, por sua vez, submeterem os seus súditos à sua própria vassalagem. (Jacques Le Goff. A civilização do Ocidente medieval, 2016.)',null,'["proporcionou a criação das comunas para defender os servos dos confiscos e taxações senhoriais excessivos.", "representou uma forma de divisão da riqueza e do poder político-militar entre a nobreza.", "garantiu a unificação política e a autossuficiência econômica dos reinos germânicos na Europa.", "fortaleceu as monarquias nacionais ao alargar a sua função teocrática na sociedade.", "subordinou a autoridade fiscal dos senhores sobre os seus domínios às determinações de um conselho de nobres."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'História','De acordo com a afirmação de Montesquieu apresentada no excerto,','No seu estado natural, os homens nascem numa verdadeira igualdade, mas não podem permanecer nela. A sociedade faz com que a percam e apenas retornam à igualdade pelas leis. (Charles-Louis de Secondat, Barão de Montesquieu. Apud: Ricardo Luiz de Souza. A democracia contemporânea e o mundo de Montesquieu, 2018.)',null,'["a sociedade estamental fundamenta-se em um contrato social feito pelos cidadãos.", "o indivíduo deve renunciar à igualdade, de forma geral, com a instituição do Estado.", "a igualdade entre os cidadãos é garantida pela divisão dos poderes estatais.", "a origem familiar do indivíduo é a base dos privilégios sociais restritos somente pelas leis.", "a igualdade primordial reaparece como igualdade jurídica após o surgimento da sociedade civil."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'História','De acordo com o excerto, a Revolução Industrial na Grã-Bretanha foi favorecida pela','A partir da segunda metade dos anos 1760, com o final da Guerra dos Sete Anos, é que a mecanização da indústria se estabelece. A máquina de fiar com múltiplos fusos e aque-la movida à água de Richard Arkwright haviam sido inventadas em 1765 e 1768, respectivamente, e esperaram perto de 10 anos para serem efetivamente incorporadas à produção industrial com a explosão da demanda por tecidos nas áreas abertas ao comércio pelo Estado britânico, entre finais do século XVIII e princípios do XIX. (Luís Edmundo Moraes. História contemporânea: da Revolução Francesa à Primeira Guerra Mundial, 2025. Adaptado.)',null,'["melhoria da infraestrutura de transporte do país devido aos investimentos estatais.", "acumulação de capitais sustentada pelo comércio colonial transatlântico.", "inovação tecnológica associada ao aumento do consumo mundial de tecidos.", "oferta de mão de obra nas fábricas em decorrência da desmobilização militar.", "substituição do trabalho humano por máquinas movidas a energia elétrica."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'História','Os dados apresentados no excerto decorrem','Entre 1864 e 1874, o número de escravizados no Nordeste declinou de 774 mil (45% do total de escravizados existentes no Brasil) para 435 687 (28% do total). No mesmo período, nas regiões cafeeiras, a população escravizada aumentou de 645 mil (43% do total de escravizados) para 809 575 (56% do total), e só na Província de São Paulo o número de cativos dobrou, passando de 80 mil a 174 622. (Boris Fausto. História do Brasil, 2007. Adaptado.)',null,'["do tráfico interprovincial de escravizados, que se intensificou após a aprovação da lei Eusébio de Queirós.", "da iniciativa governamental de atrair imigrantes, que foi retomada com a aprovação da lei do Ventre Livre.", "da abolição antecipada de escravizados, que ocorreu em algumas províncias, como o Ceará e o Amazonas.", "da concessão da liberdade aos escravizados sexagenários, que foi aprovada pela lei Saraiva-Cotegipe.", "do desmantelamento do trabalho nas fazendas paulistas, que foi provocado pela fuga em massa de escravizados."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'História','Durante o Estado Novo (1937-1945), os instrumentos de propaganda do governo, mencionados no excerto,','O ministro do Trabalho, Indústria e Comércio, Alexandre Marcondes Filho, tomou posse em janeiro de 1942 e passou a fazer, semanalmente, uma palestra de dez minutos, durante A Hora do Brasil. O nome das palestras já indicava sua intenção: “Falando aos trabalhadores brasileiros”. Nelas, divulgava a obra do presidente Getúlio Vargas, contava a história das leis sociais, seus pontos polêmicos e os direitos que elas garantiam. Nunca deixava de destacar as virtudes excepcionais do presidente e as qualidades do cidadão brasileiro, homem bom e trabalhador, principal responsável pela riqueza e grandeza do país. O programa foi ao ar todas as quintas-feiras até o final de julho de 1945, transmitido pelas emissoras de rádio de todo o país. (https://memorialdademocracia.com.br. Adaptado.)',null,'["coexistiam com a liberdade de expressão dos meios de comunicação e dirigiam-se ao grande público.", "criticavam a modernização do país pela via autoritária e atribuíam o progresso deste à mobilização política dos trabalhadores urbanos.", "promoviam valores corporativistas e defendiam a autonomia das organizações sindicais dos trabalhadores urbanos.", "vinculavam a ampliação das leis trabalhistas à atuação do presidente e fortaleciam a legitimidade governamental junto aos trabalhadores.", "prestigiavam as novas tecnologias de comunicação e apresentavam diferentes versões sobre a História do país."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'História','Dentre as características da Guerra Fria que a aproximam de uma Terceira Guerra Mundial, como mencionado no excerto, encontram-se','A Segunda Guerra Mundial mal terminara quando a humanidade mergulhou no que se pode encarar, razoavelmente, como uma Terceira Guerra Mundial, embora uma guerra muito peculiar. Pois, como observou o grande filósofo Thomas Hobbes, “a guerra consiste não só na batalha, ou no ato de lutar, mas num período de tempo em que a vontade de disputar pela batalha é suficientemente conhecida”. A Guerra Fria entre Estados Unidos e União Soviética, que dominou o cenário internacional na segunda metade do século XX, foi sem dúvida um desses períodos. (Eric J. Hobsbawm. Era dos extremos: o breve século XX: 1914-1991, 1995. Adaptado.)',null,'["a competição pela supremacia tecnológica global e a neutralidade das duas superpotências em conflitos regionais.", "a coexistência pacífica e o tratado de contenção da produção de armas nucleares da década de 1950 entre as duas superpotências.", "a tensão e hostilidade contínuas entre as duas superpotências e a ausência de confronto militar direto entre ambas.", "a prática de espionagem e propaganda das duas superpotências e o desinteresse pelo processo de descolonização afro-asiático.", "a tolerância à multipolaridade global e a competição científica pela conquista do espaço entre as duas superpotências."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Filosofia','O problema ético central apresentado no excerto refere-se à','Em 2020, duas mulheres venceram o prêmio Nobel de química pelo desenvolvimento de uma ferramenta revolucionária de edição genética, que já foi descrita como “a reescrita do código da vida”. A técnica é conhecida como Crispr/Cas9 e permite que cientistas mudem o código de DNA de maneira específica para entender e tratar doenças genéticas. Enquanto tem potencial imenso de transformar as nossas vidas, a técnica tem levantado muitas questões éticas. O cientista chinês He Jiankui foi condenado a três anos de prisão em 2019 após anunciar que bebês gêmeas nasceram com DNA modificado para torná-las resistentes ao HIV, o que ele conseguiu ao usar a ferramenta Crispr/Cas9 antes do nascimento delas. Claes Gustafsson, secretário do comitê do Nobel em química, disse que “com todas as tecnologias realmente poderosas, nas ciências biológicas ou em qualquer outra área, há possibilidade de mau uso”. (www.cnnbrasil.com.br, 07.10.2020. Adaptado.)',null,'["possibilidade de utilização de intervenções genéticas para reduzir as desigualdades no acesso à saúde.", "dificuldade da regulamentação internacional das pesquisas relacionadas à manipulação do material genético humano.", "substituição das normativas tradicionais de controle científico pela autonomia nas pesquisas de engenharia genética.", "definição de critérios que orientem a utilização de tecnologias capazes de alterar geneticamente seres humanos.", "necessidade de eliminar restrições legais que dificultam o avanço das biotecnologias."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Filosofia','A transformação descrita no excerto contribuiu para fortalecer uma concepção filosófica na qual a arte passou a','A fotografia foi responsável por uma grande revolução na pintura, já que possibilitava uma representação “perfeita” do objeto fotografado. Representação desejada pelos pintores desde o início do Renascimento, quando se iniciou uma intensa pesquisa de técnicas para reproduzir a realidade de maneira mais fiel. E por tratar-se de uma forma fidelíssima de representação, a fotografia desencadeou uma crise na pintura, que precisou repensar seus conceitos e sua função. Não fazia mais sentido pintar quadros com o objetivo de representar a realidade se a câmera fotográfica fazia isso de maneira rápida e precisa. A partir desse momento, a pintura começou a se modificar e novos estilos e movimentos artísticos surgiram. (www.aoredor.blog.br, 02.03.2025. Adaptado.)',null,'["recuperar os princípios clássicos de objetividade ao abandonar interpretações particulares da realidade.", "valorizar formas de expressão que ultrapassassem a simples imitação do real.", "reafirmar o compromisso estético com a reprodução técnica dos objetos observados.", "substituir a criatividade artística pela neutralidade dos recursos tecnológicos.", "negar a possível relação entre experiência subjetiva e produção estética."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Filosofia','Do ponto de vista filosófico, a crítica apresentada nos versos da canção evidencia que o ser humano','Leia os versos da canção “Tá?”, interpretada por Mariana Aydar e composta por Roberta Sá, Pedro Luís e Carlos Rennó. Pra bom entendedor, meia palavra bas- Eu vou denunciar a sua ação nefas- Você amarga o mar, desflora a flores- Por onde você passa, o ar você empes- Não tem medida a sua ação imediatis- Não tem limite o seu sonho consumis- Você deixou na mata uma ferida expos- Você descore as cores dos corais na cos- Você aquece a Terra e enriquece a cus- Do roubo, do futuro e da beleza, augus- [...] Não vou dizer seu nome porque me desgas- Pra bom entendedor, meia palavra bas- [...] Pra bom entendedor, meia palavra bas... ta! (https://open.spotify.com)',null,'["exerce sobre a natureza um domínio inevitável decorrente da superioridade racional da espécie humana.", "substitui valores éticos por critérios científicos na definição da relação entre sociedade e natureza.", "deve se reconhecer como parte da natureza, responsabilizando-se pelos impactos de suas ações sobre ela.", "necessita submeter a preservação ambiental às exigências do crescimento econômico contemporâneo.", "considera os impactos ambientais como consequências naturais do desenvolvimento das sociedades humanas."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Filosofia','A diferença entre as perspectivas filosóficas apresentadas no excerto evidencia a oposição entre','René Descartes viveu no começo do século XVII, num período por vezes chamado de Revolução Científica, uma era de rápidos avanços nas ciências. O cientista e filósofo britânico Francis Bacon havia estabelecido um novo método para conduzir experiências científicas, baseado em observações detalhadas e suas metodologias forneceram um novo sistema para investigar o mundo. Descartes compartilhava de sua excitação e otimismo, mas por razões diferentes. Bacon considerava que as aplicações práticas das descobertas científicas eram seu objetivo e ponto principal, enquanto Descartes estava mais fascinado com o projeto de expandir o conhecimento e a compreensão do mundo. (O livro da Filosofia, 2011. Adaptado.)',null,'["o Dogmatismo e o Ceticismo.", "o Materialismo e o Idealismo.", "o Positivismo e o Pragmatismo.", "o Humanismo e o Iluminismo.", "o Racionalismo e o Empirismo."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Sociologia','Analise a charge de Carol Ito. (https://fervuranoclima.com.br) Na charge, a perspectiva associada à personagem indígena expressa a',null,'["/pmsp/oficial-2026/q11-9-figura-1.png"]','["subordinação das práticas comunitárias às exigências econômicas necessárias para o desenvolvimento material da sociedade.", "utilização coletiva dos recursos naturais como estratégia voltada para a expansão contínua da produção de bens e do consumo.", "compreensão da vida humana como parte de uma experiência coletiva integrada aos elementos naturais e sociais.", "valorização simbólica da natureza como realidade separada das formas concretas de organização da vida social.", "defesa da autonomia individual como princípio orientador das relações entre cultura, sociedade e ambiente."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Sociologia','As relações parassociais, apresentadas no excerto, tendem a','A sensação de proximidade com celebridades e figuras midiáticas sempre existiu na história. Ao acompanhar esses indivíduos por meio de canais midiáticos, é comum que as pessoas acreditem que, de fato, construíram uma espécie de amizade com aqueles que acompanham por meio das telas. Assim, com o fortalecimento das redes sociais, esses tipos de interações, conhecidos como “relações parassociais”, tornaram-se ainda mais frequentes na sociedade. Pesquisadores avaliam que, como o conteúdo produzido por essas celebridades é absorvido de forma única por cada um dos indivíduos, é comum que eles acreditem que, de fato, criaram uma relação única e próxima de celebridades. Esse fenômeno explica, dessa forma, os motivos pelos quais certa credibilidade é atribuída a pessoas famosas em propagandas publicitárias, por exemplo. (Julia Galvão. https://jornal.usp.br, 29.11.2023.)',null,'["associar os vínculos sociais construídos nos meios digitais à diminuição da influência dos padrões culturais de consumo.", "caracterizar a ausência de contato presencial como obstáculo à identificação simbólica entre indivíduos e celebridades.", "relacionar a construção identitária à menor circulação de referências culturais compartilhadas.", "contribuir para a formação de referências simbólicas que influenciam comportamentos, preferências e formas de pertencimento social.", "compreender as relações sociais mediadas pelas redes digitais como predominantemente orientadas por interesses econômicos."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Sociologia','Do ponto de vista da classificação dos direitos na sociedade contemporânea, as situações apresentadas nos excertos referem-se à','Texto 1 Um grupo formado por professores, alunos e moradores de cinco bairros da região Norte de Campinas realizou, em 10.09.2021, um ato contra o fechamento do período noturno de uma escola pública estadual. O fim das aulas noturnas, segundo os manifestantes, causaria transtornos às comunidades próximas, que contavam com apenas aquela escola na região. Além dos alunos do noturno, os estudantes do período diurno também foram contrários à medida porque planejavam estudar futuramente durante a noite. A maioria dos moradores da região é de família de baixa renda e precisa trabalhar durante o dia. (https://correio.rac.com.br, 11.09.2021. Adaptado.) Texto 2 Entre 2000 e 2024, o Brasil perdeu 110 758 escolas rurais ou do campo, segundo levantamento do Fórum Nacional de Educação do Campo (Fonec) com dados do Instituto Nacional de Estudos e Pesquisas Educacionais Anísio Teixeira (Inep). Críticos afirmam que muitas decisões de encerramento ocorrem sem consulta real às comunidades, ferindo normas que deveriam exigir consulta prévia, e que o fechamento de escolas do campo representa um enfraquecimento do direito à educação e da permanência dos jovens no campo. (https://jornalggn.com.br, 16.02.2026. Adaptado.)',null,'["efetivação de direitos sociais que dependem da atuação do poder público para garantir condições de acesso à educação.", "ampliação de direitos civis ligados à liberdade individual de escolha sobre a permanência nas instituições escolares.", "consolidação de direitos políticos associados à participação eleitoral das comunidades locais.", "afirmação de direitos individuais relacionados à administração territorial e ao ordenamento institucional das comunidades.", "proteção de direitos naturais relacionados à autonomia das famílias na definição das formas de escolarização disponíveis."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Sociologia','O caso apresentado na notícia evidencia que as desigualdades étnico-raciais nas sociedades contemporâneas relacionam-se','Um turista argentino de 63 anos foi preso em Tiradentes, Minas Gerais, suspeito de fotografar e filmar um menino negro de sete anos dentro da locomotiva a vapor que liga São João del-Rei à cidade histórica. Segundo o boletim de ocorrência, o homem compartilhou as imagens em um aplicativo de mensagens com comentários racistas, entre eles: “Posso levá-lo como escravo”. Ao ser confrontado pela mãe do menino, o suspeito desbloqueou o aparelho voluntariamente, e ela conseguiu visualizar a conversa em que as imagens do filho haviam sido enviadas com mensagens racistas. Em outra mensagem localizada no celular, segundo a mãe, o argentino dizia que queria levar um escravo para cuidar das netas da pessoa com quem conversava. (https://oglobo.globo.com, 25.05.2026. Adaptado.)',null,'["à compreensão de que as desigualdades sociais se baseiam na posição econômica dos indivíduos.", "ao fortalecimento dos mecanismos jurídicos voltados à proteção contra práticas discriminatórias.", "à valorização da diversidade cultural como princípio orientador das relações sociais contemporâneas.", "à atualização dos significados históricos da escravidão em novos contextos sociais.", "à permanência de práticas discriminatórias vinculadas a processos históricos de racialização e exclusão social."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Geografia','Uma intervenção antrópica que aumenta a vulnerabilidade ambiental dos igarapés é','Os cursos d’água atuam como sistemas de fluxo contínuo, redistribuindo sedimentos e materiais provenientes da paisagem. Esse processo pode ser alterado por intervenções antrópicas, que modificam a estabilidade dos rios urbanos. Em cidades como Manaus, onde os igarapés desempenham um papel importante na drenagem e no equilíbrio ecológico, a urbanização desordenada tem provocado impactos nesses corpos d’água, comprometendo sua estabilidade e aumentando a vulnerabilidade ambiental. (Alan Kristian Nunes Machado et al. Revista Sociedade & Natureza, vol. 38, 2026. Adaptado.)',null,'["a implantação de parques lineares.", "o desassoreamento dos leitos.", "a ampliação de áreas de drenagem.", "a retirada da mata ciliar.", "o monitoramento da poluição."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Geografia','A estratégia de mercado da China, apresentada no excerto, está relacionada','A China há muito tempo domina a manufatura global, graças à sua competitividade de custos e às cadeias de suprimento integradas. Essa força permanece intacta apesar das tarifas mais altas dos Estados Unidos (EUA) em 2025, que agora se estabilizaram em torno de 50%. As tarifas mal afetaram o comércio chinês: a participação do país nas exportações globais de bens se manteve em cerca de 14%, quatro vezes maior do que a de Índia e Vietnã juntos. As exportações de bens para os EUA representam apenas 2% a 3% do Produto Interno Bruto (PIB) chinês, e mais da metade das exportações de bens da China agora vai para economias do Sul Global. (www.infomoney.com.br, 13.01.2026. Adaptado.)',null,'["à divisão internacional do trabalho fomentada pela especialização produtiva das commodities chinesas.", "à diversificação chinesa de parceiros comerciais para a venda de bens e mercadorias de alto valor agregado.", "à dominação político-econômica dos investimentos transnacionais na zona econômica especial chinesa.", "ao modelo de planejamento estatal central implementado no decorrer do governo chinês de Mao Tsé-Tung.", "ao processo de transnacionalização da economia chinesa com a atuação direta no bloco econômico do BRICS."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Geografia','Os dados apresentados no gráfico correspondem às reservas e à produção mineral de','Analise o gráfico que apresenta informações sobre as reservas e a produção de determinado recurso mineral em escala mundial em 2024. (https://revistapesquisa.fapesp.br, 02.10.2025. Adaptado.)','["/pmsp/oficial-2026/q17-14-figura-1.png"]','["carvão.", "terras-raras.", "nióbio.", "ferro gusa.", "bauxita."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Geografia','Um dos objetivos do projeto Trens Intercidades (TICs) é o de integrar','Analise a imagem que apresenta o projeto de integração ferroviária entre cidades paulistas, chamado Trens Intercidades (TICs). (https://revistaoe.com.br, 06.09.2025. Adaptado.)','["/pmsp/oficial-2026/q18-15-figura-1.png"]','["as cidades médias, devido à criação de polos econômicos e tecnológicos.", "a megalópole, devido à formação da zona de conurbação entre as cidades.", "a cidade-região, devido à centralidade do arranjo produtivo no setor sucroalcooleiro.", "os centros regionais, devido à presença de corredores de exportação entre as cidades.", "a macrometrópole, devido aos intensos fluxos logísticos entre as cidades."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Geografia','O fenômeno meteorológico mencionado no excerto impacta diretamente a produção agrícola brasileira. Na região Sul e na região Centro-Oeste, esses impactos são, respectivamente,','O El Niño retornou no fim de abril de 2026 e se consolidou ao longo de maio de 2026, com impactos diretos na safra de soja 2026/27. A tendência é que o fenômeno comece com intensidade moderada, mas que ganhe força ao longo dos meses, podendo evoluir para um cenário de “super El Niño”. (Gabriel Almeida. www.canalrural.com.br, 13.04.2026. Adaptado.)',null,'["a incidência de doenças provocadas por fungos, devido à elevada umidade; e a redução da umidade no solo, devido à escassez de chuvas.", "o aumento da erosão laminar do solo, devido ao excesso de precipitação; e o atraso na colheita de grãos, devido aos volumes de chuva acima de média anual.", "o tombamento das lavouras, devido às rajadas fortes de ventos; e o aumento da umidade no solo, devido às chuvas torrenciais.", "a incidência de queimadas, devido às altas temperaturas; e o processo de lixiviação do solo, devido ao longo período de estiagem.", "o atraso na colheita de grãos, devido à formação de intensas geadas; e o aumento da erosão laminar do solo, devido ao excesso de precipitação."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Geografia','A distribuição da infraestrutura para a transmissão de dados por fibra óptica é','Analise o mapa publicado no perfil @espacialidade do Instagram em 24.05.2026. Infraestrutura para a transmissão de dados por fibra óptica no Brasil (www.instagram.com. Adaptado.)','["/pmsp/oficial-2026/q20-17-figura-1.png"]','["espraiada na região Norte, devido às limitações técnicas que remontam ao período da formação colonial.", "irradiada no litoral da região Nordeste, devido aos polos universitários que geram pesquisas em tecnologia.", "adensada na região Sudeste, devido à alta densidade técnica que acompanha a hierarquia urbana.", "concentrada na região Sul, devido à concentração de população relativa que demanda serviços técnicos.", "dinamizada na região Centro-Oeste, devido à localização da capital nacional que exige investimentos informacionais."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Língua Portuguesa','No trecho transcrito, o narrador caracteriza Marcela como uma pessoa movida, sobretudo,','Para responder às questões de 21 a 28, leia o capítulo XVI e o início do capítulo XVII do romance Memórias póstumas de Brás Cubas, de Machado de Assis. Capítulo XVI Uma reflexão imoral Ocorre-me uma reflexão imoral, que é ao mesmo tempo uma correção de estilo. Cuido haver dito, no cap. XIV, que Marcela morria de amores pelo Xavier. Não morria, vivia. Viver não é a mesma coisa que morrer; assim o afirmam todos os joalheiros desse mundo, gente muito vista na gramática. Bons joalheiros, que seria do amor se não fossem os vossos dixes¹ e fiados? Um terço ou um quinto do universal comércio dos corações. Esta é a reflexão imoral que eu pretendia fazer, a qual é ainda mais obscura do que imoral, porque não se entende bem o que eu quero dizer. O que eu quero dizer é que a mais bela testa do mundo não fica menos bela, se a cingir um diadema de pedras finas; nem menos bela, nem menos amada. Marcela, por exemplo, que era bem bonita, Marcela amou-me... Capítulo XVII Do trapézio e outras coisas ... Marcela amou-me durante quinze meses e onze contos de réis; nada menos. Meu pai, logo que teve aragem² dos onze contos, sobressaltou-se deveras; achou que o caso excedia as raias de um capricho juvenil. — Desta vez, disse ele, vais para a Europa; vais cursar uma universidade, provavelmente Coimbra; quero-te para homem sério e não para arruador e gatuno. E como eu fizes-se um gesto de espanto: — Gatuno, sim, senhor; não é outra coisa um filho que me faz isto... Sacou da algibeira os meus títulos de dívida, já resgatados por ele, e sacudiu-mos na cara. — Vês, peralta? é assim que um moço deve zelar o nome dos seus? Pensas que eu e meus avós ganhamos o dinheiro em casas de jogo ou a vadiar pelas ruas? Pelintra³! Desta vez ou tomas juízo, ou ficas sem coisa nenhuma. Estava furioso, mas de um furor temperado e curto. Eu ouvi-o calado, e nada opus à ordem da viagem, como de outras vezes fizera; ruminava a ideia de levar Marcela comigo. Fui ter com ela; expus-lhe a crise e fiz-lhe a proposta. Marcela ouviu-me com os olhos no ar, sem responder logo; como insistisse, disse-me que ficava, que não podia ir para a Europa. (Memórias póstumas de Brás Cubas, 2001.) ¹ dixes: joias. ² aragem: vento, brisa (por figura, evaporação, sumiço). ³ pelintra: sem-vergonha.',null,'["pelo arrebatamento da paixão.", "pelo ciúme excessivo.", "pela lógica da vingança.", "pelo interesse material.", "pela vaidade desmedida."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Língua Portuguesa','No Capítulo XVI, o narrador lança mão de um procedimento estilístico bastante característico da prosa madura de Machado de Assis, a saber,','Para responder às questões de 21 a 28, leia o capítulo XVI e o início do capítulo XVII do romance Memórias póstumas de Brás Cubas, de Machado de Assis. Capítulo XVI Uma reflexão imoral Ocorre-me uma reflexão imoral, que é ao mesmo tempo uma correção de estilo. Cuido haver dito, no cap. XIV, que Marcela morria de amores pelo Xavier. Não morria, vivia. Viver não é a mesma coisa que morrer; assim o afirmam todos os joalheiros desse mundo, gente muito vista na gramática. Bons joalheiros, que seria do amor se não fossem os vossos dixes¹ e fiados? Um terço ou um quinto do universal comércio dos corações. Esta é a reflexão imoral que eu pretendia fazer, a qual é ainda mais obscura do que imoral, porque não se entende bem o que eu quero dizer. O que eu quero dizer é que a mais bela testa do mundo não fica menos bela, se a cingir um diadema de pedras finas; nem menos bela, nem menos amada. Marcela, por exemplo, que era bem bonita, Marcela amou-me... Capítulo XVII Do trapézio e outras coisas ... Marcela amou-me durante quinze meses e onze contos de réis; nada menos. Meu pai, logo que teve aragem² dos onze contos, sobressaltou-se deveras; achou que o caso excedia as raias de um capricho juvenil. — Desta vez, disse ele, vais para a Europa; vais cursar uma universidade, provavelmente Coimbra; quero-te para homem sério e não para arruador e gatuno. E como eu fizes-se um gesto de espanto: — Gatuno, sim, senhor; não é outra coisa um filho que me faz isto... Sacou da algibeira os meus títulos de dívida, já resgatados por ele, e sacudiu-mos na cara. — Vês, peralta? é assim que um moço deve zelar o nome dos seus? Pensas que eu e meus avós ganhamos o dinheiro em casas de jogo ou a vadiar pelas ruas? Pelintra³! Desta vez ou tomas juízo, ou ficas sem coisa nenhuma. Estava furioso, mas de um furor temperado e curto. Eu ouvi-o calado, e nada opus à ordem da viagem, como de outras vezes fizera; ruminava a ideia de levar Marcela comigo. Fui ter com ela; expus-lhe a crise e fiz-lhe a proposta. Marcela ouviu-me com os olhos no ar, sem responder logo; como insistisse, disse-me que ficava, que não podia ir para a Europa. (Memórias póstumas de Brás Cubas, 2001.) ¹ dixes: joias. ² aragem: vento, brisa (por figura, evaporação, sumiço). ³ pelintra: sem-vergonha.',null,'["a abordagem nostálgica do passado.", "o discurso socialmente engajado.", "o recurso à metalinguagem.", "o discurso apoiado em argumentos científicos.", "a argumentação de teor moralizante."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2026-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
