_technology.pdf',null,'["can generate a few obstacles.", "seem to be firmly established.", "may cause too many problems.", "could eliminate human workforce.", "might be replaced by other systems."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
