insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Língua Estrangeira','The speech “Don’t try to sneak a water bottle past security this time” implies that the character in the cartoon','Text II From: https://www.cartoonmovement.com/cartoon/facial-recognition-0','["/pmsp/oficial-2025/q43-18-figura-1.png"]','["enjoyed having lunch before travelling.", "needed to drink water for medical reasons.", "transgressed the rule on a previous occasion.", "is aware of how comprehensive the system is.", "has no idea why security is warning him now."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Matemática','Uma hamburgueria oferece dois tipos de hambúrgueres: clássico e premium. Um hambúrguer premium é 25% mais caro quando comparado a um hambúrguer clássico. Além disso, um suco de laranja custa a metade do valor de um hambúrguer premium. Um hambúrguer clássico, um hambúrguer premium e dois sucos de laranja custam, juntos, R$ 84,00. Com base nessas informações, é correto concluir que a diferença entre os preços de um hambúrguer premium e de um hambúrguer clássico é de',null,null,'["R$ 4,00.", "R$ 5,00.", "R$ 6,00.", "R$ 8,00.", "R$ 10,00."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
