insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Matemática','Uma dada função 𝑓, ao receber qualquer valor real, subtrai desse valor três unidades, eleva essa diferença ao quadrado e, por fim, multiplica o resultado da potência por quatro. Sejam 𝑥₁ e 𝑥₂ valores reais tais que 𝑓(𝑥₁) = 𝑓(𝑥₂) = 25, com 𝑥₁ > 𝑥₂. O valor de 𝑥₁ −𝑥₂ é',null,null,'["6,0.", "5,5.", "5,0.", "4,5.", "4,0."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Matemática','Em uma caixa, há exatamente 10 balas, sendo 6 delas de leite e as demais, de coco. Exatamente duas balas serão retiradas aleatoriamente da caixa, uma de cada vez, sem reposição. A probabilidade de que se obtenha pelo menos uma bala de coco é',null,'["/pmsp/oficial-2025/q48-22-figura-1.png"]','["4/9.", "1/3.", "2/5.", "1/2.", "2/3."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Matemática','A figura ilustra duas circunferências concêntricas, de centro em 𝑂, sobre as quais se constrói um circuito fechado 𝐴𝐵𝐶𝐷𝐴, formado pelos segmentos de reta 𝐴𝐵 e 𝐶𝐷, intercalados por dois arcos de circunferência 𝐴𝐷 e 𝐵𝐶. Os pontos 𝐴 e 𝐷 pertencem à circunferência de raio 5 cm e os pontos 𝐵 e 𝐶, à circunferência de raio 2 cm. O arco 𝐴𝐷 mede 240° e os prolongamentos de 𝐴𝐵 e 𝐶𝐷 contêm o ponto 𝑂. Considerando-se 𝜋 igual a 3, o comprimento do circuito completo é',null,'["/pmsp/oficial-2025/q49-23-figura-1.png"]','["20 cm.", "24 cm.", "27 cm.", "30 cm.", "36 cm."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Matemática','Representada sobre um plano cartesiano, uma reta 𝑟 contém os pontos (1, 4) e (3, 10). Nesse mesmo sistema de coordenadas, uma reta 𝑠 paralela à reta 𝑟 contém o ponto (1, 0). É correto concluir que 𝑠 intersecta o eixo das ordenadas no ponto',null,null,'["(0, –4).", "(0, –3).", "(0, –2).", "(0, –1).", "(0, 0)."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,51,'Matemática','A soma dos 7 termos de certa progressão aritmética é 77. É correto concluir que o 4º termo dessa progressão vale',null,null,'["7.", "11.", "14.", "18.", "22."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,52,'Matemática','A média aritmética de 4 números inteiros positivos é 9. A mediana da lista formada por eles vale 8. Se a diferença entre o maior e o menor desses números é igual a 10, então o maior deles é',null,null,'["15.", "14.", "12.", "11.", "10."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,53,'Matemática','Para definir uma senha de 5 dígitos para o seu cofre, Aluísio escolheu, inicialmente, os dois dígitos do dia e os dois dígitos do mês de seu aniversário. De posse desses 4 dígitos, ele os distribuiu nas quatro posições de uma matriz 2 x 2 de modo que o determinante dessa matriz fosse o maior possível. A senha foi então formada pela ordenação decrescente desses 5 dígitos: os 4 da data e o determinante máximo. Sabendo-se que Aluísio nasceu no penúltimo dia do ano, é correto afirmar que a senha do seu cofre é',null,null,'["32100.", "53210.", "63210.", "63211.", "73210."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,54,'Matemática','Diariamente, a altura H (em metros) da maré em certo cais pode ser modelada por H(t) = 1,4 + 0,5 × sen((π/6)t + π/10), com 0 ≤ t < 24, em que t é o tempo decorrido, em horas, desde a meia-noite. Nesse local, a altura máxima atingida pela maré, em metros, ao longo de um dia é',null,null,'["0,90.", "1,65.", "1,40.", "1,85.", "1,90."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,55,'Matemática','Uma cafeteria gourmet recebeu, de seus fornecedores, 8 tipos diferentes de cafés especiais numerados de 1 a 8. Para um evento exclusivo, o gerente deseja escolher 3 desses tipos de café para uma degustação. No entanto, ele sabe que os cafés nº 2 e nº 7 têm sabores muito parecidos. Por isso, ele decide que, se um desses for escolhido, o outro não poderá ser. Nessas condições, o número de opções distintas de que o gerente dispõe para oferecer nessa degustação é',null,null,'["30.", "35.", "36.", "50.", "56."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,56,'Matemática','Um indivíduo está de pé sobre uma rua horizontal olhando fixamente para o topo de um poste vertical de 6 metros de altura. Quando o indivíduo estava em uma posição em que o ângulo de elevação do seu olhar era 30°, ele caminhou 5 metros na direção do poste, se aproximando deste, até parar no ponto em que o ângulo de elevação do olhar passou a ser de 60°. Considerando-se 1,7 como aproximação para a √3, é correto afirmar que a altura dos olhos do indivíduo, em metros, é',null,null,'["1,65.", "1,75.", "1,80.", "1,85.", "1,90."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,57,'Física','Uma partícula parte do repouso e mantém aceleração constante durante um intervalo de tempo t. Continua em movimento progressivo, mantendo velocidade constante pelo mesmo intervalo de tempo t. Em seguida, desacelera com aceleração constante, levando um intervalo de tempo 2t para retornar ao repouso. O movimento é horizontal e retilíneo. O gráfico que melhor representa a variação da posição em função do tempo do movimento descrito é:','Figuras das alternativas A, B, C, D e E, nessa ordem.','["/pmsp/oficial-2025/q57-25-alternativa-1.png", "/pmsp/oficial-2025/q57-25-alternativa-2.png", "/pmsp/oficial-2025/q57-25-alternativa-3.png", "/pmsp/oficial-2025/q57-25-alternativa-4.png", "/pmsp/oficial-2025/q57-25-alternativa-5.png"]','["Figura da alternativa A (ver apoio).", "Figura da alternativa B (ver apoio).", "Figura da alternativa C (ver apoio).", "Figura da alternativa D (ver apoio).", "Figura da alternativa E (ver apoio)."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,58,'Física','Considere o vagão de um trem em movimento, conforme representado na figura a seguir. Um observador externo observa um pêndulo preso ao teto do vagão deslocado da direção vertical, indicada pela linha pontilhada. Sabendo que o vagão se desloca em trajetória horizontal e retilínea, ele pode estar se movimentando de',null,'["/pmsp/oficial-2025/q58-26-figura-1.png"]','["X para Y, com velocidade constante.", "Y para X, com sua velocidade diminuindo.", "X para Y, com sua velocidade aumentando.", "Y para X, com sua velocidade aumentando.", "Y para X, com velocidade constante."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,59,'Física','A figura representa quatro blocos de massas iguais a 10 kg apoiados em um plano horizontal perfeitamente liso. Aplica-se ao corpo A uma força horizontal F = 8 N. O módulo da força que o corpo C exerce sobre o corpo B tem módulo igual a',null,'["/pmsp/oficial-2025/q59-26-figura-1.png"]','["2 N.", "4 N.", "6 N.", "8 N.", "10 N."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,60,'Física','A figura representa um carrinho que parte do repouso no ponto X a uma altura de 28 m, e percorre um trecho de montanha russa até chegar ao ponto y, com altura igual a 8 m. Considere que não há forças dissipativas, e o valor da aceleração da gravidade é de 10 m/s². A velocidade com que o carrinho chega ao ponto y é',null,'["/pmsp/oficial-2025/q60-26-figura-1.png"]','["8 m/s.", "10 m/s.", "20 m/s.", "28 m/s.", "40 m/s."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,61,'Física','Um estudante no nível do mar recebe um termômetro com escala termométrica desconhecida. Para estudá-lo, seu professor propõe que o termômetro seja inserido em um recipiente contendo água com gelo. Nesse caso, o termômetro acusa um valor de −4. Em seguida, o professor pede que o termômetro seja inserido em um recipiente com água em ebulição. O estudante verifica que o termômetro passa a indicar +116. A única temperatura em que o termômetro estudado e um outro termômetro graduado na escala Celsius indicam a mesma temperatura é',null,null,'["10 oC.", "20 oC.", "30 oC.", "40 oC.", "60 oC."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,62,'Física','Duas esferas puntiformes e idênticas estão carregadas com cargas iguais e separadas no vácuo. Quando as esferas estão a 0,2 m de distanciamento, a força elétrica entre elas é de 4000 N. Para que a intensidade da força elétrica seja igual a 250 N, as esferas devem ficar separadas de',null,null,'["0,3 m.", "0,4 m.", "0,5 m.", "0,8 m.", "1,0 m."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,63,'Química','Recentemente o mundo acompanhou a escolha de um novo papa. Quando o conclave papal se reúne para a eleição, a fumaça da queima das cédulas dos cardeais indica o resultado. A fumaça branca é a sinalização que uma decisão foi tomada. Tal fumaça é produzida a partir da mistura de clorato de potássio, lactose e breu (resina de pinheiro). O sal inorgânico utilizado na produção da fumaça branca possui a seguinte fórmula química:',null,'["/pmsp/oficial-2025/tabela-periodica-1.png"]','["KCl.", "KClO.", "KClO₂.", "KClO₃.", "KClO₄."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,64,'Química','O gás cloro (Cl₂) é bastante utilizado em estações de tratamento de água e esgotos. Uma de suas aplicações está na remoção de sulfeto de hidrogênio (H₂S), resultante da decomposição da matéria orgânica, que confere um odor desagradável à água, similar a ovo podre. O gás cloro converte o H₂S em enxofre elementar (S₈) gerando, ainda, HCl como subproduto. A reação não balanceada que descreve o processo é dada a seguir: Cl2(g) + H₂S(aq) → S8(s) + HCl(aq) Após balanceamento da reação, é possível prever que a razão entre a quantidade de enxofre elementar formado e a de gás cloro empregado no tratamento deve ser de',null,'["/pmsp/oficial-2025/tabela-periodica-1.png"]','["1/8.", "1/4.", "1/2.", "4.", "8."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,65,'Química','A Química está intrinsecamente associada ao nosso cotidiano, desempenhando papel fundamental na produção de novos materiais, medicamentos e artefatos industriais. A partir do conhecimento das propriedades dos compostos químicos é possível fazer algumas previsões. Observe a tabela a seguir que contém os pontos de fusão e ebulição de três substâncias distintas. Fusão (°C) Ebulição (°C) Substância 1 –95 –30 2 –3 112 3 88 145 A partir das informações é possível prever que os estados físicos das substâncias 1, 2 e 3, à temperatura ambiente (25°C), devem ser, respectivamente,',null,'["/pmsp/oficial-2025/q65-28-figura-1.png", "/pmsp/oficial-2025/tabela-periodica-1.png"]','["sólido, líquido e gasoso.", "gasoso, líquido e sólido.", "sólido, gasoso e líquido.", "gasoso, gasoso e sólido.", "sólido, líquido e sólido."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,66,'Química','A partir da posição dos elementos na Classificação Periódica dos Elementos é possível relacionar suas informações e estabelecer de forma lógica suas propriedades e comportamentos em reações. Observe a tabela a seguir, que contém características de três elementos químicos. Elemento Características Elemento representativo com dois níveis de X energia e que possui quatro elétrons no seu último nível. Metal alcalino terroso de menor raio atômico do Y seu grupo. Elemento que forma com metais alcalinos Z composto iônico de fórmula A₂Z e possui o maior potencial de ionização do seu grupo. Os elementos X, Y e Z correspondem, respectivamente, a',null,'["/pmsp/oficial-2025/q66-29-figura-1.png", "/pmsp/oficial-2025/tabela-periodica-1.png"]','["C, Be e F.", "Al, Li e F.", "C, Li e F.", "Al, Be e O.", "C, Be e O."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,67,'Química','O descarte incorreto de lixo eletrônico, como aparelhos celulares e computadores usados, tem provocado preocupações tanto ambientais quanto econômicas, por conta da presença de vários metais nas placas e peças desses dispositivos. Para recuperar esses metais e reduzir os danos gerados, é preciso separá-los dos materiais plásticos e cerâmicos que também compõem as placas eletrônicas. Após moagem das placas eletrônicas, o processo mais adequado para separar metais sólidos das demais partes trituradas não metálicas é a',null,'["/pmsp/oficial-2025/tabela-periodica-1.png"]','["destilação.", "imantação.", "peneiração.", "decantação.", "cristalização."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,68,'Química','Em um recipiente fechado misturam-se, sob condições adequadas de temperatura e pressão, gás nitrogênio (N₂) e gás hidrogênio (H₂), que reagem entre si segundo equação química balanceada: N2(g) + 3H2(g) → 2NH3(g) A mistura inicial é representada na figura a seguir, na qual os círculos escuros representam os átomos de nitrogênio e os círculos claros os átomos de hidrogênio. De modo a obedecer a lei da conservação da massa, o diagrama que representa uma possível mistura final, após a reação gerar o produto NH₃, é','Figuras das alternativas A, B, C, D e E, nessa ordem.','["/pmsp/oficial-2025/q68-30-figura-1.png", "/pmsp/oficial-2025/q68-30-alternativa-1.png", "/pmsp/oficial-2025/q68-30-alternativa-2.png", "/pmsp/oficial-2025/q68-30-alternativa-3.png", "/pmsp/oficial-2025/q68-30-alternativa-4.png", "/pmsp/oficial-2025/q68-30-alternativa-5.png", "/pmsp/oficial-2025/tabela-periodica-1.png"]','["Figura da alternativa A (ver apoio).", "Figura da alternativa B (ver apoio).", "Figura da alternativa C (ver apoio).", "Figura da alternativa D (ver apoio).", "Figura da alternativa E (ver apoio)."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,69,'Biologia','Conhecer a composição química do material genético e compreender como ele funciona, é fundamental para a prevenção e solução de várias questões relacionadas à saúde, ao bem-estar e ao meio ambiente. Com relação a esse tema, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A molécula de DNA é composta por uma dupla cadeia de polinucleotídeos; cada nucleotídeo é formado por uma base nitrogenada, um açúcar e um fosfato. Em uma fita única de DNA, a ligação entre os nucleotídeos se faz entre o açúcar de um nucleotídeo e a base nitrogenada do seguinte. ( ) Um organismo multicelular complexo, como o humano, é formado por muitos tipos de células. Por exemplo, um neurônio e uma célula muscular de uma mesma pessoa, embora tenham igual número de cromossomos, são diferentes, pois seus genes não são os mesmos. ( ) Fatores do ambiente, como certos tipos de alimentos e poluentes, podem influenciar a expressão dos genes de um indivíduo, ativando-os ou inativando-os, sem alterar a sequência de bases do DNA. As afirmativas são, respectivamente,',null,null,'["F – V – F.", "F – F – V.", "V – F – F.", "V – V – F.", "F – V – V."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,70,'Biologia','Apesar da inestimável contribuição dos antibióticos no combate às doenças infecciosas, sua administração pode provocar efeitos adversos nos pacientes, como é o caso do cloranfenicol. Essa droga impede a multiplicação de bactérias, ligando-se à subunidade 50S dos ribossomos procarióticos. Em função desse modo de ação, o cloranfenicol pode causar, em humanos, efeitos colaterais devido à interrupção da(o)',null,null,'["tradução de proteínas da parede celular.", "processo de transcrição do DNA mitocondrial.", "produção de RNA ribossomal a partir de DNA nuclear.", "síntese de proteínas codificadas pelo DNA mitocondrial.", "tradução do DNA nuclear para formação de RNA mensageiro."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,71,'Biologia','A figura mostra um experimento para comparar as trocas gasosas realizadas por uma planta nos processos de fotossíntese e respiração celular, em presença e ausência de luz. O vermelho de cresol é um indicador de pH. Ele apresenta coloração púrpura, em meio com baixa concentração de CO₂ (meio alcalino) e amarela, em meio com alta concentração de CO₂ (meio ácido). No início do experimento, todos os tubos apresentavam coloração vermelha. Após algumas horas, espera-se que a coloração do indicador no(s)',null,'["/pmsp/oficial-2025/q71-32-figura-1.png"]','["tubo 1 mude para amarela; a planta produzirá CO₂ por intermédio da respiração celular.", "tubo 2 mude para amarela; a planta absorverá CO₂ durante a fotossíntese.", "tubo 2 mude para púrpura; a planta não realizará a respiração celular e usará todo o CO₂ na fotossíntese.", "tubo 2 permaneça vermelha; o CO₂ produzido na fotossíntese será absorvido durante a respiração celular.", "tubos 1 e 3 permaneça vermelha; sem a ocorrência de fotossíntese, a concentração de CO₂ não será alterada."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,72,'Biologia','O fotógrafo Sebastião Salgado morreu no dia 23 de maio de 2025, aos 81 anos. Ele lidava com um distúrbio sanguíneo decorrente da malária que contraiu em 2010. A malária é uma doença infecciosa causada por',null,null,'["vírus, cujo vetor são as fêmeas infectadas dos mosquitos gênero Lutzomya, conhecidos como mosquitos-palha.", "protozoários do gênero Neisseria, cujo vetor são as fêmeas infectadas dos mosquitos do gênero Aedes, que têm hábitos diurnos.", "vírus, cujo vetor são as fêmeas infectadas dos mosquitos gênero Anopheles, também chamado de mosquitos-prego.", "protozoários do gênero Plasmodium, cujo vetor são as fêmeas infectadas dos mosquitos gênero Anopheles, também chamados de mosquitos-prego.", "bactérias do gênero Plasmodium, cujo vetor são as fêmeas infectadas dos mosquitos do gênero Aedes, que têm hábitos diurnos."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,73,'Biologia','No início do século XX, pesquisadores trabalharam em uma teoria que sintetizava os conceitos do darwinismo, as leis de Mendel e o que havia sido descoberto na Biologia. Esse trabalho deu origem à teoria atual, conhecida como Teoria Sintética da Evolução ou Neodarwinismo. Com relação à Teoria Sintética da Evolução, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A recombinação gênica é um fator evolutivo. Nos eucariontes, ela ocorre devido a um processo mitótico: a permutação, também chamada de crossing-over. ( ) Do ponto de vista evolutivo, o antibiótico atua como um agente seletivo que mata as bactérias selvagens e deixa os recursos à disposição das bactérias que, estimuladas pelo medicamento, criaram resistência a ele. Estas se reproduzem e dão origem a populações inteiras de bactérias resistentes contra as quais aquele antibiótico exerce pouco efeito. ( ) A embriologia e a anatomia mostram que as asas dos insetos e as das aves têm origem embrionária e estrutura anatômica diferentes, embora tenham a mesma função. Essas são as chamadas estruturas análogas e decorrem de um processo de evolução divergente. As afirmativas são, respectivamente,',null,null,'["F – F – V.", "V – F – F.", "V – F – V.", "F – V – F.", "F – F – F."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,74,'Biologia','Para se fazer o teste de identificação dos grupos sanguíneos dos sistemas ABO e Rh de uma pessoa, são necessárias três gotas de sangue: a uma delas se adiciona uma gota de soro com aglutinina anti-A; à outra, soro anti-B; e, à terceira, soro anti-Rh. Em determinada situação, duas mulheres (M e N) disputam a maternidade de um bebê, cujo sangue foi testado com o uso dos soros anti-A, anti-B e anti-Rh (anti-D). Os resultados são apresentados a seguir. Sobre as supostas mães sabe-se que: a mulher M tem o genótipo iidd; já a mulher N, que pertence ao grupo A, apresentou eritroblastose ao nascer. A possível mãe do bebê é a mulher',null,'["/pmsp/oficial-2025/q74-33-figura-1.png"]','["M, sendo seu fenótipo O positivo e o da criança, A positivo.", "N, sendo que os fenótipos dela e do bebê são A positivo.", "M, sendo que os fenótipos dela e do bebê são A negativo.", "N, sendo que os fenótipos dela e do bebê são A negativo.", "M, sendo seu fenótipo O negativo e o da criança, B positivo."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,75,'Noções de Administração Pública','Ao passar por determinada localidade, João, policial militar, constatou que se encontrava no interior de uma residência, debruçado sobre o peitoril da janela frontal, a mesma pessoa do sexo masculino que ele tinha perseguido uma semana antes, em razão da prática de crime de furto contra pedestre. Na situação descrita, é correto afirmar que João',null,null,'["pode ingressar na residência, sem o consentimento do morador, para prender a referida pessoa.", "somente pode ingressar na residência, sem o consentimento do morador, durante o dia, por determinação judicial.", "pode ingressar na residência, se houver consentimento do morador ou determinação judicial, durante o dia ou à noite.", "pode ingressar na residência, a exemplo de qualquer pessoa do povo, com ou sem o consentimento do morador, pois a pessoa está em flagrante delito.", "deve comunicar o fato à autoridade que conduz a investigação do crime de furto, a qual pode ingressar na residência, sem o consentimento do morador, para prender a referida pessoa."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,76,'Noções de Administração Pública','O Governador do Estado Alfa pretende nomear uma pessoa com grande expertise na área de planejamento urbano, que até então atuava exclusivamente na iniciativa privada, para chefiar uma estrutura administrativa incumbida da realização da referida atividade de planejamento. Considerando que a referida pessoa não foi previamente aprovada em concurso público, é correto afirmar, à luz da Constituição do Estado de São Paulo, que',null,null,'["essa espécie de nomeação é vedada.", "é possível nomeá-la para ocupar cargo em comissão.", "é possível nomeá-la para o exercício de função de confiança.", "é possível nomeá-la para ocupar cargo de provimento efetivo.", "somente é possível celebrar contrato temporário com essa pessoa."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,77,'Noções de Informática','Um usuário do MS Windows 10 BR pressionou, no teclado, a tecla “Windows” e digitou o comando “cmd” para abrir o prompt de comando. No prompt de comando, para acessar a pasta “relatórios” que está na pasta “documentos”, o usuário deve digitar o seguinte comando:',null,null,'["dir documents\\relatorios", "md documents\\relatorios", "cd documents\\relatorios", "cls documents\\relatorio", "list documents\\relatorio"]'::jsonb,'A/B/C/D/E','Questão anulada no gabarito definitivo.' from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,78,'Noções de Informática','Um soldado, para realizar o levantamento da compra de alguns itens que fazem parte do uniforme de Cabo da Polícia Militar do Estado de São Paulo, criou a seguinte planilha no MS Excel 2016 BR: Na célula D2 inseriu a fórmula =C$2*$B2 e, com o mouse, clicou e arrastou a alça de preenchimento para baixo até a célula D6. Na célula D7, para determinar o valor total da compra dos itens, inseriu a fórmula =SOMA(D2:D6) e apresentou essa planilha a seu superior. Ao conferir a planilha, o superior verificou que alguns dos valores apresentados na coluna “Total” estavam corretos porque a fórmula usada para multiplicar os valores das colunas “Quant” e “Valor” estava incorreta. Dessa forma, para que os valores da coluna “Total” sejam corretamente ajustados, a fórmula correta que deverá ser inserida na célula D2 para depois ser arrastada pela alça de preenchimento até a célula D6 é',null,'["/pmsp/oficial-2025/q78-35-figura-1.png"]','["=C2*B2", "=C2+B2", "=C$2*$B2", "=$C$2*B2", "=C$2*$B$2"]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,79,'Noções de Informática','Um usuário do Google Chrome estava navegando na Internet por meio de inúmeras guias abertas no navegador, mas, sem querer, acabou fechando uma dessas guias. Nesse caso, para reabrir a última guia fechada, o usuário deverá acionar o seguinte atalho de teclado:',null,null,'["Ctrl + L", "Ctrl + J", "Ctrl + Shift + N", "Ctrl + Shift + R", "Ctrl + Shift + T"]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,80,'Noções de Informática','Acerca dos ambientes Google Workspace, associe as ferramentas listadas a seguir às respectivas funções. 1. Meet 2. Drive 3. Google Calendar ( ) Facilita o armazenamento e compartilhamento de arquivos, permitindo o acesso online e colaborativo. ( ) Permite videoconferências e chamadas de voz, facilitando a comunicação em tempo real e a realização de reuniões online. ( ) Ajuda a organizar e gerenciar eventos e reuniões, permitindo que as pessoas saibam quando e onde precisam estar. Assinale a opção que indica a associação correta, na ordem apresentada.',null,null,'["1 – 3 – 2.", "1 – 2 – 3.", "2 – 3 – 1.", "2 – 1 – 3.", "3 – 1 – 2."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exams(slug,title,source,year) values ('pmsp-oficial-2025-espanhol','PM São Paulo · Oficial · 2025 · 13/07/2025 · Espanhol','pmerj','2025') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'História','Analise se as afirmativas a seguir, que mencionam fatores que contribuíram para a crise do sistema feudal durante o período medieval, são falsas (F) ou verdadeiras (V). ( ) A Peste Negra resultou em um expressivo descenso populacional, eliminando grande parte da mão de obra europeia disponível e desencadeando um processo de desorganização social, econômica e produtiva. ( ) As revoltas camponesas, que resistiam às obrigações feudais e exigiam melhores condições de trabalho, contribuíram para o declínio do sistema feudal e para o avanço das transformações sociais na Idade Média. ( ) A expansão das Cruzadas estimulou o surgimento de rotas comerciais que favoreceram o desenvolvimento do comércio e contribuíram para o enfraquecimento das estruturas do sistema feudal. As afirmativas são, respectivamente,',null,null,'["V – V – F.", "V – F – F.", "F – F – V.", "F – V – F.", "V – V – V."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'História','Leia o trecho a seguir. A posição dos moradores do hemisfério americano foi, por séculos, puramente passiva; sua existência política era nula. Nós estávamos em um grau ainda mais baixo de servidão e, por isso, com mais dificuldade para nos elevarmos ao gozo da liberdade. Adaptado de: Bolívar, Simón. Carta de Jamaica, 1815. O trecho é da Carta da Jamaica, de Simón Bolívar, e trata da independência do continente americano em relação à monarquia hispânica. Assinale a afirmativa correta acerca do projeto de Simón Bolívar para a América.',null,null,'["O projeto considerava que os verdadeiros cidadãos da monarquia hispânica eram os espanhóis nascidos na Espanha, e não os americanos.", "O projeto defendia que a América deveria continuar sob o domínio político da Espanha, desde que fossem realizadas reformas administrativas.", "O projeto rejeitava o uso da força para conquistar a liberdade do continente americano em relação à monarquia hispânica, preferindo caminhos pacíficos.", "O projeto condenava a liberdade comercial imposta pela monarquia hispânica e defendia uma política de proteção econômica que favorecesse os interesses dos americanos.", "O projeto buscava a unificação dos territórios americanos, propondo a criação de uma federação que integrasse a América de maneira unificada."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'História','Analise o trecho a seguir, extraído da crônica do Padre Simão de Vasconcellos, jesuíta que esteve no Brasil e escreveu sobre os primeiros contatos dos europeus com os indígenas brasileiros. E como a curiosidade do homem em procurar saber é tão natural, pretenderam tirar dos índios algumas respostas das dúvidas que tinham e faziam-lhes as seguintes perguntas. Quando os primeiros progenitores de suas gentes entraram a povoar aquelas suas terras? De que parte do mundo vieram? De que nação eram? Por onde, e de que maneira passaram a terras tão remotas, sendo que, não havia entre os antigos embarcações muito mais avançadas do que suas ordinárias canoas? Como não conservaram suas cores? Como não conservaram suas línguas? Como chegaram a degenerar seus costumes? Como alguns dos seus, especialmente os tapuias, chegaram a um estado tão grosseiro que se pode duvidar se eles nasceram de homens, ou se são indivíduos da espécie humana? E, finalmente, perguntavam quais bondades tinham esta terra e este clima em que vivem? Essas e outras perguntas semelhantes iam fazendo os nossos exploradores aos Índios, segundo as ocasiões que achavam. Adaptado de: Vasconcelos, Simão. Crônica da Companhia de Jesus, 1668, p. 58. Com base no trecho, é correto afirmar que a atitude dos europeus durante o primeiro contato com os indígenas que habitavam o Brasil foi marcada pela',null,null,'["exaltação dos costumes nativos, vistos como uma expressão de um estado natural e moralmente superior da condição humana, por não estarem corrompidos pelos vícios da sociedade europeia.", "curiosidade em relação aos costumes nativos, motivada pelo interesse em obter conhecimento histórico e geográfico sobre o território, ainda que permeada por visões negativas sobre determinados grupos.", "vontade de aprender com os povos indígenas sobre suas histórias, demonstrando uma postura de desprendimento de preconceitos, com disposição para compreender o outro sem pré-julgamentos.", "rejeição ao conhecimento tradicional desses povos sobre suas histórias, impondo uma narrativa eurocêntrica, valorizada por sua associação ao saber universitário europeu.", "indiferença em relação ao saber geográfico indígena sobre o mundo natural, privilegiando suas próprias experiências no território como única base legítima para a construção do conhecimento sobre o local."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'História','A charge, intitulada “O Velho Cordão da Gente Nova”, mostra, em primeiro plano, um grupo de homens formalmente vestidos, apresentados como foliões, liderados por Getúlio Vargas, que carrega uma bandeira com os dizeres “Há uma forte corrente a nosso favor”. Ao fundo, vê-se uma multidão fantasiada, em alusão ao carnaval de rua. Assinale a opção que identifica corretamente um elemento do Governo Provisório de Getúlio Vargas representado na charge.','Observe a charge a seguir. (Fonte: Capa da Revista Careta (RJ), 17 de fevereiro de 1934. Adaptado)','["/pmsp/oficial-2025/q4-6-figura-1.png"]','["A continuidade da influência das oligarquias da República Velha no governo de Getúlio Vargas.", "As reformas inovadoras implementadas por Getúlio Vargas que ameaçavam os interesses das oligarquias políticas.", "O isolamento do governo de Getúlio Vargas, que governava sem apoio político consistente.", "A descentralização do poder que resultou na estabilidade política, marca do governo de Getúlio Vargas.", "A incapacidade de Getúlio Vargas em exercer liderança sobre seus próprios aliados políticos."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'História','Leia o trecho a seguir. Soldados, marinheiros e aviadores da Força Expedicionária Aliada, estais prestes a embarcar na Grande Cruzada, pela qual temos lutado durante todos estes meses. Os olhos do mundo estão voltados para vós. As esperanças e orações de todos os que amam a liberdade vos acompanham. [...] Tenho total confiança na sua coragem, dedicação ao dever e habilidade em combate. Não aceitaremos nada menos do que a vitória total. Boa sorte! E que todos supliquemos a bênção de Deus Todo-Poderoso sobre essa grande e nobre missão. Adaptado de: Ordem do Dia do Dia D, declaração emitida aos soldados, marinheiros e aviadores da Força Expedicionária Aliada, em 6 de junho de 1944. O trecho se refere à ordem dada aos soldados, marinheiros e aviadores da Força Expedicionária dos Aliados no Dia D, conhecido como Operação Overlord, na Normandia, um momento decisivo da Segunda Guerra Mundial. O resultado do Dia D representou',null,null,'["a consolidação do domínio da Alemanha nazista em território francês.", "a entrada dos Estados Unidos na guerra após perceberem que os Aliados estavam prestes a sofrerem uma derrota.", "uma fase não bélica da Segunda Guerra Mundial, marcada por acordos diplomáticos entre França e Alemanha.", "uma ofensiva dos Aliados contra o exército alemão, que marcou o início da libertação da França do domínio nazista.", "a decadência das forças alemãs, que não ofereceram resistência à invasão dos Aliados."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'História','Nas primeiras décadas do século XX, o Brasil passou por mudanças importantes no campo da cultura e da ciência, marcadas pela criação de instituições voltadas para o desenvolvimento do conhecimento. Uma das instituições criadas no Brasil durante o começo do século XX com esse objetivo foi',null,null,'["o Instituto Histórico e Geográfico Brasileiro (IHGB), criado para coletar e divulgar documentos importantes para a história do Brasil, além de incentivar o estudo e a valorização da história no país.", "a Escola de Cirurgia da Bahia, criada como o primeiro curso universitário do Brasil e ajudou a organizar o ensino de medicina em um país que ainda estava atrasado nessa área por causa do período colonial.", "o Jardim Botânico do Rio de Janeiro, criado para reunir diversas espécies de plantas do mundo todo, com o objetivo de aclimatá-las e utilizá-las para fortalecer o desenvolvimento da agricultura no país.", "o Instituto Soroterápico Federal, que mais tarde passou a se chamar Fundação Oswaldo Cruz (Fiocruz), criado para produzir vacinas e soros no combate à peste bubônica.", "o Museu Nacional, criado para ajudar a formar a identidade do país exibindo artefatos de diferentes regiões do Brasil e do mundo."]'::jsonb,'A/B/C/D/E','Questão anulada no gabarito definitivo.' from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Filosofia','O homem selvagem [sic] e o homem policiado diferem de tal modo, tanto no fundo do coração quanto nas suas inclinações, que aquilo que determinaria a felicidade de um reduziria o outro ao desespero. O primeiro só almeja o repouso e a liberdade, só quer viver e permanecer na ociosidade. O cidadão, ao contrário, sempre ativo, cansa-se, agita-se, atormenta-se sem cessar para encontrar ocupações ainda mais trabalhosas. ROUSSEAU, Jean-Jacques. Discurso sobre a origem e os fundamentos da desigualdade entre os homens. São Paulo: Abril, 1973. (Adaptado.) O trecho acima diz respeito à tese do filósofo a respeito da origem das desigualdades entre os seres humanos. Segundo Rousseau, a desigualdade social e política é fruto de',null,null,'["diferenças naturais entre os indivíduos.", "convenções humanas na sociedade civil.", "disposição desigual para o trabalho.", "traços primitivos persistindo na sociedade.", "inclinações sensíveis prejudiciais à razão."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Filosofia','O termo “bioética” surgiu no início da década de 1970 como parte de uma tentativa de integrar a perspectiva humanista à atividade científica. Parte dessa preocupação era a de superar a dicotomia entre aquilo que é e aquilo que deve ser. Essa dicotomia tende a manter separados',null,null,'["a neutralidade intrínseca à ciência e os preconceitos culturais impostos pela sociedade.", "o que já foi alcançado pela atividade científica e o que ainda permanece no horizonte das pesquisas.", "os fatos investigados pela ciência e os valores éticos de interesse para a vida humana.", "o desenvolvimento tecnológico e as limitações impostas pelo desconhecimento científico.", "a busca pela verdade e a aceitação das incertezas próprias das ciências humanas."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Filosofia','Com o Iluminismo surge a tentativa de refundar as bases da sociedade a partir da razão, e não mais a partir do puro exercício da força ou dos valores tradicionais. Uma ideia política fundamental, tributária do Iluminismo, é a de que',null,null,'["o progresso das sociedades depende da harmonia entre a ordem natural e as determinações da vontade divina.", "todo indivíduo é sujeito de direitos inalienáveis que preservam sua dignidade enquanto humano.", "o Estado tem o pleno poder para decidir o que é melhor para a manutenção da harmonia social.", "os comportamentos individuais e a natureza humana são determinados por condições culturais.", "o uso da razão deve evitar mudanças radicais, pois as sociedades evoluem de forma orgânica e lenta."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Filosofia','O filósofo Karl Popper propôs a falseabilidade como critério capaz de distinguir as atividades científicas daquelas que não o são. Segundo o critério da falseabilidade, a atividade científica é aquela que',null,null,'["encontra base sólida na observação empírica e nos raciocínios indutivos.", "tem suas hipóteses confirmadas por meio da repetição de experimentos.", "constrói verdades definitivas por meio da postulação de leis universais.", "formula teorias que são suscetíveis à refutação por meio da experiência.", "é considerada enquanto tal pelo consenso da comunidade científica."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Sociologia','Acreditando que o homem é um animal amarrado a teias de significados que ele mesmo teceu, assumo a cultura como sendo essas teias e a sua análise; portanto, não como uma ciência experimental em busca de leis, mas como uma ciência interpretativa, à procura do significado. GEERTZ, Clifford. A interpretação das culturas. Rio de Janeiro: LTC, 2015. (Adaptado.) A partir de sua visão de “cultura”, o autor sugere que a antropologia necessita de um método de investigação distinto de outros tipos de ciências. Assinale a opção que expressa corretamente este método.',null,null,'["Acompanhar os comportamentos de um grupo ao longo do tempo para identificar regularidades.", "Construir modelos de análise baseados em variáveis objetivas e que permitam prever tendências culturais.", "Mapear estruturas materiais da organização social, priorizando a análise das relações de poder.", "Compreender como as ações, gestos e rituais expressam sentidos partilhados para aqueles que os realizam.", "Levantar dados empíricos que permitam classificações e categorização das culturas segundo critérios neutros."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Sociologia','O sociólogo Max Weber faz uma análise das diferentes formas de autoridade e dos modos pelas quais elas alcançam legitimidade social. Uma dessas formas se baseia na devoção de uma coletividade a uma figura de liderança considerada como indivíduo excepcional. Trata-se do poder',null,null,'["costumeiro.", "tradicional.", "hierárquico.", "aristocrático.", "carismático."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Sociologia','Segundo György Lukács, é o trabalho que cria a diferenciação entre o humano, como ser social, e os seres unicamente naturais. É por meio dele que nos tornamos capazes de transformar o meio, enquanto ao mesmo tempo nos transformamos. Isso se deve ao fato de o trabalho ser',null,null,'["um mecanismo de interação que é condicionado por respostas adaptativas às circunstâncias externas.", "uma forma de ação ativa e consciente pela qual o sujeito insere no mundo as suas próprias finalidades.", "um processo baseado na construção de padrões comportamentais estáveis para preservar o ambiente.", "uma atividade espontânea que decorre da imposição das necessidades mínimas de sobrevivência material.", "um processo físico por meio do qual o ser humano passa a obedecer às regularidades da natureza."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Sociologia','É característico da cultura brasileira o processo por meio do qual os conteúdos simbólicos de tradições distintas se articulam e sobrepõem, por meio tanto do contato afetivo quanto conflitivo, gerando novas formas híbridas. A esse processo se dá o nome de',null,null,'["miscigenação.", "sincretismo.", "relativização.", "multiculturalismo.", "segregação."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Geografia','Brasil sobe cinco posições no ranking do IDH e está na 84ª colocação O Programa de Desenvolvimento das Nações Unidas (Pnud ou UNDP, na sigla em inglês) divulgou a edição deste ano do relatório de Desenvolvimento Humano. O documento atualiza o Índice de Desenvolvimento Humano (IDH) de 193 países. Disponível em: https://agenciabrasil.ebc.com.br/economia/noticia/2025-05/brasilsobe-cinco-posicoes-no-ranking-do-idh-e-esta-na-84a-colocacao. Acesso: 12 Maio. 2025 Em relação ao IDH, avalie as afirmativas a seguir: I. Avalia aspectos relacionados aos indicadores econômicos, como Produto Interno Bruto (PIB) per capita, desconsiderando parâmetros sociais. II. Orienta políticas públicas que visam o desenvolvimento econômico, a alocação de recursos em infraestrutura, saúde e educação. III. Apresenta uma variação de 0 a 1, em que os países com valores mais próximos de 1 são considerados de alto desenvolvimento humano. Está correto o que se afirma em',null,null,'["I, apenas.", "III, apenas.", "I e II, apenas.", "II e III, apenas.", "I, II e III."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Geografia','Globalmente, a soja destaca-se como um dos grãos mais produzidos e consumidos (...). Nesse contexto, no Brasil apresenta crescimento das áreas cultivadas pela sojicultura nos biomas nacionais, com destaque para o bioma Cerrado e recentemente avançando para as terras da região do bioma Amazônia. Disponível em: https://www.editorarealize.com.br/editora/anais/sbgfa/2024/ Acesso: 13 mai. 2025. Sobre o processo descrito acima, avalie as seguintes afirmativas: I. Propicia o aumento da taxa de desmatamento, configurando uma perda para a conservação da biodiversidade. II. Caracteriza-se pelo uso intensivo de agrotóxicos, causando a contaminação dos recursos hídricos. III. Apresenta utilização intensiva de tecnologia buscando aumento de produtividade, como uso de sementes transgênicas. Está correto o que se afirma em',null,null,'["I, apenas.", "III, apenas.", "I e II, apenas.", "II e III, apenas.", "I, II e III."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Geografia','A qualidade ambiental deve ser encarada não só como o somatório das qualidades de cada um dos componentes do meio, mas como condição essencialmente ligada à qualidade de vida das populações. BOTELHO, Rosangela G. M.; SILVA, Antonio S. Bacia hidrográfica e qualidade ambiental. VITTE, A. C.; GUERRA, A. J. T. (orgs.). Reflexões sobre a Geografia Física no Brasil. Rio de Janeiro: Bertrand Brasil, 2024. p.154. Acerca do conceito de qualidade ambiental, avalie as seguintes afirmativas: I. Está relacionado à condição geral do ambiente, no que diz respeito à saúde e ao bem-estar dos seres vivos que o habitam. II. Engloba uma série de fatores, como pureza do ar e da água, riqueza biológica e a utilização dos recursos naturais. III. Compromete a capacidade das gerações futuras de suprir suas próprias necessidades de extração de recursos naturais. Está correto o que se afirma em',null,null,'["I, apenas.", "III, apenas.", "I e II, apenas.", "II e III, apenas.", "I, II e III."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Geografia','A lotação de um policial militar em batalhão localizado perto de sua residência foi garantida na Justiça (...) Questionando a falta de justificativa da corporação para transferir um soldado para um batalhão localizado em outra cidade, distante 114 km de sua residência, a instituição obteve a condenação do Estado e com isso garantiu o retorno do agente ao seu batalhão de origem. Disponível em: https://defensoria/noticia/detalhes/Defensoria-garante-lotacao-de- PM-em-batalhao-perto-de-casa (Adaptado) Acesso: 07 mai. 2024 Caso essa situação não fosse alterada, o servidor público realizaria diariamente o movimento de deslocamento denominado',null,null,'["êxodo urbano.", "pendularidade.", "transumância.", "peregrinação.", "turismo."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Geografia','Segundo Oliva (1995) a principal expressão de estado regulador será o Estado de Bem-Estar Social. Essa forma combina, nem sempre na mesma dose, elementos de controle e planejamento do processo econômico com investimentos da área social. (...) OLIVA, Jaime. Espaço e modernidade: temas da geografia mundial. (Adaptado) Avalie se a importância desse tipo de regulação do Estado para o trabalhador consiste em: I. Garantir o clientelismo político para manutenção de grupos de oportunistas no poder. II. Desenvolver sistemas de previdência que protejam trabalhadores acidentados em serviço e desempregados sem justa causa. III. Permitir que trabalhadores aposentados possam continuar consumindo, mesmo após idade avançada e saúde precária. Está correto o que se afirma em',null,null,'["I, apenas.", "III, apenas.", "I e II, apenas.", "II e III, apenas.", "I, II e III."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Geografia','Distritos da cidade de São Paulo onde moram mais pessoas negras tiveram mais alagamentos, inundações e deslizamentos nos últimos dez anos. A conclusão é de um levantamento exclusivo da Agência Pública a partir dos dados da Defesa Civil do município. No período, os dez distritos com mais ocorrências do tipo possuem população negra acima da média da cidade. Disponível em: https://apublica.org/2024/02/bairros-perifericos-e-de-maioria-negrasao-os-mais-afetados-por-desastres-em-sao-paulo/ Acesso: 08 Mai 2025. Avalie se o estudo apresentado no texto evidencia que: I. Os locais pesquisados apresentam maior violência policial, presença de grupos armados e atuação de facções criminosas. II. Os bairros com maior população negra apresentam uma qualidade de vida inferior e concentram um número maior de desastres. III. A situação de racismo ambiental dessas áreas se manifesta por meio da desproporcionalidade na exposição a impactos ambientais negativos. Está correto o que se afirma em',null,null,'["I e III, apenas.", "III, apenas.", "II e III, apenas.", "I e II, apenas.", "I, II e III."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Língua Portuguesa','Observe a seguinte frase: Por melhor que se fale, quando se fala muito, finaliza-se sempre por dizer tolices. O conselho implícito que está nessa frase, é:',null,null,'["Deve-se procurar falar melhor.", "Não se deve dizer tolices.", "Não se deve falar muito.", "Deve-se usar a razão ao falar.", "Não se deve terminar a fala com tolices."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Língua Portuguesa','As frases a seguir mostram comparações. Assinale a opção em que a comparação utiliza linguagem lógica (não figurada).',null,null,'["Devemos falar como nos testamentos: quanto menos palavras, menos questões.", "Ideias são como pulgas: saltam de uns para outros, mas não mordem a todos.", "Criatividade é como barba. Você só a terá se deixá-la crescer.", "Palavras cruzadas são como a linguagem em férias.", "As palavras são como camaleões: trocam de cor de acordo com sua posição."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Língua Portuguesa','As frases a seguir mostram comparações. Assinale a opção em que a comparação realizada não é explicada.',null,null,'["O público é como o leão; se a gente tem medo, ele engole.", "As palavras são como pinos em que se penduram as ideias.", "Ideias são como crianças. As nossas são sempre maravilhosas.", "Uma citação na hora certa é como comida altamente saborosa.", "As bibliotecas são como as farmácias: muitos venenos e poucos remédios."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Língua Portuguesa','Assinale a frase em que houve troca indevida entre onde/aonde.',null,null,'["Não há lugar para a força onde é necessária a astúcia.", "Onde a pele do leão não cobre é preciso costurar a da raposa.", "Apenas a violência pode servir onde reina a violência.", "Na escuridão não sabemos aonde dirigir-nos.", "Eis aí aonde mora a solidão e o abandono."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Língua Portuguesa','Um código indiano de leis registra o seguinte: Toda vez que o homem reconhece e confessa ter pecado, libera-se do próprio pecado como uma serpente, da pele velha. Sobre o significado e a estruturação desse segmento textual, é correto afirmar que',null,null,'["a introdução da imagem da serpente no texto se prende à ideia má, contida nos pecados.", "a comparação da liberação dos pecados com a liberação da pele por parte da serpente é exemplo de linguagem lógica.", "o reconhecimento do pecado e a sua confissão levam à liberação de culpas no pecador.", "o texto condena implicitamente a confissão dos pecados presente no catolicismo.", "a última vírgula empregada no texto é necessária em função da inversão sintática de termos na frase."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Língua Portuguesa','Assinale a frase que se estrutura por meio de antônimos.',null,null,'["A grande tragédia da ciência – o assassinato de uma linda hipótese por um fato horroroso.", "A ciência fez de nós deuses antes mesmo de merecermos ser homens.", "Antigamente a cidade era o mundo, hoje o mundo é uma cidade.", "Há mais coisas entre o céu e a terra do que imagina a filosofia.", "Os que se apegam demasiado às coisas pequenas geralmente chegam a ser incapazes das demais."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Língua Portuguesa','Assinale a opção em que a palavra “mais” mostra uma classe gramatical diferente das demais.',null,null,'["Morrer me incomoda por não poder ouvir mais Cole Porter.", "Quando penso que Mozart na minha idade já estava morto, fico mais sério e pensativo.", "Quanto mais bela é a música, menos a sabem apreciar os ignorantes.", "O poeta é o mais fiel historiador.", "Escrever humor é a maneira mais engraçada de ganhar a vida."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Língua Portuguesa','Assinale a opção em que a palavra “só” é classificada como na frase “Para assistirem a este filme, só entram os maiores de dezoito anos”.',null,null,'["Nos asilos, algumas vezes, bem sós se sentem os idosos.", "Ninguém consegue viver completamente só.", "Ela preferiu viajar só a estar mal acompanhada.", "Não compre um carro só pelo preço.", "Veja só a coragem daquele alpinista!"]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Língua Portuguesa','Assinale a frase em que o termo, de valor adverbial, foi corretamente substituído por um advérbio de sentido equivalente.',null,null,'["O pesquisador mostrou o resultado da pesquisa sobre preços, sem preocupação. / exatamente.", "O professor agiu com toda a energia diante da ofensa do aluno. / timidamente.", "O futebol brasileiro está, de fato, atravessando uma grave crise de qualidade. / realmente.", "O varandão do apartamento estava banhado de sol em toda a sua extensão. / intensamente.", "O historiador leu o livro da primeira à última página, com muita atenção. / ordenadamente."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Língua Portuguesa','Assinale a frase em que houve troca indevida entre “senão” e “se não”.',null,null,'["Para a música e para a mulher, não posso senão abrir caminho, esteja ocupado com o que for.", "Certamente, se não chover, o Rio de Janeiro terá o melhor carnaval dos últimos anos.", "Infeliz de quem não lê senão um livro.", "O único senão da peça é que a atriz principal tinha uma voz demasiadamente fina.", "Nasce uma obra de arte se o autor chega a transformar a emoção em símbolo; senão, ele só consegue uma alegoria."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Língua Portuguesa','Assinale a frase em que a forma sublinhada está grafada corretamente.',null,'["/pmsp/oficial-2025/q31-15-figura-1.png"]','["Aquele que sabe muito bem o por que das coisas tem com que se preocupar.", "Quando se apela ao talento é por que falta imaginação.", "Se eu chamei o número errado, você atendeu o telefone porquê?", "Mudou o tempero porquê mudou o chefe de cozinha.", "Por que você insiste em tocar enquanto eu estou regendo?"]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Língua Portuguesa','Assinale a afirmativa correta sobre os elementos de uma das frases a seguir.',null,'["/pmsp/oficial-2025/q32-15-figura-1.png"]','["Os publicitários não se suicidam porque Deus os condenou a assistir até o fim à consequência de seus atos. / Nesse caso, o emprego do acento grave da crase está errado.", "As perguntas é que fazem o filósofo. / Nessa frase, a expressão “é que” mostra valor enfático.", "“Hoje não existem mais malandros, só bandidos” e “A Literatura é a mais sedutora das profissões”. / a palavra “mais” mostra a mesma classe gramatical.", "Ser ator no Brasil é viver uma aventura que nunca termina / Nessa frase, a oração adjetiva sublinhada poderia ser adequadamente pelo adjetivo “finita”.", "Prefiro escritores mortos porque a gente não corre o risco de dar de cara com eles numa festa. / Nessa frase a forma da palavra sublinhada está incorreta."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Língua Portuguesa','Assinale a frase em que a expressão “graças a” está empregada de forma adequada.',null,null,'["Graças aos muitos abraços, minha roupa ficou amarrotada.", "Comprai a instrução a preço de muito dinheiro, graças a ela ganhareis muito ouro.", "O acidente ocorreu graças à falta de sinalização.", "Graças aos altos impostos, as coisas estão ficando caras.", "Fiquei preocupado graças às notícias que li no jornal."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Língua Portuguesa','Assinale a frase a seguir em que a troca de posição entre substantivo e adjetivo provoca modificação de sentido.',null,null,'["Um dia a massa irá comer do biscoito fino que fabrico.", "Minha própria eloquência embriagou-me.", "As melhores coisas são ditas em particular.", "As palavras antigas são as melhores.", "O menino fez um trocadilho horrível."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Língua Portuguesa','Assinale a frase em que “um/uma” é classificado como numeral e não como artigo.',null,null,'["A ABL (Academia Brasileira de Letras) se compõe de trinta e nove membros e um morto rotativo.", "O silêncio é de ouro, mas uma boa canção pode chegar à platina.", "Uma música que se preze nunca é objetiva.", "A expressão mais genuína de um povo reside na dança e na música.", "Conheci um autor francês que falava dezoito idiomas."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Língua Portuguesa','Assinale a frase em que há erro no emprego do acento grave indicativo da crase.',null,null,'["De dia, buscamos a festa, à noite somos forçados ao sono.", "Aquele que se mostra engenhoso à custa do livro alheio não pratica o bem.", "O prêmio foi entregue àquele candidato que menos erros cometeu na prova.", "Um homem competente é um homem que se equivoca segundo às regras.", "O pouco que sei devo-o à minha ignorância."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Língua Portuguesa','As frases a seguir trazem nomes de especialidades médicas. Assinale a frase cuja especialidade tem seu objeto corretamente definido.',null,null,'["O ginecologista dedica sua vida às mulheres. / cuida de doenças da pele.", "Quando seu obstetra fala em contração, na verdade quer dizer dor. / trabalha com partos.", "Nunca deixe de consultar um urologista. / especialista em exames laboratoriais.", "Ninguém como o psicanalista para enfeitar nossos mais belos sonhos. / trata do aparelho respiratório.", "Tenha a coragem de consultar um neurologista. / trata de problemas do fígado."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Língua Portuguesa','Os vocábulos abaixo aparecem acentuados, mas um deles está acentuado de forma incorreta. Assinale a opção em que esse vocábulo aparece.',null,null,'["balaústre / cafeína.", "egoísta / gratuíto.", "faísca / heroína.", "juízo / país.", "saúde / viúvo."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Língua Estrangeira','A continuación, leerá algunas informaciones respecto a los analfabetos funcionales. I. El porcentaje de analfabetos sigue siendo el mismo. II. El índice de analfabetismo entre los jóvenes ha aumentado. III. La pandemia puede haber afectado el índice de analfabetos de más edad. Señale','Tres de cada diez brasileños con edades entre 15 y 64 años no saben leer ni escribir o saben tan poco que no logran comprender frases simples ni identificar números telefónicos o precios. Son los llamados analfabetos funcionales. Este grupo representa el 29% de la población, el mismo porcentaje que en 2018. Los datos provienen del Indicador de Alfabetismo Funcional (INAF), divulgado el lunes (5), y encienden una alerta sobre la necesidad e importancia de políticas públicas orientadas a reducir esta desigualdad entre la población. El INAF también presenta otro dato preocupante. Entre los jóvenes, el analfabetismo funcional ha aumentado. Mientras que, en 2018, el 14% de los jóvenes de entre 15 y 29 años se encontraban en condición de analfabetismo funcional, en 2024 ese índice subió al 16%. Según los investigadores responsables del estudio, este aumento puede haber ocurrido debido a la pandemia, período durante el cual las escuelas estuvieron cerradas y muchos jóvenes quedaron sin clases. (Mariana Tokarnia – Reportera de Agência Brasil (https://agenciabrasil.ebc.com.br/es) Publicado en 10/05/2025 - 09:00)',null,'["si todas las afirmaciones son correctas.", "si sólo las afirmaciones I y II son correctas.", "si sólo la afirmación I es correcta.", "si sólo las afirmaciones II y III son correctas.", "si sólo la afirmación III es correcta."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Língua Estrangeira','En el fragmento “que no logran comprender…” (primer párrafo), el vocablo destacado puede sustituirse, en español, sin alterarle el significado por','Tres de cada diez brasileños con edades entre 15 y 64 años no saben leer ni escribir o saben tan poco que no logran comprender frases simples ni identificar números telefónicos o precios. Son los llamados analfabetos funcionales. Este grupo representa el 29% de la población, el mismo porcentaje que en 2018. Los datos provienen del Indicador de Alfabetismo Funcional (INAF), divulgado el lunes (5), y encienden una alerta sobre la necesidad e importancia de políticas públicas orientadas a reducir esta desigualdad entre la población. El INAF también presenta otro dato preocupante. Entre los jóvenes, el analfabetismo funcional ha aumentado. Mientras que, en 2018, el 14% de los jóvenes de entre 15 y 29 años se encontraban en condición de analfabetismo funcional, en 2024 ese índice subió al 16%. Según los investigadores responsables del estudio, este aumento puede haber ocurrido debido a la pandemia, período durante el cual las escuelas estuvieron cerradas y muchos jóvenes quedaron sin clases. (Mariana Tokarnia – Reportera de Agência Brasil (https://agenciabrasil.ebc.com.br/es) Publicado en 10/05/2025 - 09:00)',null,'["alcanzan.", "fracasan.", "esperan.", "aclaran.", "comprueban."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Língua Estrangeira','A continuación, leerá algunas informaciones respecto al consumo de alcohol. I. La mayoría de la población no asume que consume alcohol. II. La investigación reveló que el consumo ha aumentado. III. Predominan respuestas en las que se asume que el consumo es moderado. Señale','La mitad de los brasileños dice haber reducido el consumo de alcohol en el último año Cuando se trata del consumo de alcohol, la población brasileña está dividida a partes iguales entre quienes dicen consumir la sustancia (51%) y quienes no lo hacen (49%). Los datos provienen de una encuesta de Datafolha. Las respuestas corresponden a personas mayores de 18 años, edad de la mayoría legal en el país y a partir de la cual se permite la venta de alcohol. En un balance del consumo del último año, más de la mitad (53%) de quienes bebieron alcohol afirman haber reducido su consumo, mientras que un 12% notó un aumento y un 35% considera que no hubo cambios. Los brasileños bebieron un promedio de 4,5 dosis en la semana anterior a la encuesta. Para el estudio, una dosis se entiende como un vaso, una lata, una copa o un trago. La gran mayoría (81%) considera que consume bebidas alcohólicas en una medida adecuada y un 18% dice que bebe en exceso. Dentro de ese porcentaje, un 11% dice beber más de lo que debería y un 7% cree que bebe mucho más de lo que debería. (https://www1.folha.uol.com.br/internacional/es. 5.may.2025 13h31. Bárbara Blum)',null,'["Si todas las afirmaciones son correctas.", "Si sólo las afirmaciones I y II son correctas.", "Si sólo la afirmación I es correcta.", "Si sólo las afirmaciones II y III son correctas.", "Si sólo la afirmación III es correcta."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Língua Estrangeira','En el fragmento: Los datos provienen de una encuesta” (Primer Párrafo), el vocablo destacado puede sustituirse, en español, sin alterarle el significado por:','La mitad de los brasileños dice haber reducido el consumo de alcohol en el último año Cuando se trata del consumo de alcohol, la población brasileña está dividida a partes iguales entre quienes dicen consumir la sustancia (51%) y quienes no lo hacen (49%). Los datos provienen de una encuesta de Datafolha. Las respuestas corresponden a personas mayores de 18 años, edad de la mayoría legal en el país y a partir de la cual se permite la venta de alcohol. En un balance del consumo del último año, más de la mitad (53%) de quienes bebieron alcohol afirman haber reducido su consumo, mientras que un 12% notó un aumento y un 35% considera que no hubo cambios. Los brasileños bebieron un promedio de 4,5 dosis en la semana anterior a la encuesta. Para el estudio, una dosis se entiende como un vaso, una lata, una copa o un trago. La gran mayoría (81%) considera que consume bebidas alcohólicas en una medida adecuada y un 18% dice que bebe en exceso. Dentro de ese porcentaje, un 11% dice beber más de lo que debería y un 7% cree que bebe mucho más de lo que debería. (https://www1.folha.uol.com.br/internacional/es. 5.may.2025 13h31. Bárbara Blum)',null,'["balance.", "examen.", "estadística.", "sondeo.", "reportaje."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Língua Estrangeira','En el texto, se hace una denuncia respecto a/ a la/ al:','En lo profundo del esfuerzo de Brasil por erradicar el desperdicio de alimentos A los 19 años, Regina Tchelly dejó su pequeña ciudad natal en el noreste de Brasil y llegó a Río de Janeiro con un sueño: convertirse en una chef famosa. Cuando llegó allí, Regina Tchelly, acostumbrada desde su infancia a no desperdiciar comida, se entristeció al ver con qué frecuencia los vendedores ambulantes tiraban comida en buen estado. Esta situación la llevó a emprender un nuevo camino culinario. Empezó a llevarse a casa comida desechada de su trabajo como camarera y creó recetas innovadoras, como pan de especias con cáscara de plátano y quiche de tallos de brócoli. Esa experiencia acabaría llevándola a fundar Favela Orgânica. La organización ha enseñado a miles de personas con bajos ingresos, así como a quienes venden en la calle y a quienes trabajan en restaurantes, a desperdiciar menos alimentos, combatir el hambre y hacer frente a las consecuencias ambientales, a menudo devastadoras, del desperdicio de alimentos. “No debería existir el concepto de desechar. Con ello desperdiciamos nuestro planeta”, afirmó Regina Tchelly, quien ahora tiene 42 años. “Tenemos que cambiar nuestros hábitos. Estamos inmersos en una enorme crisis climática. Aquí, la gente aprende cómo la comida sana y los hábitos sostenibles pueden beneficiar tanto a nuestra salud como al planeta”. (27 Mar 2024 - https://www.unep.org/es)',null,'["crisis climática.", "personas con bajos ingresos.", "derroche de alimentos.", "consecuencias ambientales.", "infancias difíciles en comunidades."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Língua Estrangeira','En el fragmento: “los vendedores tiraban comida en buen estado” (Segundo párrafo), el vocablo destacado puede sustituirse, en español, sin alterarle el significado por','En lo profundo del esfuerzo de Brasil por erradicar el desperdicio de alimentos A los 19 años, Regina Tchelly dejó su pequeña ciudad natal en el noreste de Brasil y llegó a Río de Janeiro con un sueño: convertirse en una chef famosa. Cuando llegó allí, Regina Tchelly, acostumbrada desde su infancia a no desperdiciar comida, se entristeció al ver con qué frecuencia los vendedores ambulantes tiraban comida en buen estado. Esta situación la llevó a emprender un nuevo camino culinario. Empezó a llevarse a casa comida desechada de su trabajo como camarera y creó recetas innovadoras, como pan de especias con cáscara de plátano y quiche de tallos de brócoli. Esa experiencia acabaría llevándola a fundar Favela Orgânica. La organización ha enseñado a miles de personas con bajos ingresos, así como a quienes venden en la calle y a quienes trabajan en restaurantes, a desperdiciar menos alimentos, combatir el hambre y hacer frente a las consecuencias ambientales, a menudo devastadoras, del desperdicio de alimentos. “No debería existir el concepto de desechar. Con ello desperdiciamos nuestro planeta”, afirmó Regina Tchelly, quien ahora tiene 42 años. “Tenemos que cambiar nuestros hábitos. Estamos inmersos en una enorme crisis climática. Aquí, la gente aprende cómo la comida sana y los hábitos sostenibles pueden beneficiar tanto a nuestra salud como al planeta”. (27 Mar 2024 - https://www.unep.org/es)',null,'["arrojaban.", "apartaban.", "ahorraban.", "segregaban.", "retenían."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=