insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Matemática','Uma dada função 𝑓, ao receber qualquer valor real, subtrai desse valor três unidades, eleva essa diferença ao quadrado e, por fim, multiplica o resultado da potência por quatro. Sejam 𝑥₁ e 𝑥₂ valores reais tais que 𝑓(𝑥₁) = 𝑓(𝑥₂) = 25, com 𝑥₁ > 𝑥₂. O valor de 𝑥₁ −𝑥₂ é',null,null,'["6,0.", "5,5.", "5,0.", "4,5.", "4,0."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Matemática','Em uma caixa, há exatamente 10 balas, sendo 6 delas de leite e as demais, de coco. Exatamente duas balas serão retiradas aleatoriamente da caixa, uma de cada vez, sem reposição. A probabilidade de que se obtenha pelo menos uma bala de coco é',null,'["/pmsp/oficial-2025/q48-22-figura-1.png"]','["4/9.", "1/3.", "2/5.", "1/2.", "2/3."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Matemática','A figura ilustra duas circunferências concêntricas, de centro em 𝑂, sobre as quais se constrói um circuito fechado 𝐴𝐵𝐶𝐷𝐴, formado pelos segmentos de reta 𝐴𝐵 e 𝐶𝐷, intercalados por dois arcos de circunferência 𝐴𝐷 e 𝐵𝐶. Os pontos 𝐴 e 𝐷 pertencem à circunferência de raio 5 cm e os pontos 𝐵 e 𝐶, à circunferência de raio 2 cm. O arco 𝐴𝐷 mede 240° e os prolongamentos de 𝐴𝐵 e 𝐶𝐷 contêm o ponto 𝑂. Considerando-se 𝜋 igual a 3, o comprimento do circuito completo é',null,'["/pmsp/oficial-2025/q49-23-figura-1.png"]','["20 cm.", "24 cm.", "27 cm.", "30 cm.", "36 cm."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Matemática','Representada sobre um plano cartesiano, uma reta 𝑟 contém os pontos (1, 4) e (3, 10). Nesse mesmo sistema de coordenadas, uma reta 𝑠 paralela à reta 𝑟 contém o ponto (1, 0). É correto concluir que 𝑠 intersecta o eixo das ordenadas no ponto',null,null,'["(0, –4).", "(0, –3).", "(0, –2).", "(0, –1).", "(0, 0)."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,51,'Matemática','A soma dos 7 termos de certa progressão aritmética é 77. É correto concluir que o 4º termo dessa progressão vale',null,null,'["7.", "11.", "14.", "18.", "22."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,52,'Matemática','A média aritmética de 4 números inteiros positivos é 9. A mediana da lista formada por eles vale 8. Se a diferença entre o maior e o menor desses números é igual a 10, então o maior deles é',null,null,'["15.", "14.", "12.", "11.", "10."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,53,'Matemática','Para definir uma senha de 5 dígitos para o seu cofre, Aluísio escolheu, inicialmente, os dois dígitos do dia e os dois dígitos do mês de seu aniversário. De posse desses 4 dígitos, ele os distribuiu nas quatro posições de uma matriz 2 x 2 de modo que o determinante dessa matriz fosse o maior possível. A senha foi então formada pela ordenação decrescente desses 5 dígitos: os 4 da data e o determinante máximo. Sabendo-se que Aluísio nasceu no penúltimo dia do ano, é correto afirmar que a senha do seu cofre é',null,null,'["32100.", "53210.", "63210.", "63211.", "73210."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,54,'Matemática','Diariamente, a altura H (em metros) da maré em certo cais pode ser modelada por H(t) = 1,4 + 0,5 × sen((π/6)t + π/10), com 0 ≤ t < 24, em que t é o tempo decorrido, em horas, desde a meia-noite. Nesse local, a altura máxima atingida pela maré, em metros, ao longo de um dia é',null,null,'["0,90.", "1,65.", "1,40.", "1,85.", "1,90."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,55,'Matemática','Uma cafeteria gourmet recebeu, de seus fornecedores, 8 tipos diferentes de cafés especiais numerados de 1 a 8. Para um evento exclusivo, o gerente deseja escolher 3 desses tipos de café para uma degustação. No entanto, ele sabe que os cafés nº 2 e nº 7 têm sabores muito parecidos. Por isso, ele decide que, se um desses for escolhido, o outro não poderá ser. Nessas condições, o número de opções distintas de que o gerente dispõe para oferecer nessa degustação é',null,null,'["30.", "35.", "36.", "50.", "56."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,56,'Matemática','Um indivíduo está de pé sobre uma rua horizontal olhando fixamente para o topo de um poste vertical de 6 metros de altura. Quando o indivíduo estava em uma posição em que o ângulo de elevação do seu olhar era 30°, ele caminhou 5 metros na direção do poste, se aproximando deste, até parar no ponto em que o ângulo de elevação do olhar passou a ser de 60°. Considerando-se 1,7 como aproximação para a √3, é correto afirmar que a altura dos olhos do indivíduo, em metros, é',null,null,'["1,65.", "1,75.", "1,80.", "1,85.", "1,90."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,57,'Física','Uma partícula parte do repouso e mantém aceleração constante durante um intervalo de tempo t. Continua em movimento progressivo, mantendo velocidade constante pelo mesmo intervalo de tempo t. Em seguida, desacelera com aceleração constante, levando um intervalo de tempo 2t para retornar ao repouso. O movimento é horizontal e retilíneo. O gráfico que melhor representa a variação da posição em função do tempo do movimento descrito é:','Figuras das alternativas A, B, C, D e E, nessa ordem.','["/pmsp/oficial-2025/q57-25-alternativa-1.png", "/pmsp/oficial-2025/q57-25-alternativa-2.png", "/pmsp/oficial-2025/q57-25-alternativa-3.png", "/pmsp/oficial-2025/q57-25-alternativa-4.png", "/pmsp/oficial-2025/q57-25-alternativa-5.png"]','["Figura da alternativa A (ver apoio).", "Figura da alternativa B (ver apoio).", "Figura da alternativa C (ver apoio).", "Figura da alternativa D (ver apoio).", "Figura da alternativa E (ver apoio)."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,58,'Física','Considere o vagão de um trem em movimento, conforme representado na figura a seguir. Um observador externo observa um pêndulo preso ao teto do vagão deslocado da direção vertical, indicada pela linha pontilhada. Sabendo que o vagão se desloca em trajetória horizontal e retilínea, ele pode estar se movimentando de',null,'["/pmsp/oficial-2025/q58-26-figura-1.png"]','["X para Y, com velocidade constante.", "Y para X, com sua velocidade diminuindo.", "X para Y, com sua velocidade aumentando.", "Y para X, com sua velocidade aumentando.", "Y para X, com velocidade constante."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,59,'Física','A figura representa quatro blocos de massas iguais a 10 kg apoiados em um plano horizontal perfeitamente liso. Aplica-se ao corpo A uma força horizontal F = 8 N. O módulo da força que o corpo C exerce sobre o corpo B tem módulo igual a',null,'["/pmsp/oficial-2025/q59-26-figura-1.png"]','["2 N.", "4 N.", "6 N.", "8 N.", "10 N."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,60,'Física','A figura representa um carrinho que parte do repouso no ponto X a uma altura de 28 m, e percorre um trecho de montanha russa até chegar ao ponto y, com altura igual a 8 m. Considere que não há forças dissipativas, e o valor da aceleração da gravidade é de 10 m/s². A velocidade com que o carrinho chega ao ponto y é',null,'["/pmsp/oficial-2025/q60-26-figura-1.png"]','["8 m/s.", "10 m/s.", "20 m/s.", "28 m/s.", "40 m/s."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,61,'Física','Um estudante no nível do mar recebe um termômetro com escala termométrica desconhecida. Para estudá-lo, seu professor propõe que o termômetro seja inserido em um recipiente contendo água com gelo. Nesse caso, o termômetro acusa um valor de −4. Em seguida, o professor pede que o termômetro seja inserido em um recipiente com água em ebulição. O estudante verifica que o termômetro passa a indicar +116. A única temperatura em que o termômetro estudado e um outro termômetro graduado na escala Celsius indicam a mesma temperatura é',null,null,'["10 oC.", "20 oC.", "30 oC.", "40 oC.", "60 oC."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,62,'Física','Duas esferas puntiformes e idênticas estão carregadas com cargas iguais e separadas no vácuo. Quando as esferas estão a 0,2 m de distanciamento, a força elétrica entre elas é de 4000 N. Para que a intensidade da força elétrica seja igual a 250 N, as esferas devem ficar separadas de',null,null,'["0,3 m.", "0,4 m.", "0,5 m.", "0,8 m.", "1,0 m."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,63,'Química','Recentemente o mundo acompanhou a escolha de um novo papa. Quando o conclave papal se reúne para a eleição, a fumaça da queima das cédulas dos cardeais indica o resultado. A fumaça branca é a sinalização que uma decisão foi tomada. Tal fumaça é produzida a partir da mistura de clorato de potássio, lactose e breu (resina de pinheiro). O sal inorgânico utilizado na produção da fumaça branca possui a seguinte fórmula química:',null,'["/pmsp/oficial-2025/tabela-periodica-1.png"]','["KCl.", "KClO.", "KClO₂.", "KClO₃.", "KClO₄."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,64,'Química','O gás cloro (Cl₂) é bastante utilizado em estações de tratamento de água e esgotos. Uma de suas aplicações está na remoção de sulfeto de hidrogênio (H₂S), resultante da decomposição da matéria orgânica, que confere um odor desagradável à água, similar a ovo podre. O gás cloro converte o H₂S em enxofre elementar (S₈) gerando, ainda, HCl como subproduto. A reação não balanceada que descreve o processo é dada a seguir: Cl2(g) + H₂S(aq) → S8(s) + HCl(aq) Após balanceamento da reação, é possível prever que a razão entre a quantidade de enxofre elementar formado e a de gás cloro empregado no tratamento deve ser de',null,'["/pmsp/oficial-2025/tabela-periodica-1.png"]','["1/8.", "1/4.", "1/2.", "4.", "8."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,65,'Química','A Química está intrinsecamente associada ao nosso cotidiano, desempenhando papel fundamental na produção de novos materiais, medicamentos e artefatos industriais. A partir do conhecimento das propriedades dos compostos químicos é possível fazer algumas previsões. Observe a tabela a seguir que contém os pontos de fusão e ebulição de três substâncias distintas. Fusão (°C) Ebulição (°C) Substância 1 –95 –30 2 –3 112 3 88 145 A partir das informações é possível prever que os estados físicos das substâncias 1, 2 e 3, à temperatura ambiente (25°C), devem ser, respectivamente,',null,'["/pmsp/oficial-2025/q65-28-figura-1.png", "/pmsp/oficial-2025/tabela-periodica-1.png"]','["sólido, líquido e gasoso.", "gasoso, líquido e sólido.", "sólido, gasoso e líquido.", "gasoso, gasoso e sólido.", "sólido, líquido e sólido."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,66,'Química','A partir da posição dos elementos na Classificação Periódica dos Elementos é possível relacionar suas informações e estabelecer de forma lógica suas propriedades e comportamentos em reações. Observe a tabela a seguir, que contém características de três elementos químicos. Elemento Características Elemento representativo com dois níveis de X energia e que possui quatro elétrons no seu último nível. Metal alcalino terroso de menor raio atômico do Y seu grupo. Elemento que forma com metais alcalinos Z composto iônico de fórmula A₂Z e possui o maior potencial de ionização do seu grupo. Os elementos X, Y e Z correspondem, respectivamente, a',null,'["/pmsp/oficial-2025/q66-29-figura-1.png", "/pmsp/oficial-2025/tabela-periodica-1.png"]','["C, Be e F.", "Al, Li e F.", "C, Li e F.", "Al, Be e O.", "C, Be e O."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,67,'Química','O descarte incorreto de lixo eletrônico, como aparelhos celulares e computadores usados, tem provocado preocupações tanto ambientais quanto econômicas, por conta da presença de vários metais nas placas e peças desses dispositivos. Para recuperar esses metais e reduzir os danos gerados, é preciso separá-los dos materiais plásticos e cerâmicos que também compõem as placas eletrônicas. Após moagem das placas eletrônicas, o processo mais adequado para separar metais sólidos das demais partes trituradas não metálicas é a',null,'["/pmsp/oficial-2025/tabela-periodica-1.png"]','["destilação.", "imantação.", "peneiração.", "decantação.", "cristalização."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,68,'Química','Em um recipiente fechado misturam-se, sob condições adequadas de temperatura e pressão, gás nitrogênio (N₂) e gás hidrogênio (H₂), que reagem entre si segundo equação química balanceada: N2(g) + 3H2(g) → 2NH3(g) A mistura inicial é representada na figura a seguir, na qual os círculos escuros representam os átomos de nitrogênio e os círculos claros os átomos de hidrogênio. De modo a obedecer a lei da conservação da massa, o diagrama que representa uma possível mistura final, após a reação gerar o produto NH₃, é','Figuras das alternativas A, B, C, D e E, nessa ordem.','["/pmsp/oficial-2025/q68-30-figura-1.png", "/pmsp/oficial-2025/q68-30-alternativa-1.png", "/pmsp/oficial-2025/q68-30-alternativa-2.png", "/pmsp/oficial-2025/q68-30-alternativa-3.png", "/pmsp/oficial-2025/q68-30-alternativa-4.png", "/pmsp/oficial-2025/q68-30-alternativa-5.png", "/pmsp/oficial-2025/tabela-periodica-1.png"]','["Figura da alternativa A (ver apoio).", "Figura da alternativa B (ver apoio).", "Figura da alternativa C (ver apoio).", "Figura da alternativa D (ver apoio).", "Figura da alternativa E (ver apoio)."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,69,'Biologia','Conhecer a composição química do material genético e compreender como ele funciona, é fundamental para a prevenção e solução de várias questões relacionadas à saúde, ao bem-estar e ao meio ambiente. Com relação a esse tema, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A molécula de DNA é composta por uma dupla cadeia de polinucleotídeos; cada nucleotídeo é formado por uma base nitrogenada, um açúcar e um fosfato. Em uma fita única de DNA, a ligação entre os nucleotídeos se faz entre o açúcar de um nucleotídeo e a base nitrogenada do seguinte. ( ) Um organismo multicelular complexo, como o humano, é formado por muitos tipos de células. Por exemplo, um neurônio e uma célula muscular de uma mesma pessoa, embora tenham igual número de cromossomos, são diferentes, pois seus genes não são os mesmos. ( ) Fatores do ambiente, como certos tipos de alimentos e poluentes, podem influenciar a expressão dos genes de um indivíduo, ativando-os ou inativando-os, sem alterar a sequência de bases do DNA. As afirmativas são, respectivamente,',null,null,'["F – V – F.", "F – F – V.", "V – F – F.", "V – V – F.", "F – V – V."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,70,'Biologia','Apesar da inestimável contribuição dos antibióticos no combate às doenças infecciosas, sua administração pode provocar efeitos adversos nos pacientes, como é o caso do cloranfenicol. Essa droga impede a multiplicação de bactérias, ligando-se à subunidade 50S dos ribossomos procarióticos. Em função desse modo de ação, o cloranfenicol pode causar, em humanos, efeitos colaterais devido à interrupção da(o)',null,null,'["tradução de proteínas da parede celular.", "processo de transcrição do DNA mitocondrial.", "produção de RNA ribossomal a partir de DNA nuclear.", "síntese de proteínas codificadas pelo DNA mitocondrial.", "tradução do DNA nuclear para formação de RNA mensageiro."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,71,'Biologia','A figura mostra um experimento para comparar as trocas gasosas realizadas por uma planta nos processos de fotossíntese e respiração celular, em presença e ausência de luz. O vermelho de cresol é um indicador de pH. Ele apresenta coloração púrpura, em meio com baixa concentração de CO₂ (meio alcalino) e amarela, em meio com alta concentração de CO₂ (meio ácido). No início do experimento, todos os tubos apresentavam coloração vermelha. Após algumas horas, espera-se que a coloração do indicador no(s)',null,'["/pmsp/oficial-2025/q71-32-figura-1.png"]','["tubo 1 mude para amarela; a planta produzirá CO₂ por intermédio da respiração celular.", "tubo 2 mude para amarela; a planta absorverá CO₂ durante a fotossíntese.", "tubo 2 mude para púrpura; a planta não realizará a respiração celular e usará todo o CO₂ na fotossíntese.", "tubo 2 permaneça vermelha; o CO₂ produzido na fotossíntese será absorvido durante a respiração celular.", "tubos 1 e 3 permaneça vermelha; sem a ocorrência de fotossíntese, a concentração de CO₂ não será alterada."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,72,'Biologia','O fotógrafo Sebastião Salgado morreu no dia 23 de maio de 2025, aos 81 anos. Ele lidava com um distúrbio sanguíneo decorrente da malária que contraiu em 2010. A malária é uma doença infecciosa causada por',null,null,'["vírus, cujo vetor são as fêmeas infectadas dos mosquitos gênero Lutzomya, conhecidos como mosquitos-palha.", "protozoários do gênero Neisseria, cujo vetor são as fêmeas infectadas dos mosquitos do gênero Aedes, que têm hábitos diurnos.", "vírus, cujo vetor são as fêmeas infectadas dos mosquitos gênero Anopheles, também chamado de mosquitos-prego.", "protozoários do gênero Plasmodium, cujo vetor são as fêmeas infectadas dos mosquitos gênero Anopheles, também chamados de mosquitos-prego.", "bactérias do gênero Plasmodium, cujo vetor são as fêmeas infectadas dos mosquitos do gênero Aedes, que têm hábitos diurnos."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,73,'Biologia','No início do século XX, pesquisadores trabalharam em uma teoria que sintetizava os conceitos do darwinismo, as leis de Mendel e o que havia sido descoberto na Biologia. Esse trabalho deu origem à teoria atual, conhecida como Teoria Sintética da Evolução ou Neodarwinismo. Com relação à Teoria Sintética da Evolução, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A recombinação gênica é um fator evolutivo. Nos eucariontes, ela ocorre devido a um processo mitótico: a permutação, também chamada de crossing-over. ( ) Do ponto de vista evolutivo, o antibiótico atua como um agente seletivo que mata as bactérias selvagens e deixa os recursos à disposição das bactérias que, estimuladas pelo medicamento, criaram resistência a ele. Estas se reproduzem e dão origem a populações inteiras de bactérias resistentes contra as quais aquele antibiótico exerce pouco efeito. ( ) A embriologia e a anatomia mostram que as asas dos insetos e as das aves têm origem embrionária e estrutura anatômica diferentes, embora tenham a mesma função. Essas são as chamadas estruturas análogas e decorrem de um processo de evolução divergente. As afirmativas são, respectivamente,',null,null,'["F – F – V.", "V – F – F.", "V – F – V.", "F – V – F.", "F – F – F."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,74,'Biologia','Para se fazer o teste de identificação dos grupos sanguíneos dos sistemas ABO e Rh de uma pessoa, são necessárias três gotas de sangue: a uma delas se adiciona uma gota de soro com aglutinina anti-A; à outra, soro anti-B; e, à terceira, soro anti-Rh. Em determinada situação, duas mulheres (M e N) disputam a maternidade de um bebê, cujo sangue foi testado com o uso dos soros anti-A, anti-B e anti-Rh (anti-D). Os resultados são apresentados a seguir. Sobre as supostas mães sabe-se que: a mulher M tem o genótipo iidd; já a mulher N, que pertence ao grupo A, apresentou eritroblastose ao nascer. A possível mãe do bebê é a mulher',null,'["/pmsp/oficial-2025/q74-33-figura-1.png"]','["M, sendo seu fenótipo O positivo e o da criança, A positivo.", "N, sendo que os fenótipos dela e do bebê são A positivo.", "M, sendo que os fenótipos dela e do bebê são A negativo.", "N, sendo que os fenótipos dela e do bebê são A negativo.", "M, sendo seu fenótipo O negativo e o da criança, B positivo."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,75,'Noções de Administração Pública','Ao passar por determinada localidade, João, policial militar, constatou que se encontrava no interior de uma residência, debruçado sobre o peitoril da janela frontal, a mesma pessoa do sexo masculino que ele tinha perseguido uma semana antes, em razão da prática de crime de furto contra pedestre. Na situação descrita, é correto afirmar que João',null,null,'["pode ingressar na residência, sem o consentimento do morador, para prender a referida pessoa.", "somente pode ingressar na residência, sem o consentimento do morador, durante o dia, por determinação judicial.", "pode ingressar na residência, se houver consentimento do morador ou determinação judicial, durante o dia ou à noite.", "pode ingressar na residência, a exemplo de qualquer pessoa do povo, com ou sem o consentimento do morador, pois a pessoa está em flagrante delito.", "deve comunicar o fato à autoridade que conduz a investigação do crime de furto, a qual pode ingressar na residência, sem o consentimento do morador, para prender a referida pessoa."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,76,'Noções de Administração Pública','O Governador do Estado Alfa pretende nomear uma pessoa com grande expertise na área de planejamento urbano, que até então atuava exclusivamente na iniciativa privada, para chefiar uma estrutura administrativa incumbida da realização da referida atividade de planejamento. Considerando que a referida pessoa não foi previamente aprovada em concurso público, é correto afirmar, à luz da Constituição do Estado de São Paulo, que',null,null,'["essa espécie de nomeação é vedada.", "é possível nomeá-la para ocupar cargo em comissão.", "é possível nomeá-la para o exercício de função de confiança.", "é possível nomeá-la para ocupar cargo de provimento efetivo.", "somente é possível celebrar contrato temporário com essa pessoa."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,77,'Noções de Informática','Um usuário do MS Windows 10 BR pressionou, no teclado, a tecla “Windows” e digitou o comando “cmd” para abrir o prompt de comando. No prompt de comando, para acessar a pasta “relatórios” que está na pasta “documentos”, o usuário deve digitar o seguinte comando:',null,null,'["dir documents\\relatorios", "md documents\\relatorios", "cd documents\\relatorios", "cls documents\\relatorio", "list documents\\relatorio"]'::jsonb,'A/B/C/D/E','Questão anulada no gabarito definitivo.' from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,78,'Noções de Informática','Um soldado, para realizar o levantamento da compra de alguns itens que fazem parte do uniforme de Cabo da Polícia Militar do Estado de São Paulo, criou a seguinte planilha no MS Excel 2016 BR: Na célula D2 inseriu a fórmula =C$2*$B2 e, com o mouse, clicou e arrastou a alça de preenchimento para baixo até a célula D6. Na célula D7, para determinar o valor total da compra dos itens, inseriu a fórmula =SOMA(D2:D6) e apresentou essa planilha a seu superior. Ao conferir a planilha, o superior verificou que alguns dos valores apresentados na coluna “Total” estavam corretos porque a fórmula usada para multiplicar os valores das colunas “Quant” e “Valor” estava incorreta. Dessa forma, para que os valores da coluna “Total” sejam corretamente ajustados, a fórmula correta que deverá ser inserida na célula D2 para depois ser arrastada pela alça de preenchimento até a célula D6 é',null,'["/pmsp/oficial-2025/q78-35-figura-1.png"]','["=C2*B2", "=C2+B2", "=C$2*$B2", "=$C$2*B2", "=C$2*$B$2"]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,79,'Noções de Informática','Um usuário do Google Chrome estava navegando na Internet por meio de inúmeras guias abertas no navegador, mas, sem querer, acabou fechando uma dessas guias. Nesse caso, para reabrir a última guia fechada, o usuário deverá acionar o seguinte atalho de teclado:',null,null,'["Ctrl + L", "Ctrl + J", "Ctrl + Shift + N", "Ctrl + Shift + R", "Ctrl + Shift + T"]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,80,'Noções de Informática','Acerca dos ambientes Google Workspace, associe as ferramentas listadas a seguir às respectivas funções. 1. Meet 2. Drive 3. Google Calendar ( ) Facilita o armazenamento e compartilhamento de arquivos, permitindo o acesso online e colaborativo. ( ) Permite videoconferências e chamadas de voz, facilitando a comunicação em tempo real e a realização de reuniões online. ( ) Ajuda a organizar e gerenciar eventos e reuniões, permitindo que as pessoas saibam quando e onde precisam estar. Assinale a opção que indica a associação correta, na ordem apresentada.',null,null,'["1 – 3 – 2.", "1 – 2 – 3.", "2 – 3 – 1.", "2 – 1 – 3.", "3 – 1 – 2."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2025-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exams(slug,title,source,year) values ('pmsp-oficial-2024-ingles','PM São Paulo · Oficial · 2024 · 18/08/2024 · Inglês','pmerj','2024') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'História','No contexto de formação do Império Romano, para construir o consenso político referido no excerto, o imperador Otávio Augusto','Um aspecto importante no que se refere à construção de uma unidade do Império está vinculado à posição do imperador. Nunca se tratou de um cargo legalmente regulado, mas que delimitava uma unidade político-institucional, para além do aspecto de unidade identitária. Essa posição se manteve pouco clara do ponto de vista institucional e dependia da construção de um consenso político em torno de um indivíduo que detinha a posição mais alta nas hierarquias compósitas do Império. (Norberto Luiz Guarinello. História Antiga, 2020.)',null,'["reforçou a política de distribuição de trigo e de promotoria de festividades.", "preservou a estrutura estatal e o poder do Senado do período republicano.", "conservou a organização do exército e suas estratégias de combate.", "implementou medidas para garantir a autonomia das províncias.", "suprimiu a aliança política entre as elites urbanas e o poder imperial."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'História','Os fatos históricos mencionados no excerto relacionam-se','O novo primeiro-ministro da Grã-Bretanha, George Grenville, estava determinado a arrecadar fundos. Durante décadas, uma lei exigira que os mercadores coloniais pagassem uma tarifa alfandegária sobre o melaço que importavam. As tarifas, no entanto, pouco ajudavam a Metrópole, porque a maioria dos mercadores contrabandeava seu melaço, subornando as autoridades alfandegárias para que fizessem vista grossa. Com a Lei do Açúcar, Grenville tornou o sistema mais rígido. O Parlamento também aprovou a Lei do Selo, que exigia que os americanos comprassem papel timbrado especial para todo tipo de negócio. (James West Davidson. Uma breve história dos Estados Unidos, 2016. Adaptado.)',null,'["à Petição de Direitos, assinada pelo rei Carlos I para transferir o seu poder de cobrar tributos ao parlamento britânico.", "ao reforço dos laços coloniais, impostos às Treze Colônias pelos britânicos após os prejuízos financeiros advindos da Guerra dos Sete Anos.", "à implantação dos Atos de Navegação, aprovados por Oliver Cromwell para estabelecer o uso exclusivo de navios ingleses no transporte de mercadorias para as colônias.", "ao despotismo esclarecido, adotado pela Coroa britânica nas suas colônias americanas durante o processo de Revolução Industrial.", "à política do cercamento das terras comunais nas colônias britânicas, tornando-as mais produtivas e rentáveis para a Metrópole."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'História','Com base no excerto, conclui-se que os movimentos pró-descolonização da Ásia e da África','Os líderes dos movimentos nacionalistas foram instruídos pelas nações conquistadoras: Jinnah, o chefe da Liga Muçulmana; Nehru, o líder do Partido do Congresso da Índia; Dato Onn Bingaafar, na Malásia; Nkrumah, na Costa do Ouro; Bourguiba, na Tunísia, e Forhat Abbas, na Argélia. Eles conheceram a filosofia política ocidental através do ensino, da imprensa, das longas permanências nas prisões das potências coloniais e nos contatos mantidos com os partidos políticos ocidentais. (Letícia Bicalho Canêdo. A descolonização da Ásia e da África, 1994.)',null,'["apoiaram-se nas suas tradições locais em detrimento das influências estrangeiras.", "desafiaram os valores capitalistas ocidentais na ampla maioria dos países independentes.", "corroboraram a ideia de separação entre Estado e nação na formação do Terceiro Mundo.", "buscaram modelos e ideologias europeias para lutar por suas independências.", "organizaram sociedades multinacionais para enfrentar as reações metropolitanas contra a independência."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'História','No contexto do excerto, um dos principais alvos da Com panhia Holandesa das Índias Ocidentais era','A história das invasões holandesas liga-se à passagem do trono português à coroa espanhola. Na medida em que havia um conflito aberto entre a Espanha e os Países Baixos, o relacionamento entre Portugal e Holanda iria inevitavelmente mudar. Mas a Trégua dos Doze Anos entre Espanha e os Países Baixos (1609-1621) deixou Portugal em situação relativamente calma. O fim da trégua e a criação da Companhia Holandesa das Índias Ocidentais (WIC) marcam a mudança do quadro. (Boris Fausto. História do Brasil, 2007. Adaptado.)',null,'["a busca de uma aliança político-militar entre Portugal e a Holanda para pôr fim à chamada União Ibérica.", "o controle da produção açucareira na América portu guesa e do suprimento de escravizados na África.", "a consolidação da independência dos Países Baixos frente às constantes ameaças do Império espanhol à autonomia desses territórios.", "a derrota da Insurreição Pernambucana para liquidar as tentativas luso-brasileiras de expulsão dos holandeses do Nordeste.", "o estabelecimento de um governo holandês no território brasileiro a fim de assegurar o monopólio comercial do pau-brasil."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'História','As informações do excerto sobre a cidadania política justificam-se, entre outras razões, pela seguinte determinação da Constituição de 1891:','A República, ou os vitoriosos da República, fizeram muito pouco em termos de expansão de direitos civis e políticos. Algumas mudanças trazidas pela Constituição dos Estados Unidos do Brasil de 1891, como a eliminação do Poder Moderador, do Senado Vitalício e do Conselho de Estado e a introdução do federalismo, tinham sem dúvida inspiração democratizante na medida em que buscavam desconcentrar o exercício do poder. Mas, não vindo acompanhadas por expansão significativa da cidadania política, resultaram em entregar o governo mais diretamente nas mãos dos setores dominantes, tanto rurais quanto urbanos. (José Murilo de Carvalho. Os bestializados: O Rio de Janeiro e a República que não foi, 1987. Adaptado.)',null,'["os eleitores deviam comprovar renda mínima anual para participarem das eleições primárias como candidatos.", "as mulheres precisavam exercer função pública remunerada para participarem das eleições como eleitoras.", "os homens deviam ser alfabetizados para participarem do processo eleitoral como eleitores ou candidatos.", "os homens precisavam ter idade igual ou superior a vinte e cinco anos para serem eleitores.", "os eleitores deviam ser brasileiros natos, sendo vedada a participação de estrangeiros nas eleições."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'História','Com base nas políticas econômicas do governo de Juscelino Kubitschek, os dados do infográfico relacionam-se','Analise o infográfico sobre a produção automobilística brasileira entre 1957 e 1960. (https://atlas.fgv.br. Adaptado.)','["/pmsp/oficial-2024/q6-3-figura-1.png"]','["ao processo de industrialização autônomo do país, com restrições ao uso do capital estrangeiro.", "à retomada do crescimento da indústria nacional, favorecida por mudanças no sistema tributário do país.", "à proibição das importações de bens de consumo duráveis para diminuir o déficit público do país.", "à instalação de multinacionais no país para a produção de mercadorias antes importadas.", "ao incremento de programas de distribuição de renda no país para ampliar o mercado consumidor interno."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Filosofia','Ao longo da história do pensamento humano ocidental, a filosofia desenvolveu-se em um diálogo constante de embates e acordos. Nesse sentido, a ilustração provoca reflexão sobre','A ilustração a seguir pertence a um catálogo on-line de estampas de camisetas disponíveis para compra. Sim, giramos em torno do sol! Galileu 1564-1642 d.C. Copérnico 1473-1543 d.C. Ptolomeu 100-170 d.C. Aristarco 310-230 a.C. Aristóteles 384-322 a.C. (www.doppelstore.com.br. Adaptado.)','["/pmsp/oficial-2024/q7-4-figura-1.png"]','["a consolidação de uma oposição entre racionalismo e empirismo.", "a incompatibilidade entre conhecimento popular e filosófico.", "a existência de uma aproximação entre nominalismo e realismo.", "o desenvolvimento de uma trajetória entre Antiguidade e revolução científica.", "a superioridade da abordagem dualista em relação ao monismo."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Filosofia','Descrita como um sucesso, a situação noticiada','Analise a notícia. Cientistas chineses conseguiram clonar com sucesso um macaco rhesus. A informação foi divulgada em 16.01.2024. O relatório detalha a experiência de clonar o macaco e aborda os avanços da tecnologia de clonagem. A equipe de cientistas disse que seguiu as leis e diretrizes chinesas sobre uso de primatas não-humanos em estudos. A Sociedade Real para a Prevenção de Crueldade Animal do Reino Unido afirmou que possui “sérias preocupações éticas e de bem-estar em torno do uso de tecnologia de clonagem de animais”. (“Cientistas chineses realizam primeira clonagem de macaco rhesus”. www.cnnbrasil.com.br, 16.01.2024. Adaptado.)',null,'["envolve controvérsias sobre a necessidade de pesquisas em animais para beneficiar humanos.", "demonstra a ausência de polêmicas no processo que envolve a manipulação da vida animal.", "indica um estudo aplicável imediatamente em testes empíricos sobre a saúde humana.", "revela as inovações científicas na manutenção de espécies ameaçadas de extinção.", "evidencia a condução metodológica da pesquisa pelo princípio bioético da autonomia."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Filosofia','Em sua obra A República, Platão discute a noção de justiça e como ela se manifesta tanto na cidade ideal como nos indivíduos. Essa discussão apresenta o impasse indicado no excerto, a partir do qual a noção de desigualdade é','Para Platão, o homem tende à socialização, ou seja, é naturalmente que os homens se unem para formar uma cidade e, desse modo, satisfazerem mais facilmente suas necessidades. A igualdade entre os homens, de acordo com Platão, não existe, e isto é para ele mais um traço da natureza humana. A propriedade é um dos fatores necessários para entender a questão da desigualdade. Há que se notar que Platão, por meio da proibição da propriedade, tenta, de uma certa forma, sanar a desigualdade social. No entanto, em seu estado ideal, ele instaura classes sociais que não devem intrometer-se umas nas outras, pois, sendo uns superiores e outros inferiores, devem permanecer em seu lugar, exercendo a função que lhes fora designada por natureza. (Cristiane Aparecida Barbosa. “A desigualdade nos clássicos políticos: de Platão a Rousseau”. Educação e Filosofia, 2004. Adaptado.)',null,'["o principal reflexo da democracia direta.", "uma condição inerente aos humanos.", "amenizada pelo acesso à propriedade.", "a causa de ataques entre os homens.", "gerada pela ação dos governantes."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Filosofia','(Quino. Toda Mafalda, 2010.) A reflexão suscitada pela tirinha é estudada em Filosofia a partir da',null,'["/pmsp/oficial-2024/q10-6-figura-1.png"]','["investigação dos critérios subjacentes ao juízo estético.", "análise da natureza das categorias fundamentais do ser.", "avaliação de justificativas e fundamentos das decisões morais.", "compreensão dos elementos estruturantes da realidade.", "identificação de origem e limites do conhecimento."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Sociologia','De acordo com o pensamento do autor, a atuação da tendência dominante em circunstâncias cotidianas','[…] a agricultura e a vida econômica costumam estabelecer para si mesmas outros fins que não a satisfação da necessidade de alimento; o casamento em geral expressa outras coisas, de maneira mais visível, que a preferência sexual; e o luto não enfatiza com clareza o pesar. Quanto mais intimamente conhecemos o funcionamento interno de diferentes culturas, com mais facilidade podemos ver que a variabilidade quase infinita em qualquer traço cultural, se ele for observado em volta do globo, não é um mero eco das mudanças em alguma simples resposta humana subjacente. Esteve em ação uma força diferente e maior, que usou as situações recorrentes de acasalamento, morte, abastecimento e as demais quase como matéria-prima, e as elaborou para expressar sua própria intenção. Podemos chamar essa força que curva ocasiões segundo seus propósitos e as molda a seu próprio idioma dentro dessa sociedade de sua tendência dominante. (Celso Castro. Textos básicos de Antropologia – cem anos de tradição: Boas, Malinowski, Lévi-Strauss e outros, 2016.)',null,'["revela a imprevisibilidade dos comportamentos sociais.", "manifesta-se de acordo com a cultura de cada grupo.", "realiza-se a partir da aquisição de bens essenciais.", "evidencia a universalização das ações humanas.", "confirma a desobrigação social com os rituais."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Sociologia','O excerto revela que','Apesar de o Brasil ter uma das maiores áreas cultiváveis do planeta devido ao clima e ao solo favoráveis, 116 milhões de habitantes vivem em situação de insegurança alimentar. […] E, ao mesmo tempo em que 19 milhões de cidadãos no país passam fome, 26,8% da população adulta sofrem de obesidade devido à alimentação baseada em produtos baratos, ultraprocessados ou de pouco valor nutritivo. (Maria Eduarda Cardim e Rosana Hessel. “Brasil das safras recordes enfrenta fome e obesidade”. www.correiobraziliense.com.br, 10.02.2022.)',null,'["o desenvolvimento econômico exige políticas que restrinjam a alimentação dos mais pobres.", "a grande presença de obesos brasileiros pertencentes às classes mais baixas mostra uma contradição.", "as políticas públicas voltadas para o combate à obesi dade devem considerar a desigualdade social.", "a obesidade no Brasil é predominantemente um problema de escolhas individuais e falta de disciplina pessoal.", "as classes sociais mais baixas têm boa alimentação devido ao valor acessível de produtos orgânicos."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Sociologia','A situação retratada no excerto remete','Uma história de 150 anos que começa com uma viagem de um mês e meio em condições precárias, nos fundos de um navio, agarrando-se à família e à esperança de um futuro do outro lado do oceano. Assim chegavam cerca de 400 italianos à costa brasileira em 21 de fevereiro de 1874, pioneiros de um movimento que atraiu 1,4 milhão de pessoas em 50 anos. A travessia, realizada no navio La Sofia, de Gênova rumo ao Espírito Santo, alterou para sempre não somente a vida de cada um desses desbravadores, mas a cultura e a economia brasileiras, que ganharam contornos italianos inegáveis desde então. (Gabriel Rodrigues. “Há 150 anos, imigração italiana foi pioneira e transformou o Brasil”. www.otempo.com.br, 21.02.2024.)',null,'["à etapa da miscigenação brasileira pautada pelo princípio da democracia racial.", "à importância do desenvolvimento de infraestrutura moderna para acomodar os imigrantes.", "à relevância de políticas sociais para a recuperação da economia brasileira após a crise do café.", "ao início da contribuição italiana para a cultura brasileira a partir de políticas de embranquecimento do Brasil.", "à iniciativa brasileira de prover melhores condições de vida aos italianos como estratégia de combate ao eurocentrismo."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Sociologia','A elaboração descrita no excerto é parte das funções típicas do Poder','Ao ser criada uma nova política pública, devem ser definidos, entre outros itens, os responsáveis pela coordenação e articulação das ações; as competências das principais partes envolvidas, com respectivos objetivos, papéis, responsabilidades, recursos e obrigações; o grau de focalização ou universalização da política pública, considerando as necessidades do público-alvo e os recursos disponíveis; e o plano de gestão de riscos com a identificação dos principais problemas que podem surgir e as medidas mitigadoras para tratá-los. (“Aprovado projeto que estabelece normas para criação de políticas públicas”. www.coad.com.br, 05.04.2018.)',null,'["Judiciário.", "Bicameral.", "Legislativo.", "Moderador.", "Executivo."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Geografia','Os eventos geológicos descritos no excerto são provocados pelo movimento','A ilha de Taiwan sofreu com o maior terremoto em 25 anos no dia 02.04.2024, quando um abalo sísmico de 7,4 na esca-la Richter foi sentido na cidade de Hualien, que está situada a cerca de 150 quilômetros da capital, Taipei, como informou o Serviço Geológico dos Estados Unidos (United States Geological Survey, da sigla USGS). O terremoto também foi sentido em Xangai, na China, e em várias províncias ao longo da costa sudeste chinesa. A intensidade do tremor alcançou cerca de 35 quilômetros de profundidade e com isso um alerta de tsunami foi gerado no Japão. Ao longo dos últimos 50 anos, o território de Taiwan tem sofrido com terremotos de alta intensidade e o principal motivo é a sua localização geográfica no mundo. (www.nationalgeographicbrasil.com, 03.04.2024. Adaptado.)',null,'["transformante entre as placas Euroasiática e Indiana, na zona sísmica do Pacífico.", "convergente entre as placas Euroasiática e Filipina, na zona do círculo de fogo.", "transformante entre as placas Australiana e do Pacífico, na zona do círculo de fogo.", "convergente entre as placas Australiana e de Nasca, na zona sísmica do Pacífico.", "divergente entre as placas Indiana e de Cocos, na zona da dorsal meso-oceânica."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Geografia','A partir da análise do gráfico e de conhecimentos sobre a crise ambiental em escala mundial, verifica-se que','Extração global de recursos, quatro categorias principais de recursos, 1970-2024, milhões de toneladas (Programa das Nações Unidas para o Meio Ambiente (Pnuma). Perspectiva de Recursos Globais, 2024. Adaptado.)','["/pmsp/oficial-2024/q16-10-figura-1.png"]','["o crescimento da extração de biomassa está relacionado aos esforços globais para mitigar as metas de controle de poluição.", "o baixo crescimento da extração de combustíveis fósseis está relacionado à preferência pela utilização de energia sustentável nos países desenvolvidos.", "o baixo crescimento da extração de minerais metálicos está relacionado às preocupações com a pegada ecológica dos processos industriais.", "o crescimento da extração de minerais não metálicos está relacionado ao aumento das emissões de gases do efeito estufa.", "a diminuição da extração de biomassa está relacionada ao estímulo à equidade socioambiental nos países do Sul Global."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Geografia','O cenário descrito no excerto tem como consequência','Transformação digital, 5G, indústria 4.0, inteligência arti ficial (IA), computação em nuvem, blockchain e muitos outros termos são novas expressões que têm inundado o mundo inteiro. A transformação digital é uma mudança radical na forma de pensar como uma organização utiliza tecnologia, pessoas e processos para alterar seu desempenho nos negócios. Empregam-se tecnologias e ferramentas digitais para criar ou modificar processos de negócios existentes, culturas empresariais e a experiência do usuário, conseguindo assim atender aos requisitos de mercado em constante modificação. (Robert Spadinger. “Internet das coisas (IOT) transformação digital e indústria 4.0”. In: Luiz Claudio Kubota (org.). Digitalização e tecnologias da informação e comunicação, 2024. Adaptado.)',null,'["a diversificação do ambiente empresarial pela contratação de trabalhadores terceirizados.", "a distribuição de polos industriais de alta tecnologia pela adaptação do modelo fordista.", "a diminuição do desemprego conjuntural pelo investimento na qualificação do trabalhador.", "a mitigação da concentração do capital pela distribuição da produção industrial das Big Techs.", "a transformação do mercado de trabalho pelo aprofundamento do desemprego estrutural."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Geografia','Sabendo que a Geórgia está localizada na Europa Oriental e que integrou a União Soviética, a lei mencionada no excerto é um instrumento que limita seus interesses geopolíticos quanto','Apesar dos protestos nas ruas e alertas da comunidade internacional, o Parlamento da Geórgia adotou uma polêmica lei sobre a influência estrangeira, que afeta a regulação de veículos de comunicação e Organizações Não-Governamentais (ONGs). A lei exige que os meios de comunicação e as ONGs que obtenham mais de 20% de seu orçamento do exterior se registrem como órgãos que “cumprem o interes-se de uma potência estrangeira”. Para os opositores, essa lei restringirá a liberdade de imprensa e obstruirá as chances de a Geórgia ingressar em organismos multilaterais de cooperação internacional. A presidente da Geórgia, Salome Zurabishvili, vetou a lei em 18.05.2024. Na ocasião, ela disse que o texto “contradiz nossa Constituição e todas as normas europeias”, representando um “obstáculo ao nosso caminho europeu”. (Parlamento da Geórgia aprova lei de ‘influência estrangeira’ em meio a protestos contra medida. https://oglobo.globo.com, 29.05.2024. Adaptado.)',null,'["à sua entrada no Conselho para Assistência Econômica Mútua (COMECON), uma vez que o país terá vantagens para importar gás natural produzido no bloco.", "à sua admissão na Comunidade dos Estados Independentes (CEI), uma vez que o país busca estreitar as relações diplomáticas com a Rússia.", "à sua condição de país-membro na Organização do Tratado do Atlântico Norte (Otan), uma vez que o país integra a aliança militar desde a dissolução da União Soviética.", "à sua adesão à União Europeia (UE), uma vez que o país já possui o reconhecimento da sua condição de país candidato pelo bloco.", "à sua participação no acordo de Oslo, uma vez que o país deseja integrar o Tribunal Penal de Haia para punir os crimes de guerra sofridos durante a separação da Iugoslávia."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Geografia','De acordo com a análise do cartograma e conhecimentos sobre a estrutura do agronegócio brasileiro, a variação na produção e exportação de grãos da soja e do milho ao norte e ao sul do paralelo 16º S é resultado','Analise o cartograma que demonstra a produção e a exportação da soja e do milho acima e abaixo do paralelo 16º S, em 2023. (www.canalrural.com.br, 09.03.2024.)','["/pmsp/oficial-2024/q19-13-figura-1.png"]','["de modelos distintos de financiamento, que seguem linhas de crédito diferenciadas de acordo com o destino dos produtos.", "da diferença na estrutura fundiária das monocultoras, que estão assentadas em minifúndios e latifúndios.", "da desigual distribuição da infraestrutura logística insta lada, que compromete a competitividade dos produtos.", "da função social desempenhada pela propriedade rural, que possibilita atender os mercados interno e externo em diferentes regiões.", "da variação das condições ambientais, que altera a capacidade de produção devido ao uso de sementes transgênicas ou crioulas."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Geografia','A característica da população jovem brasileira apresentada no excerto tem como impacto','Há, em 2024, mais jovens no Brasil que não estudam, não trabalham e nem estão procurando emprego. No primeiro trimestre de 2023, havia cerca de 4 milhões de pessoas entre 14 e 24 anos nessa condição. Agora, no mesmo período do ano, são 5,4 milhões. De acordo com o levantamento, cerca de 60% dessa população é composta por mulheres. A maior parte delas, inclusive, tem filhos pequenos. Em um outro recorte, 68% dos que não estudam, não trabalham e nem buscam emprego são negros. (André Lucena. www.cartacapital.com.br, 28.05.2024. Adaptado.)',null,'["a diminuição da capacidade produtiva do país, o que resulta em menor crescimento do PIB.", "o aumento da taxa de fecundidade do país, o que esti mula o crescimento demográfico.", "a estabilidade da transição demográfica do país, o que provoca aumento na expectativa de vida ao nascer.", "o crescimento do setor terciário no país, o que promove aumento do desemprego estrutural.", "o incremento do subemprego no país, o que resulta em menores taxas de informalidade."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Língua Portuguesa','O efeito de humor da tirinha se dá por meio do emprego da linguagem','Examine a tirinha de Fernando Gonsales, publicada no site do autor em 08.04.2024, para responder às questões 21 e 22. (www.niquel.com.br)','["/pmsp/oficial-2024/apoio-21-22-15-1.png"]','["conotativa.", "metonímica.", "denotativa.", "comparativa.", "antagônica."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Língua Portuguesa','O ponto de exclamação é uma pontuação versátil que pode explicitar uma ampla gama de emoções e intenções. Na fala do primeiro e do último quadrinho, esse ponto expressa, respectivamente,','Examine a tirinha de Fernando Gonsales, publicada no site do autor em 08.04.2024, para responder às questões 21 e 22. (www.niquel.com.br)','["/pmsp/oficial-2024/apoio-21-22-15-1.png"]','["surpresa e ordem.", "entusiasmo e frustração.", "excitação e ironia.", "alegria e desespero.", "ênfase e dúvida."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Língua Portuguesa','De acordo com o trecho, Amália considerava o casamento uma','Leia o trecho do romance Encarnação, de José de Alencar, para responder às questões de 23 a 28. Conheci outrora uma família que morava em São Clemente. Havia em sua casa agradáveis reuniões de que fazia os encantos uma filha, bonita moça de dezoito anos, corada como a aurora e loura como o sol. Amália seduzia especialmente pela graça radiante, e pela viçosa e ingênua alegria, que manava dos lábios vermelhos, como dos olhos de topázio, e lhe rorejava¹ a lúcida beleza. Sua risada argentina era a mais cintilante das volatas² que ressoavam entre os rumores festivos da casa, onde à noite o piano trinava sob os dedos ágeis da melhor discípula do Arnaud. Acontecia-lhe chorar algumas vezes por causa de um vestido que a modista não lhe fizera a gosto, ou de um baile muito desejado que se transferia; mas essas lágrimas efêmeras, que saltavam em bagas dos grandes olhos luminosos, iam nas covinhas da boca transformar-se em cascatas de risos frescos e melodiosos. Tinha razão de folgar. Era o carinho dos pais e a predileta de quantos a conheciam. Muitos dos mais distintos moços da corte a adoravam. Ela, porém, preferia a isenção de menina; e não pensava em escolher um dentre tantos apaixonados, que a cercavam. Os pais, que desejavam muito vê-la casada e feliz, sentiam quando ela recusava algum partido vantajoso. Mas reconheciam ao mesmo tempo que formosa, rica e prendada como era, a filha tinha o direito de ser exigente; e confiavam no futuro. Outra e bem diversa era a causa da indiferença da moça. Amália não acreditava no amor. A paixão para ela só existia no romance. Os enlevos³ de duas almas a viverem uma da outra não passavam de arroubos de poesia, que davam em comédia quando os queriam transportar para o mundo real. Tinha sobre o casamento ideias mui positivas. Considerava o estado conjugal uma simples partilha de vida, de bens, de prazeres e trabalhos. Estes não os queria: os mais ela os possuía e gozava, mesmo solteira, no seio de sua família. Era feliz; não compreendia, portanto, a vantagem de ligar-se para sempre a um estranho, no qual podia encontrar um insípido companheiro, se não fosse um tirano doméstico. Estes pensamentos, Amália não os enunciava, nem os erigia em opiniões. Eram apenas os impulsos íntimos de sua vontade; obedecendo a eles, não tinha a menor pretensão à excentricidade. Ao contrário, como sabia do desejo dos pais, aceitava de boa mente a corte de seus admiradores. Mas estes bem percebiam que para a travessa e risonha vestal⁴ dos salões, o amor não era mais do que um divertimento de sociedade, semelhante à dança ou à música. Conservando a sua independência de filha querida, e moça da moda, Amália não nutria prejuízos contra o casamento, que aliás aceitava como uma solução natural para o outono da mulher. Ela bem sabia, que depois de haver gozado da mocidade, no fim de sua esplêndida primavera, teria de pagar o tributo à sociedade, e como as outras escolher um marido, fazer-se dona-de-casa, e rever nos filhos a sua beleza desvanecida. Até lá, porém, era e queria ser flor. Das suas lições de botânica lhe ficara bem viva esta recordação, que o fruto só desponta quando as pétalas começam a fanar-se: se vem antes disso, eiva⁵. (Encarnação, 2003.) ¹ rorejar: gotejar. ² volata: série de notas musicais executadas rapidamente. ³ enlevo: êxtase, deleite. 4 vestal: sacerdotisa da deusa romana Vesta; mulher muito bonita que devia guardar rigorosa castidade. ⁵ eivar: falhar.',null,'["consequência natural da vida.", "instituição falida e sem propósito.", "escolha inconsciente e baseada no amor.", "imposição social degradante.", "necessidade imediata."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Língua Portuguesa','Na expressão “outono da mulher” (16o parágrafo), a palavra sublinhada é uma metáfora para referir-se','Leia o trecho do romance Encarnação, de José de Alencar, para responder às questões de 23 a 28. Conheci outrora uma família que morava em São Clemente. Havia em sua casa agradáveis reuniões de que fazia os encantos uma filha, bonita moça de dezoito anos, corada como a aurora e loura como o sol. Amália seduzia especialmente pela graça radiante, e pela viçosa e ingênua alegria, que manava dos lábios vermelhos, como dos olhos de topázio, e lhe rorejava¹ a lúcida beleza. Sua risada argentina era a mais cintilante das volatas² que ressoavam entre os rumores festivos da casa, onde à noite o piano trinava sob os dedos ágeis da melhor discípula do Arnaud. Acontecia-lhe chorar algumas vezes por causa de um vestido que a modista não lhe fizera a gosto, ou de um baile muito desejado que se transferia; mas essas lágrimas efêmeras, que saltavam em bagas dos grandes olhos luminosos, iam nas covinhas da boca transformar-se em cascatas de risos frescos e melodiosos. Tinha razão de folgar. Era o carinho dos pais e a predileta de quantos a conheciam. Muitos dos mais distintos moços da corte a adoravam. Ela, porém, preferia a isenção de menina; e não pensava em escolher um dentre tantos apaixonados, que a cercavam. Os pais, que desejavam muito vê-la casada e feliz, sentiam quando ela recusava algum partido vantajoso. Mas reconheciam ao mesmo tempo que formosa, rica e prendada como era, a filha tinha o direito de ser exigente; e confiavam no futuro. Outra e bem diversa era a causa da indiferença da moça. Amália não acreditava no amor. A paixão para ela só existia no romance. Os enlevos³ de duas almas a viverem uma da outra não passavam de arroubos de poesia, que davam em comédia quando os queriam transportar para o mundo real. Tinha sobre o casamento ideias mui positivas. Considerava o estado conjugal uma simples partilha de vida, de bens, de prazeres e trabalhos. Estes não os queria: os mais ela os possuía e gozava, mesmo solteira, no seio de sua família. Era feliz; não compreendia, portanto, a vantagem de ligar-se para sempre a um estranho, no qual podia encontrar um insípido companheiro, se não fosse um tirano doméstico. Estes pensamentos, Amália não os enunciava, nem os erigia em opiniões. Eram apenas os impulsos íntimos de sua vontade; obedecendo a eles, não tinha a menor pretensão à excentricidade. Ao contrário, como sabia do desejo dos pais, aceitava de boa mente a corte de seus admiradores. Mas estes bem percebiam que para a travessa e risonha vestal⁴ dos salões, o amor não era mais do que um divertimento de sociedade, semelhante à dança ou à música. Conservando a sua independência de filha querida, e moça da moda, Amália não nutria prejuízos contra o casamento, que aliás aceitava como uma solução natural para o outono da mulher. Ela bem sabia, que depois de haver gozado da mocidade, no fim de sua esplêndida primavera, teria de pagar o tributo à sociedade, e como as outras escolher um marido, fazer-se dona-de-casa, e rever nos filhos a sua beleza desvanecida. Até lá, porém, era e queria ser flor. Das suas lições de botânica lhe ficara bem viva esta recordação, que o fruto só desponta quando as pétalas começam a fanar-se: se vem antes disso, eiva⁵. (Encarnação, 2003.) ¹ rorejar: gotejar. ² volata: série de notas musicais executadas rapidamente. ³ enlevo: êxtase, deleite. 4 vestal: sacerdotisa da deusa romana Vesta; mulher muito bonita que devia guardar rigorosa castidade. ⁵ eivar: falhar.
