insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Matemática','Os números 85 e 775 são extremos de uma progressão aritmética (PA) crescente. Sabendo que existem 29 termos entre esses extremos, a razão dessa PA é igual a',null,null,'["21.", "23.", "25.", "27.", "29."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Matemática','Considere o polinômio P(x) = x⁵ – 6x⁴ – 39x³ + 416x² + kx + 1 152, em que k é uma constante real. Esse polinômio tem duas raízes positivas distintas de multiplicidade 2, sendo que uma dessas raízes é 3. Sabendo que – 8 é uma raiz simples de P, o valor da constante k é',null,null,'["– 1 200.", "– 600.", "– 300.", "– 150.", "– 75."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Matemática','Com os algarismos 1, 2, 3, 4, 5 e 7 serão formados números de 3 algarismos, da forma cdu, com c representando o algarismo das centenas, d o das dezenas e u o das unidades, obedecendo às seguintes condições: • os números pares devem ser tais que c ≥ d e d > u; • os números ímpares devem ser tais que c > u. Nessas condições, o total de números distintos que podem ser formados é',null,null,'["15.", "24.", "67.", "90.", "120."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Matemática','Rafael correu todos os dias desde o dia 30 de maio até o dia do seu aniversário, inclusive. No total ele percorreu 525 km, com uma média de 15 km corridos por dia. O dia do aniversário de Rafael é',null,null,'["2 de julho.", "3 de julho.", "4 de julho.", "5 de julho.", "6 de julho."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Matemática','Considere as matrizes A = [[x, −3, −1], [1, 0, x], [2, 1, 3]] e B = [[x, 1], [x + 1, −5]], em que x é um número positivo. Sabendo que os determinantes dessas duas matrizes são ambos iguais a y, o valor de y é',null,null,'["– 19.", "– 7.", "1.", "8.", "20."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Matemática','No plano cartesiano, a reta r, de equação x – 2y + 6 = 0, é perpendicular à reta s no ponto de coordenadas (– 2, 2). Essas retas e os eixos cartesianos determinam um quadrilátero, conforme mostra a figura. A área desse quadrilátero é',null,'["/pmsp/oficial-2024/q50-32-figura-1.png"]','["2.", "2,5.", "3.", "3,5.", "4."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,51,'Matemática','Um octógono, de área 83 cm² e perímetro 40 cm, tem todos os seus ângulos retos, conforme a figura, que mostra as medidas, em cm, de alguns lados. O algarismo das unidades de x, considerado em cm, é',null,'["/pmsp/oficial-2024/q51-33-figura-1.png"]','["9 ou 6.", "8 ou 0.", "7 ou 5.", "4 ou 2.", "3 ou 1."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,52,'Matemática','Considere as funções f(x) = 3x² – 5x + 1, g(x) = 2x + 7 e h(x) = 11x² + 100x – 55. Se k é o maior número real que satisfaz h(k) = f(g(k)), então',null,null,'["– 11 ≤ k < – 3.", "– 3 ≤ k < 6.", "6 ≤ k < 12.", "12 ≤ k < 19.", "19 ≤ k ≤ 24."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,53,'Matemática','Em um triângulo retângulo FGH, reto em F, o ponto D divide o cateto FH em duas partes de medidas 6 cm e 4 cm, conforme mostra a figura. O valor de sen α é',null,'["/pmsp/oficial-2024/q53-35-figura-1.png"]','["√2/10", "√2/20", "√6/10", "√7/14", "√7/20"]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,54,'Matemática','A base de uma pirâmide regular FABCD é um quadrado de área 16 cm². A face FCD dessa pirâmide é base da pirâmide GFCD. A altura da pirâmide GFCD em relação à face FCD é de 3 cm. Sabendo que o volume da pirâmide GFCD é 4√10 cm³, o volume da pirâmide FABCD é',null,'["/pmsp/oficial-2024/q54-36-figura-1.png", "/pmsp/oficial-2024/q54-36-figura-2.png"]','["32 cm³", "64/3 cm³", "48 cm³", "80/3 cm³", "64 cm³"]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,55,'Matemática','Seja P(x) = 3x² + mx + n, com m, n ∈ ℝ, um polinômio divisível por (x + 5). Sabendo que o resto da divisão de P(x) por (x – 1) é igual ao resto da divisão de P(x) por (x + 2), a diferença m – n é igual a',null,null,'["50.", "57.", "63.", "66.", "79."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,56,'Matemática','Um grupo é formado por 60 turistas, entre homens, mulheres e crianças. O número de crianças no grupo é um a mais do que o quádruplo do número mulheres. Sabendo que nesse grupo há menos do que 7 homens, a diferença entre o número de mulheres e o de homens é igual a',null,null,'["3.", "4.", "5.", "6.", "7."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,57,'Física','Analise o gráfico que representa a variação da velocidade de um objeto, em função do tempo, durante determinado movimento. O gráfico representa o movimento de',null,'["/pmsp/oficial-2024/q57-38-figura-1.png"]','["uma composição do metrô entre duas estações.", "um pêndulo durante metade de uma oscilação.", "uma pedra lançada verticalmente para cima.", "uma xícara que caiu de uma mesa.", "uma bola de basquete arremessada para a cesta."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,58,'Física','Ao decolar de um aeroporto, um avião de massa 5,0 × 10⁴ kg partiu do repouso e acelerou pela pista por 30 s até atingir a velocidade necessária para deixar o solo, que era de 60 m/s. A intensidade média da força resultante que atuou sobre esse avião durante essa decolagem foi de',null,null,'["2,5 × 10⁴ N.", "7,5 × 10⁴ N.", "1,0 × 10⁵ N.", "5,0 × 10⁵ N.", "9,0 × 10⁷ N."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,59,'Física','Sabendo que a diferença entre as alturas do halter, em relação ao solo, nas posições 1 e 2 é de 40 cm e considerando a aceleração gravitacional igual a 10 m/s², o trabalho realizado pelo peso do halter no deslocamento entre as posições 1 e 2 foi de','Durante a execução de um exercício físico em uma academia, uma pessoa abaixa lentamente um halter de 20 kg da posição 1 até a posição 2, mostradas na figura. (www.fitness4all.pt. Adaptado.)','["/pmsp/oficial-2024/q59-39-figura-1.png", "/pmsp/oficial-2024/q59-39-figura-2.png"]','["70 J.", "80 J.", "160 J.", "240 J.", "500 J."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,60,'Física','Um bloco preso a uma mola ideal oscila verticalmente entre as posições X e Y mostradas na figura. Considere que o sistema físico seja formado por bloco, mola e Terra e que as forças de resistência sejam desprezíveis. Enquanto o bloco oscila, ocorrem variações nos valores das energias',null,'["/pmsp/oficial-2024/q60-40-figura-1.png", "/pmsp/oficial-2024/q60-40-figura-2.png"]','["mecânica, cinética e potencial elástica, apenas.", "potencial gravitacional e potencial elástica, apenas.", "potencial gravitacional, potencial elástica e mecânica, apenas.", "cinética e mecânica, apenas.", "potencial elástica, potencial gravitacional e cinética, apenas."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,61,'Física','O aumento no comprimento, ΔL, de uma haste metálica, quando há um aumento de temperatura de T₀ para T, é dado pela expressão ΔL = L₀ · α · (T – T₀), sendo L₀ o comprimento da barra à temperatura T₀ e α uma constante que depende do material e que é denominada como coeficiente de dilatação térmica linear. A tabela apresenta o coeficiente de dilatação térmica linear de alguns materiais. Coeficiente de dilatação Material térmica linear (10 – ⁶ ºC – ¹) Platina 9 Ferro 12 Cobre 17 Alumínio 24 Chumbo 29 Considere duas hastes metálicas, P e Q, que apresentam, à temperatura T₀, comprimentos d e 2d, respectivamente. Quando a temperatura dessas hastes é aumentada para T, seus comprimentos aumentam de um mesmo valor Δd. Considerando apenas os materiais listados na tabela, as hastes P e Q são constituídas, respectivamente, por',null,'["/pmsp/oficial-2024/q61-41-figura-1.png"]','["chumbo e platina.", "cobre e ferro.", "alumínio e platina.", "alumínio e ferro.", "chumbo e alumínio."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,62,'Física','A figura mostra os sentidos e valores de correntes elétricas que chegam e saem de um ponto P de um circuito elétrico. O valor da corrente ix é igual a',null,'["/pmsp/oficial-2024/q62-42-figura-1.png"]','["15 mA.", "30 mA.", "35 mA.", "55 mA.", "105 mA."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,63,'Química','O gás dióxido de cloro (CℓOx) vem sendo utilizado no lugar do gás cloro (Cℓ₂) em várias estações de tratamento de água (ETA) para o abastecimento público, pois o dióxido de cloro fornece proteção microbiológica da água por vários dias. O dióxido de cloro pode ser obtido pela reação entre o clorito de sódio sólido, fórmula unitária NaCℓOx, e o gás cloro, segun do a reação representada pela equação química genérica: yNaClOx (s) + zCl₂ (g) → wClOx (g) + 2NaCℓ (s) Nessa equação, x aparece nas fórmulas do clorito de sódio e do dióxido de cloro e y, z e w são os coeficientes estequiométricos que completam o balanceamento da equação. O valor do índice x nas fórmulas da equação é igual a . A soma dos menores coeficientes estequiométricos inteiros, y, z e w, que balanceiam a equação é . O elemento químico de maior raio atômico presente no sólido formado na reação apresenta número atômico igual a . As lacunas do texto são preenchidas, respectivamente, por:',null,'["/pmsp/oficial-2024/tabela-periodica-1.png"]','["2 – 5 – 11.", "1 – 7 – 17.", "1 – 5 – 11.", "2 – 7 – 8.", "2 – 7 – 11."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,64,'Química','Em um laboratório, são usadas aparelhagens específicas para cada método de separação de mistura. Um desses métodos está representado na figura: A aparelhagem representada na figura é empregada no processo de',null,'["/pmsp/oficial-2024/q64-44-figura-1.png", "/pmsp/oficial-2024/tabela-periodica-1.png"]','["decantação, resultando na separação de um líquido e um sólido imiscível.", "destilação simples, resultando na separação de dois líquidos imiscíveis.", "destilação simples, resultando na separação dos componentes da mistura homogênea formados por um sólido não volátil dissolvido em um líquido.", "decantação, resultando na separação dos componentes da mistura homogênea.", "flotação, resultando na separação dos componentes de uma mistura heterogênea de um sólido e um líquido."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,65,'Química','Em uma proveta foram adicionados três líquidos imiscíveis, água, clorofórmio e mercúrio, que formaram o sistema trifásico representado na figura. As densidades desses líquidos estão dadas na tabela. Líquido Densidade 13,6 g/cm³ Mercúrio 1,53 g/cm³ Clorofórmio 1,00 g/cm³ Água Considerando o sistema trifásico formado e as informações fornecidas na tabela, afirma-se que',null,'["/pmsp/oficial-2024/q65-45-figura-1.png", "/pmsp/oficial-2024/tabela-periodica-1.png"]','["o mercúrio é menos denso que o líquido B.", "a água corresponde ao líquido B.", "o clorofórmio é o líquido C e o menos denso.", "o mercúrio é o líquido A e o mais denso.", "o clorofórmio é o líquido B e mais denso que o líquido A."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,66,'Química','As ligações químicas correspondem à união de átomos para a formação de compostos químicos, como os representados nas figuras 1, 2 e 3. As ligações químicas nas figuras 1, 2 e 3 são, respectivamente,',null,'["/pmsp/oficial-2024/q66-45-figura-1.png", "/pmsp/oficial-2024/tabela-periodica-1.png"]','["metálica, covalente e iônica.", "iônica, iônica e metálica.", "covalente, covalente e iônica.", "iônica, covalente e metálica.", "iônica, covalente e iônica."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,67,'Química','Considere o gráfico de mudança de estado físico de uma substância pura X. A substância X foi aquecida à velocidade constante partindo do 0 ºC até 250 ºC e, nessa faixa de temperatura, sofreu duas mudanças consecutivas de seu estado físico. As mudanças físicas consecutivas ocorridas nesse intervalo de temperatura são, respectivamente,',null,'["/pmsp/oficial-2024/q67-46-figura-1.png", "/pmsp/oficial-2024/tabela-periodica-1.png"]','["solidificação e liquefação.", "fusão e vaporização.", "sublimação e vaporização.", "fusão e sublimação.", "liquefação e solidificação."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,68,'Química','A chuva ácida é um termo amplo que, como o próprio nome sugere, inclui qualquer tipo de precipitação com componentes ácidos que cai no solo a partir da atmosfera na forma de chuva, neve, neblina, granizo ou até poeira ácida. A chuva ácida, ao cair na superfície, altera a composição química do solo e das águas causando alterações no meio ambiente. A chuva ácida pode ser formada pela reação da água da chuva com',null,'["/pmsp/oficial-2024/tabela-periodica-1.png"]','["CaCO₃", "CO", "CaO", "NH₄OH", "NO₂"]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,69,'Biologia','O álcool ingerido por uma pessoa é metabolizado no fígado e transformado em substâncias inócuas. As organelas das células hepáticas que metabolizam o álcool são',null,null,'["os centríolos e os peroxissomos.", "as mitocôndrias e os ribossomos.", "os ribossomos e os vacúolos digestivos.", "os retículos endoplasmáticos agranulares e os pero xissomos.", "os retículos endoplasmáticos granulares e os lisossomos."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,70,'Biologia','No ácido nucleico que forma o cromossomo,','A figura ilustra a molécula de ácido nucleico que forma um cromossomo. (www.expii.com. Adaptado.)','["/pmsp/oficial-2024/q70-47-figura-1.png"]','["encontram-se bases nitrogenadas pirimídicas e púricas.", "existem hexoses compondo os nucleotídeos.", "as duas fitas complementares conectam-se por ligações peptídicas.", "as bases guaninas ligam-se às bases timinas.", "os grupos fosfatos ligam-se diretamente às bases nitrogenadas."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,71,'Biologia','Ostras, polvos e caracóis se assemelham em muitas caracte rísticas morfológicas e fisiológicas, mas existem diferenças entre eles. O estudo taxonômico desses animais permite incluí-los no mesmo',null,null,'["filo e classe, entretanto, em reinos diferentes.", "reino e classe, entretanto, em filos diferentes.", "reino e filo, entretanto, em classes diferentes.", "reino, entretanto, em filos e classes diferentes.", "filo, entretanto, em reinos e classes diferentes."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,72,'Biologia','Na genealogia a seguir, os indivíduos destacados, 2, 3, 4, 7, 9 e 10, apresentam uma condição genética autossômica. De acordo com essa genealogia, a probabilidade de o casal formado pelos indivíduos 7 e 8 gerar uma criança com o mesmo fenótipo apresentado pela pessoa 7 é',null,'["/pmsp/oficial-2024/q72-48-figura-1.png", "/pmsp/oficial-2024/q72-48-figura-2.png"]','["1/2.", "1/4.", "1/6.", "1/8.", "3/4."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,73,'Biologia','A imagem mostra células sanguíneas humanas adultas e saudáveis. (www.nih.gov) Essas células sanguíneas humanas',null,'["/pmsp/oficial-2024/q73-49-figura-1.png"]','["são essenciais na defesa imunológica.", "transportam gás oxigênio e gás carbônico.", "transmitem os cromossomos para as células-filhas.", "possuem organelas que produzem ATP.", "contêm protrombinas que cessam hemorragias."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,74,'Biologia','Nos grandes grupos de vertebrados, o sistema cardiovascular apresenta variações em relação à anatomia do coração e à trajetória do sangue arterial e do sangue venoso nesse sistema. Dessa forma, o coração do',null,null,'["jacaré é tricavitário e não há mistura do sangue venoso com o arterial no ventrículo.", "tucano é tetracavitário e há mistura do sangue venoso com o arterial nos ventrículos.", "salmão é bicavitário e há circulação de sangue arterial nas câmaras cardíacas.", "lobo é tetracavitário e há circulação de sangue venoso nas câmaras esquerdas do coração.", "sapo é tricavitário e há mistura do sangue venoso com o arterial no ventrículo."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,75,'Noções de Administração Pública','A Constituição Federal expressamente prevê que a soberania popular será exercida pelo sufrágio universal e pelo voto direto e secreto, com valor igual para todos, e, nos termos da lei, mediante',null,null,'["audiência pública, consulta pública e plebiscito.", "consulta pública, plebiscito e referendo.", "plebiscito, referendo e iniciativa popular.", "referendo, iniciativa popular e direito de ação.", "iniciativa popular, direito de ação e serviço militar obri gatório."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,76,'Noções de Administração Pública','De acordo com a Constituição do Estado de São Paulo,',null,null,'["são servidores públicos militares estaduais os integrantes da Polícia Militar do Estado.", "o militar demitido por ato administrativo não poderá ser reintegrado à Corporação.", "o oficial da Polícia Militar perderá o posto e a patente se for julgado indigno do Oficialato pela Justiça comum.", "o oficial condenado na Justiça comum ou militar à pena privativa de liberdade perderá, automaticamente, o posto e a patente.", "o servidor público militar que responder a inquérito ou processo em qualquer jurisdição não será transferido para a reserva em nenhuma hipótese."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,77,'Noções de Informática','No MS-Word 2016, cinco nomes foram digitados, com todas as letras maiúsculas, em cinco linhas consecutivas. Em seguida, os cinco nomes foram selecionados e foi acionado o botão , que pertence ao grupo de opções de formato de Fonte, conforme mostra a figura. Dessa maneira, os cinco nomes foram',null,'["/pmsp/oficial-2024/q77-51-figura-1.png", "/pmsp/oficial-2024/q77-51-figura-2.png"]','["ordenados alfabeticamente, ficando cada nome em uma linha.", "ordenados alfabeticamente, ficando todos os nomes em uma mesma linha.", "posicionados todos em uma mesma linha, mantendo a ordem original.", "mantidos nas mesmas linhas em que se encontravam e foram tachados.", "mantidos nas mesmas linhas em que se encontravam e com todas as letras minúsculas."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,78,'Noções de Informática','No MS-Excel 2016, uma planilha de controle de estoque tem uma imagem na primeira linha e um cabeçalho na terceira linha, que é seguido de várias linhas com os dados do estoque, conforme a figura 1. Deseja-se obter o efeito de rolar pelas linhas dessa planilha de maneira que as três primeiras linhas permaneçam visíveis e as demais rolem por baixo dessas linhas, conforme a figura 2, que mostra que as linhas 4 a 9 rolaram por baixo do cabeçalho. Para conseguir esse efeito, é usada a opção Congelar Painéis da guia Exibir, representada na figura 3. Uma possibilidade para se conseguir esse efeito é',null,'["/pmsp/oficial-2024/q78-52-figura-1.png", "/pmsp/oficial-2024/q78-52-figura-2.png", "/pmsp/oficial-2024/q78-52-figura-3.png"]','["selecionar a linha 3 e clicar em Congelar Painéis.", "selecionar a linha 4 e clicar em Congelar Painéis.", "selecionar a linha 3 e clicar em Congelar Linha Superior.", "selecionar todas as linhas que ficarão visíveis e clicar em Congelar Linha Superior.", "selecionar todas as linhas que ficarão visíveis e clicar em Congelar Painéis."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,79,'Noções de Informática','Em um slide em branco do MS-PowerPoint 2016 foram inseridas 3 formas: primeiramente, uma seta para a direita; depois, um retângulo; e, por último, um triângulo isósceles, conforme a figura 1. Em seguida, apenas a seta para a direita foi selecionada e, na guia Forma de Formato, na opção Avançar, foi selecionado Avançar. Posteriormente, as 3 formas foram selecionadas e, na guia Forma de Formato, na opção Alinhar, com a opção Alinhar Objetos Selecionados marcada, foi selecionado Alinhar Acima. Por fim, com as 3 formas selecionadas e clicando novamente na opção Alinhar, foi selecionado Centralizar. Após essas ações, a disposição das formas no slide é a representada em:','Figuras das alternativas A, B, C, D e E, nessa ordem.','["/pmsp/oficial-2024/q79-53-figura-1.png", "/pmsp/oficial-2024/q79-53-figura-2.png", "/pmsp/oficial-2024/q79-53-figura-3.png", "/pmsp/oficial-2024/q79-53-alternativa-1.png", "/pmsp/oficial-2024/q79-53-alternativa-2.png", "/pmsp/oficial-2024/q79-53-alternativa-3.png", "/pmsp/oficial-2024/q79-53-alternativa-4.png", "/pmsp/oficial-2024/q79-53-alternativa-5.png"]','["Figura da alternativa A (ver apoio).", "Figura da alternativa B (ver apoio).", "Figura da alternativa C (ver apoio).", "Figura da alternativa D (ver apoio).", "Figura da alternativa E (ver apoio)."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,80,'Noções de Informática','No Google Drive, um usuário selecionou 3 arquivos na Pasta 1, conforme a figura. Para copiar os links para os 3 arquivos, o usuário deve clicar sobre a opção:','Figuras das alternativas A, B, C, D e E, nessa ordem.','["/pmsp/oficial-2024/q80-55-figura-1.png", "/pmsp/oficial-2024/q80-55-alternativa-1.png", "/pmsp/oficial-2024/q80-55-alternativa-2.png", "/pmsp/oficial-2024/q80-55-alternativa-3.png", "/pmsp/oficial-2024/q80-55-alternativa-4.png", "/pmsp/oficial-2024/q80-55-alternativa-5.png"]','["Figura da alternativa A (ver apoio).", "Figura da alternativa B (ver apoio).", "Figura da alternativa C (ver apoio).", "Figura da alternativa D (ver apoio).", "Figura da alternativa E (ver apoio)."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exams(slug,title,source,year) values ('pmsp-oficial-2024-espanhol','PM São Paulo · Oficial · 2024 · 18/08/2024 · Espanhol','pmerj','2024') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'História','No contexto de formação do Império Romano, para construir o consenso político referido no excerto, o imperador Otávio Augusto','Um aspecto importante no que se refere à construção de uma unidade do Império está vinculado à posição do imperador. Nunca se tratou de um cargo legalmente regulado, mas que delimitava uma unidade político-institucional, para além do aspecto de unidade identitária. Essa posição se manteve pouco clara do ponto de vista institucional e dependia da construção de um consenso político em torno de um indivíduo que detinha a posição mais alta nas hierarquias compósitas do Império. (Norberto Luiz Guarinello. História Antiga, 2020.)',null,'["reforçou a política de distribuição de trigo e de promotoria de festividades.", "preservou a estrutura estatal e o poder do Senado do período republicano.", "conservou a organização do exército e suas estratégias de combate.", "implementou medidas para garantir a autonomia das províncias.", "suprimiu a aliança política entre as elites urbanas e o poder imperial."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'História','Os fatos históricos mencionados no excerto relacionam-se','O novo primeiro-ministro da Grã-Bretanha, George Grenville, estava determinado a arrecadar fundos. Durante décadas, uma lei exigira que os mercadores coloniais pagassem uma tarifa alfandegária sobre o melaço que importavam. As tarifas, no entanto, pouco ajudavam a Metrópole, porque a maioria dos mercadores contrabandeava seu melaço, subornando as autoridades alfandegárias para que fizessem vista grossa. Com a Lei do Açúcar, Grenville tornou o sistema mais rígido. O Parlamento também aprovou a Lei do Selo, que exigia que os americanos comprassem papel timbrado especial para todo tipo de negócio. (James West Davidson. Uma breve história dos Estados Unidos, 2016. Adaptado.)',null,'["à Petição de Direitos, assinada pelo rei Carlos I para transferir o seu poder de cobrar tributos ao parlamento britânico.", "ao reforço dos laços coloniais, impostos às Treze Colônias pelos britânicos após os prejuízos financeiros advindos da Guerra dos Sete Anos.", "à implantação dos Atos de Navegação, aprovados por Oliver Cromwell para estabelecer o uso exclusivo de navios ingleses no transporte de mercadorias para as colônias.", "ao despotismo esclarecido, adotado pela Coroa britânica nas suas colônias americanas durante o processo de Revolução Industrial.", "à política do cercamento das terras comunais nas colônias britânicas, tornando-as mais produtivas e rentáveis para a Metrópole."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'História','Com base no excerto, conclui-se que os movimentos pró-descolonização da Ásia e da África','Os líderes dos movimentos nacionalistas foram instruídos pelas nações conquistadoras: Jinnah, o chefe da Liga Muçulmana; Nehru, o líder do Partido do Congresso da Índia; Dato Onn Bingaafar, na Malásia; Nkrumah, na Costa do Ouro; Bourguiba, na Tunísia, e Forhat Abbas, na Argélia. Eles conheceram a filosofia política ocidental através do ensino, da imprensa, das longas permanências nas prisões das potências coloniais e nos contatos mantidos com os partidos políticos ocidentais. (Letícia Bicalho Canêdo. A descolonização da Ásia e da África, 1994.)',null,'["apoiaram-se nas suas tradições locais em detrimento das influências estrangeiras.", "desafiaram os valores capitalistas ocidentais na ampla maioria dos países independentes.", "corroboraram a ideia de separação entre Estado e nação na formação do Terceiro Mundo.", "buscaram modelos e ideologias europeias para lutar por suas independências.", "organizaram sociedades multinacionais para enfrentar as reações metropolitanas contra a independência."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'História','No contexto do excerto, um dos principais alvos da Com panhia Holandesa das Índias Ocidentais era','A história das invasões holandesas liga-se à passagem do trono português à coroa espanhola. Na medida em que havia um conflito aberto entre a Espanha e os Países Baixos, o relacionamento entre Portugal e Holanda iria inevitavelmente mudar. Mas a Trégua dos Doze Anos entre Espanha e os Países Baixos (1609-1621) deixou Portugal em situação relativamente calma. O fim da trégua e a criação da Companhia Holandesa das Índias Ocidentais (WIC) marcam a mudança do quadro. (Boris Fausto. História do Brasil, 2007. Adaptado.)',null,'["a busca de uma aliança político-militar entre Portugal e a Holanda para pôr fim à chamada União Ibérica.", "o controle da produção açucareira na América portu guesa e do suprimento de escravizados na África.", "a consolidação da independência dos Países Baixos frente às constantes ameaças do Império espanhol à autonomia desses territórios.", "a derrota da Insurreição Pernambucana para liquidar as tentativas luso-brasileiras de expulsão dos holandeses do Nordeste.", "o estabelecimento de um governo holandês no território brasileiro a fim de assegurar o monopólio comercial do pau-brasil."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'História','As informações do excerto sobre a cidadania política justificam-se, entre outras razões, pela seguinte determinação da Constituição de 1891:','A República, ou os vitoriosos da República, fizeram muito pouco em termos de expansão de direitos civis e políticos. Algumas mudanças trazidas pela Constituição dos Estados Unidos do Brasil de 1891, como a eliminação do Poder Moderador, do Senado Vitalício e do Conselho de Estado e a introdução do federalismo, tinham sem dúvida inspiração democratizante na medida em que buscavam desconcentrar o exercício do poder. Mas, não vindo acompanhadas por expansão significativa da cidadania política, resultaram em entregar o governo mais diretamente nas mãos dos setores dominantes, tanto rurais quanto urbanos. (José Murilo de Carvalho. Os bestializados: O Rio de Janeiro e a República que não foi, 1987. Adaptado.)',null,'["os eleitores deviam comprovar renda mínima anual para participarem das eleições primárias como candidatos.", "as mulheres precisavam exercer função pública remunerada para participarem das eleições como eleitoras.", "os homens deviam ser alfabetizados para participarem do processo eleitoral como eleitores ou candidatos.", "os homens precisavam ter idade igual ou superior a vinte e cinco anos para serem eleitores.", "os eleitores deviam ser brasileiros natos, sendo vedada a participação de estrangeiros nas eleições."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'História','Com base nas políticas econômicas do governo de Juscelino Kubitschek, os dados do infográfico relacionam-se','Analise o infográfico sobre a produção automobilística brasileira entre 1957 e 1960. (https://atlas.fgv.br. Adaptado.)','["/pmsp/oficial-2024/q6-3-figura-1.png"]','["ao processo de industrialização autônomo do país, com restrições ao uso do capital estrangeiro.", "à retomada do crescimento da indústria nacional, favorecida por mudanças no sistema tributário do país.", "à proibição das importações de bens de consumo duráveis para diminuir o déficit público do país.", "à instalação de multinacionais no país para a produção de mercadorias antes importadas.", "ao incremento de programas de distribuição de renda no país para ampliar o mercado consumidor interno."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Filosofia','Ao longo da história do pensamento humano ocidental, a filosofia desenvolveu-se em um diálogo constante de embates e acordos. Nesse sentido, a ilustração provoca reflexão sobre','A ilustração a seguir pertence a um catálogo on-line de estampas de camisetas disponíveis para compra. Sim, giramos em torno do sol! Galileu 1564-1642 d.C. Copérnico 1473-1543 d.C. Ptolomeu 100-170 d.C. Aristarco 310-230 a.C. Aristóteles 384-322 a.C. (www.doppelstore.com.br. Adaptado.)','["/pmsp/oficial-2024/q7-4-figura-1.png"]','["a consolidação de uma oposição entre racionalismo e empirismo.", "a incompatibilidade entre conhecimento popular e filosófico.", "a existência de uma aproximação entre nominalismo e realismo.", "o desenvolvimento de uma trajetória entre Antiguidade e revolução científica.", "a superioridade da abordagem dualista em relação ao monismo."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Filosofia','Descrita como um sucesso, a situação noticiada','Analise a notícia. Cientistas chineses conseguiram clonar com sucesso um macaco rhesus. A informação foi divulgada em 16.01.2024. O relatório detalha a experiência de clonar o macaco e aborda os avanços da tecnologia de clonagem. A equipe de cientistas disse que seguiu as leis e diretrizes chinesas sobre uso de primatas não-humanos em estudos. A Sociedade Real para a Prevenção de Crueldade Animal do Reino Unido afirmou que possui “sérias preocupações éticas e de bem-estar em torno do uso de tecnologia de clonagem de animais”. (“Cientistas chineses realizam primeira clonagem de macaco rhesus”. www.cnnbrasil.com.br, 16.01.2024. Adaptado.)',null,'["envolve controvérsias sobre a necessidade de pesquisas em animais para beneficiar humanos.", "demonstra a ausência de polêmicas no processo que envolve a manipulação da vida animal.", "indica um estudo aplicável imediatamente em testes empíricos sobre a saúde humana.", "revela as inovações científicas na manutenção de espécies ameaçadas de extinção.", "evidencia a condução metodológica da pesquisa pelo princípio bioético da autonomia."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Filosofia','Em sua obra A República, Platão discute a noção de justiça e como ela se manifesta tanto na cidade ideal como nos indivíduos. Essa discussão apresenta o impasse indicado no excerto, a partir do qual a noção de desigualdade é','Para Platão, o homem tende à socialização, ou seja, é naturalmente que os homens se unem para formar uma cidade e, desse modo, satisfazerem mais facilmente suas necessidades. A igualdade entre os homens, de acordo com Platão, não existe, e isto é para ele mais um traço da natureza humana. A propriedade é um dos fatores necessários para entender a questão da desigualdade. Há que se notar que Platão, por meio da proibição da propriedade, tenta, de uma certa forma, sanar a desigualdade social. No entanto, em seu estado ideal, ele instaura classes sociais que não devem intrometer-se umas nas outras, pois, sendo uns superiores e outros inferiores, devem permanecer em seu lugar, exercendo a função que lhes fora designada por natureza. (Cristiane Aparecida Barbosa. “A desigualdade nos clássicos políticos: de Platão a Rousseau”. Educação e Filosofia, 2004. Adaptado.)',null,'["o principal reflexo da democracia direta.", "uma condição inerente aos humanos.", "amenizada pelo acesso à propriedade.", "a causa de ataques entre os homens.", "gerada pela ação dos governantes."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Filosofia','(Quino. Toda Mafalda, 2010.) A reflexão suscitada pela tirinha é estudada em Filosofia a partir da',null,'["/pmsp/oficial-2024/q10-6-figura-1.png"]','["investigação dos critérios subjacentes ao juízo estético.", "análise da natureza das categorias fundamentais do ser.", "avaliação de justificativas e fundamentos das decisões morais.", "compreensão dos elementos estruturantes da realidade.", "identificação de origem e limites do conhecimento."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Sociologia','De acordo com o pensamento do autor, a atuação da tendência dominante em circunstâncias cotidianas','[…] a agricultura e a vida econômica costumam estabelecer para si mesmas outros fins que não a satisfação da necessidade de alimento; o casamento em geral expressa outras coisas, de maneira mais visível, que a preferência sexual; e o luto não enfatiza com clareza o pesar. Quanto mais intimamente conhecemos o funcionamento interno de diferentes culturas, com mais facilidade podemos ver que a variabilidade quase infinita em qualquer traço cultural, se ele for observado em volta do globo, não é um mero eco das mudanças em alguma simples resposta humana subjacente. Esteve em ação uma força diferente e maior, que usou as situações recorrentes de acasalamento, morte, abastecimento e as demais quase como matéria-prima, e as elaborou para expressar sua própria intenção. Podemos chamar essa força que curva ocasiões segundo seus propósitos e as molda a seu próprio idioma dentro dessa sociedade de sua tendência dominante. (Celso Castro. Textos básicos de Antropologia – cem anos de tradição: Boas, Malinowski, Lévi-Strauss e outros, 2016.)',null,'["revela a imprevisibilidade dos comportamentos sociais.", "manifesta-se de acordo com a cultura de cada grupo.", "realiza-se a partir da aquisição de bens essenciais.", "evidencia a universalização das ações humanas.", "confirma a desobrigação social com os rituais."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Sociologia','O excerto revela que','Apesar de o Brasil ter uma das maiores áreas cultiváveis do planeta devido ao clima e ao solo favoráveis, 116 milhões de habitantes vivem em situação de insegurança alimentar. […] E, ao mesmo tempo em que 19 milhões de cidadãos no país passam fome, 26,8% da população adulta sofrem de obesidade devido à alimentação baseada em produtos baratos, ultraprocessados ou de pouco valor nutritivo. (Maria Eduarda Cardim e Rosana Hessel. “Brasil das safras recordes enfrenta fome e obesidade”. www.correiobraziliense.com.br, 10.02.2022.)',null,'["o desenvolvimento econômico exige políticas que restrinjam a alimentação dos mais pobres.", "a grande presença de obesos brasileiros pertencentes às classes mais baixas mostra uma contradição.", "as políticas públicas voltadas para o combate à obesi dade devem considerar a desigualdade social.", "a obesidade no Brasil é predominantemente um problema de escolhas individuais e falta de disciplina pessoal.", "as classes sociais mais baixas têm boa alimentação devido ao valor acessível de produtos orgânicos."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Sociologia','A situação retratada no excerto remete','Uma história de 150 anos que começa com uma viagem de um mês e meio em condições precárias, nos fundos de um navio, agarrando-se à família e à esperança de um futuro do outro lado do oceano. Assim chegavam cerca de 400 italianos à costa brasileira em 21 de fevereiro de 1874, pioneiros de um movimento que atraiu 1,4 milhão de pessoas em 50 anos. A travessia, realizada no navio La Sofia, de Gênova rumo ao Espírito Santo, alterou para sempre não somente a vida de cada um desses desbravadores, mas a cultura e a economia brasileiras, que ganharam contornos italianos inegáveis desde então. (Gabriel Rodrigues. “Há 150 anos, imigração italiana foi pioneira e transformou o Brasil”. www.otempo.com.br, 21.02.2024.)',null,'["à etapa da miscigenação brasileira pautada pelo princípio da democracia racial.", "à importância do desenvolvimento de infraestrutura moderna para acomodar os imigrantes.", "à relevância de políticas sociais para a recuperação da economia brasileira após a crise do café.", "ao início da contribuição italiana para a cultura brasileira a partir de políticas de embranquecimento do Brasil.", "à iniciativa brasileira de prover melhores condições de vida aos italianos como estratégia de combate ao eurocentrismo."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Sociologia','A elaboração descrita no excerto é parte das funções típicas do Poder','Ao ser criada uma nova política pública, devem ser definidos, entre outros itens, os responsáveis pela coordenação e articulação das ações; as competências das principais partes envolvidas, com respectivos objetivos, papéis, responsabilidades, recursos e obrigações; o grau de focalização ou universalização da política pública, considerando as necessidades do público-alvo e os recursos disponíveis; e o plano de gestão de riscos com a identificação dos principais problemas que podem surgir e as medidas mitigadoras para tratá-los. (“Aprovado projeto que estabelece normas para criação de políticas públicas”. www.coad.com.br, 05.04.2018.)',null,'["Judiciário.", "Bicameral.", "Legislativo.", "Moderador.", "Executivo."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Geografia','Os eventos geológicos descritos no excerto são provocados pelo movimento','A ilha de Taiwan sofreu com o maior terremoto em 25 anos no dia 02.04.2024, quando um abalo sísmico de 7,4 na esca-la Richter foi sentido na cidade de Hualien, que está situada a cerca de 150 quilômetros da capital, Taipei, como informou o Serviço Geológico dos Estados Unidos (United States Geological Survey, da sigla USGS). O terremoto também foi sentido em Xangai, na China, e em várias províncias ao longo da costa sudeste chinesa. A intensidade do tremor alcançou cerca de 35 quilômetros de profundidade e com isso um alerta de tsunami foi gerado no Japão. Ao longo dos últimos 50 anos, o território de Taiwan tem sofrido com terremotos de alta intensidade e o principal motivo é a sua localização geográfica no mundo. (www.nationalgeographicbrasil.com, 03.04.2024. Adaptado.)',null,'["transformante entre as placas Euroasiática e Indiana, na zona sísmica do Pacífico.", "convergente entre as placas Euroasiática e Filipina, na zona do círculo de fogo.", "transformante entre as placas Australiana e do Pacífico, na zona do círculo de fogo.", "convergente entre as placas Australiana e de Nasca, na zona sísmica do Pacífico.", "divergente entre as placas Indiana e de Cocos, na zona da dorsal meso-oceânica."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Geografia','A partir da análise do gráfico e de conhecimentos sobre a crise ambiental em escala mundial, verifica-se que','Extração global de recursos, quatro categorias principais de recursos, 1970-2024, milhões de toneladas (Programa das Nações Unidas para o Meio Ambiente (Pnuma). Perspectiva de Recursos Globais, 2024. Adaptado.)','["/pmsp/oficial-2024/q16-10-figura-1.png"]','["o crescimento da extração de biomassa está relacionado aos esforços globais para mitigar as metas de controle de poluição.", "o baixo crescimento da extração de combustíveis fósseis está relacionado à preferência pela utilização de energia sustentável nos países desenvolvidos.", "o baixo crescimento da extração de minerais metálicos está relacionado às preocupações com a pegada ecológica dos processos industriais.", "o crescimento da extração de minerais não metálicos está relacionado ao aumento das emissões de gases do efeito estufa.", "a diminuição da extração de biomassa está relacionada ao estímulo à equidade socioambiental nos países do Sul Global."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Geografia','O cenário descrito no excerto tem como consequência','Transformação digital, 5G, indústria 4.0, inteligência arti ficial (IA), computação em nuvem, blockchain e muitos outros termos são novas expressões que têm inundado o mundo inteiro. A transformação digital é uma mudança radical na forma de pensar como uma organização utiliza tecnologia, pessoas e processos para alterar seu desempenho nos negócios. Empregam-se tecnologias e ferramentas digitais para criar ou modificar processos de negócios existentes, culturas empresariais e a experiência do usuário, conseguindo assim atender aos requisitos de mercado em constante modificação. (Robert Spadinger. “Internet das coisas (IOT) transformação digital e indústria 4.0”. In: Luiz Claudio Kubota (org.). Digitalização e tecnologias da informação e comunicação, 2024. Adaptado.)',null,'["a diversificação do ambiente empresarial pela contratação de trabalhadores terceirizados.", "a distribuição de polos industriais de alta tecnologia pela adaptação do modelo fordista.", "a diminuição do desemprego conjuntural pelo investimento na qualificação do trabalhador.", "a mitigação da concentração do capital pela distribuição da produção industrial das Big Techs.", "a transformação do mercado de trabalho pelo aprofundamento do desemprego estrutural."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Geografia','Sabendo que a Geórgia está localizada na Europa Oriental e que integrou a União Soviética, a lei mencionada no excerto é um instrumento que limita seus interesses geopolíticos quanto','Apesar dos protestos nas ruas e alertas da comunidade internacional, o Parlamento da Geórgia adotou uma polêmica lei sobre a influência estrangeira, que afeta a regulação de veículos de comunicação e Organizações Não-Governamentais (ONGs). A lei exige que os meios de comunicação e as ONGs que obtenham mais de 20% de seu orçamento do exterior se registrem como órgãos que “cumprem o interes-se de uma potência estrangeira”. Para os opositores, essa lei restringirá a liberdade de imprensa e obstruirá as chances de a Geórgia ingressar em organismos multilaterais de cooperação internacional. A presidente da Geórgia, Salome Zurabishvili, vetou a lei em 18.05.2024. Na ocasião, ela disse que o texto “contradiz nossa Constituição e todas as normas europeias”, representando um “obstáculo ao nosso caminho europeu”. (Parlamento da Geórgia aprova lei de ‘influência estrangeira’ em meio a protestos contra medida. https://oglobo.globo.com, 29.05.2024. Adaptado.)',null,'["à sua entrada no Conselho para Assistência Econômica Mútua (COMECON), uma vez que o país terá vantagens para importar gás natural produzido no bloco.", "à sua admissão na Comunidade dos Estados Independentes (CEI), uma vez que o país busca estreitar as relações diplomáticas com a Rússia.", "à sua condição de país-membro na Organização do Tratado do Atlântico Norte (Otan), uma vez que o país integra a aliança militar desde a dissolução da União Soviética.", "à sua adesão à União Europeia (UE), uma vez que o país já possui o reconhecimento da sua condição de país candidato pelo bloco.", "à sua participação no acordo de Oslo, uma vez que o país deseja integrar o Tribunal Penal de Haia para punir os crimes de guerra sofridos durante a separação da Iugoslávia."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Geografia','De acordo com a análise do cartograma e conhecimentos sobre a estrutura do agronegócio brasileiro, a variação na produção e exportação de grãos da soja e do milho ao norte e ao sul do paralelo 16º S é resultado','Analise o cartograma que demonstra a produção e a exportação da soja e do milho acima e abaixo do paralelo 16º S, em 2023. (www.canalrural.com.br, 09.03.2024.)','["/pmsp/oficial-2024/q19-13-figura-1.png"]','["de modelos distintos de financiamento, que seguem linhas de crédito diferenciadas de acordo com o destino dos produtos.", "da diferença na estrutura fundiária das monocultoras, que estão assentadas em minifúndios e latifúndios.", "da desigual distribuição da infraestrutura logística insta lada, que compromete a competitividade dos produtos.", "da função social desempenhada pela propriedade rural, que possibilita atender os mercados interno e externo em diferentes regiões.", "da variação das condições ambientais, que altera a capacidade de produção devido ao uso de sementes transgênicas ou crioulas."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Geografia','A característica da população jovem brasileira apresentada no excerto tem como impacto','Há, em 2024, mais jovens no Brasil que não estudam, não trabalham e nem estão procurando emprego. No primeiro trimestre de 2023, havia cerca de 4 milhões de pessoas entre 14 e 24 anos nessa condição. Agora, no mesmo período do ano, são 5,4 milhões. De acordo com o levantamento, cerca de 60% dessa população é composta por mulheres. A maior parte delas, inclusive, tem filhos pequenos. Em um outro recorte, 68% dos que não estudam, não trabalham e nem buscam emprego são negros. (André Lucena. www.cartacapital.com.br, 28.05.2024. Adaptado.)',null,'["a diminuição da capacidade produtiva do país, o que resulta em menor crescimento do PIB.", "o aumento da taxa de fecundidade do país, o que esti mula o crescimento demográfico.", "a estabilidade da transição demográfica do país, o que provoca aumento na expectativa de vida ao nascer.", "o crescimento do setor terciário no país, o que promove aumento do desemprego estrutural.", "o incremento do subemprego no país, o que resulta em menores taxas de informalidade."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Língua Portuguesa','O efeito de humor da tirinha se dá por meio do emprego da linguagem','Examine a tirinha de Fernando Gonsales, publicada no site do autor em 08.04.2024, para responder às questões 21 e 22. (www.niquel.com.br)','["/pmsp/oficial-2024/apoio-21-22-15-1.png"]','["conotativa.", "metonímica.", "denotativa.", "comparativa.", "antagônica."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Língua Portuguesa','O ponto de exclamação é uma pontuação versátil que pode explicitar uma ampla gama de emoções e intenções. Na fala do primeiro e do último quadrinho, esse ponto expressa, respectivamente,','Examine a tirinha de Fernando Gonsales, publicada no site do autor em 08.04.2024, para responder às questões 21 e 22. (www.niquel.com.br)','["/pmsp/oficial-2024/apoio-21-22-15-1.png"]','["surpresa e ordem.", "entusiasmo e frustração.", "excitação e ironia.", "alegria e desespero.", "ênfase e dúvida."]'::jsonb,'B',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Língua Portuguesa','De acordo com o trecho, Amália considerava o casamento uma','Leia o trecho do romance Encarnação, de José de Alencar, para responder às questões de 23 a 28. Conheci outrora uma família que morava em São Clemente. Havia em sua casa agradáveis reuniões de que fazia os encantos uma filha, bonita moça de dezoito anos, corada como a aurora e loura como o sol. Amália seduzia especialmente pela graça radiante, e pela viçosa e ingênua alegria, que manava dos lábios vermelhos, como dos olhos de topázio, e lhe rorejava¹ a lúcida beleza. Sua risada argentina era a mais cintilante das volatas² que ressoavam entre os rumores festivos da casa, onde à noite o piano trinava sob os dedos ágeis da melhor discípula do Arnaud. Acontecia-lhe chorar algumas vezes por causa de um vestido que a modista não lhe fizera a gosto, ou de um baile muito desejado que se transferia; mas essas lágrimas efêmeras, que saltavam em bagas dos grandes olhos luminosos, iam nas covinhas da boca transformar-se em cascatas de risos frescos e melodiosos. Tinha razão de folgar. Era o carinho dos pais e a predileta de quantos a conheciam. Muitos dos mais distintos moços da corte a adoravam. Ela, porém, preferia a isenção de menina; e não pensava em escolher um dentre tantos apaixonados, que a cercavam. Os pais, que desejavam muito vê-la casada e feliz, sentiam quando ela recusava algum partido vantajoso. Mas reconheciam ao mesmo tempo que formosa, rica e prendada como era, a filha tinha o direito de ser exigente; e confiavam no futuro. Outra e bem diversa era a causa da indiferença da moça. Amália não acreditava no amor. A paixão para ela só existia no romance. Os enlevos³ de duas almas a viverem uma da outra não passavam de arroubos de poesia, que davam em comédia quando os queriam transportar para o mundo real. Tinha sobre o casamento ideias mui positivas. Considerava o estado conjugal uma simples partilha de vida, de bens, de prazeres e trabalhos. Estes não os queria: os mais ela os possuía e gozava, mesmo solteira, no seio de sua família. Era feliz; não compreendia, portanto, a vantagem de ligar-se para sempre a um estranho, no qual podia encontrar um insípido companheiro, se não fosse um tirano doméstico. Estes pensamentos, Amália não os enunciava, nem os erigia em opiniões. Eram apenas os impulsos íntimos de sua vontade; obedecendo a eles, não tinha a menor pretensão à excentricidade. Ao contrário, como sabia do desejo dos pais, aceitava de boa mente a corte de seus admiradores. Mas estes bem percebiam que para a travessa e risonha vestal⁴ dos salões, o amor não era mais do que um divertimento de sociedade, semelhante à dança ou à música. Conservando a sua independência de filha querida, e moça da moda, Amália não nutria prejuízos contra o casamento, que aliás aceitava como uma solução natural para o outono da mulher. Ela bem sabia, que depois de haver gozado da mocidade, no fim de sua esplêndida primavera, teria de pagar o tributo à sociedade, e como as outras escolher um marido, fazer-se dona-de-casa, e rever nos filhos a sua beleza desvanecida. Até lá, porém, era e queria ser flor. Das suas lições de botânica lhe ficara bem viva esta recordação, que o fruto só desponta quando as pétalas começam a fanar-se: se vem antes disso, eiva⁵. (Encarnação, 2003.) ¹ rorejar: gotejar. ² volata: série de notas musicais executadas rapidamente. ³ enlevo: êxtase, deleite. 4 vestal: sacerdotisa da deusa romana Vesta; mulher muito bonita que devia guardar rigorosa castidade. ⁵ eivar: falhar.',null,'["consequência natural da vida.", "instituição falida e sem propósito.", "escolha inconsciente e baseada no amor.", "imposição social degradante.", "necessidade imediata."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Língua Portuguesa','Na expressão “outono da mulher” (16o parágrafo), a palavra sublinhada é uma metáfora para referir-se','Leia o trecho do romance Encarnação, de José de Alencar, para responder às questões de 23 a 28. Conheci outrora uma família que morava em São Clemente. Havia em sua casa agradáveis reuniões de que fazia os encantos uma filha, bonita moça de dezoito anos, corada como a aurora e loura como o sol. Amália seduzia especialmente pela graça radiante, e pela viçosa e ingênua alegria, que manava dos lábios vermelhos, como dos olhos de topázio, e lhe rorejava¹ a lúcida beleza. Sua risada argentina era a mais cintilante das volatas² que ressoavam entre os rumores festivos da casa, onde à noite o piano trinava sob os dedos ágeis da melhor discípula do Arnaud. Acontecia-lhe chorar algumas vezes por causa de um vestido que a modista não lhe fizera a gosto, ou de um baile muito desejado que se transferia; mas essas lágrimas efêmeras, que saltavam em bagas dos grandes olhos luminosos, iam nas covinhas da boca transformar-se em cascatas de risos frescos e melodiosos. Tinha razão de folgar. Era o carinho dos pais e a predileta de quantos a conheciam. Muitos dos mais distintos moços da corte a adoravam. Ela, porém, preferia a isenção de menina; e não pensava em escolher um dentre tantos apaixonados, que a cercavam. Os pais, que desejavam muito vê-la casada e feliz, sentiam quando ela recusava algum partido vantajoso. Mas reconheciam ao mesmo tempo que formosa, rica e prendada como era, a filha tinha o direito de ser exigente; e confiavam no futuro. Outra e bem diversa era a causa da indiferença da moça. Amália não acreditava no amor. A paixão para ela só existia no romance. Os enlevos³ de duas almas a viverem uma da outra não passavam de arroubos de poesia, que davam em comédia quando os queriam transportar para o mundo real. Tinha sobre o casamento ideias mui positivas. Considerava o estado conjugal uma simples partilha de vida, de bens, de prazeres e trabalhos. Estes não os queria: os mais ela os possuía e gozava, mesmo solteira, no seio de sua família. Era feliz; não compreendia, portanto, a vantagem de ligar-se para sempre a um estranho, no qual podia encontrar um insípido companheiro, se não fosse um tirano doméstico. Estes pensamentos, Amália não os enunciava, nem os erigia em opiniões. Eram apenas os impulsos íntimos de sua vontade; obedecendo a eles, não tinha a menor pretensão à excentricidade. Ao contrário, como sabia do desejo dos pais, aceitava de boa mente a corte de seus admiradores. Mas estes bem percebiam que para a travessa e risonha vestal⁴ dos salões, o amor não era mais do que um divertimento de sociedade, semelhante à dança ou à música. Conservando a sua independência de filha querida, e moça da moda, Amália não nutria prejuízos contra o casamento, que aliás aceitava como uma solução natural para o outono da mulher. Ela bem sabia, que depois de haver gozado da mocidade, no fim de sua esplêndida primavera, teria de pagar o tributo à sociedade, e como as outras escolher um marido, fazer-se dona-de-casa, e rever nos filhos a sua beleza desvanecida. Até lá, porém, era e queria ser flor. Das suas lições de botânica lhe ficara bem viva esta recordação, que o fruto só desponta quando as pétalas começam a fanar-se: se vem antes disso, eiva⁵. (Encarnação, 2003.) ¹ rorejar: gotejar. ² volata: série de notas musicais executadas rapidamente. ³ enlevo: êxtase, deleite. 4 vestal: sacerdotisa da deusa romana Vesta; mulher muito bonita que devia guardar rigorosa castidade. ⁵ eivar: falhar.
