0o parágrafo).", "“Estes pensamentos, Amália não os enunciava, nem os erigia em opiniões” (14o parágrafo).", "“Das suas lições de botânica lhe ficara bem viva esta recordação” (18o parágrafo)."]'::jsonb,'D',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
