insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Língua Portuguesa','Classifica-se como rica a rima que ocorre entre palavras de classes gramaticais diferentes. Esse tipo de rima ocorre no par:','Leia o poema de Luís de Camões para responder às questões de 29 a 33. SONETO VIII Pede o desejo, dama, que vos veja, Não entende o que pede, está enganado. É este amor tão fino e tão delgado¹, Que quem o tem não sabe o que deseja. Não há cousa a qual natural seja Que não queira perpétuo seu estado, Não quer logo o desejo o desejado, Por que não falte nunca onde sobeja². Mas este puro afeito³ em mim se dana, Que como a grave⁴ pedra tem por arte O centro desejar da natureza. Assi⁵ o pensamento (pela parte Que vai tomar de mim, terrestre, humana) Foi, senhora, pedir esta baixeza. (Luís de Camões. 20 sonetos, 2018.) ¹ delgado: delicado. ² sobejar: sobrar, ter em excesso. ³ afeito: afeto, sentimento. ⁴ grave: pesada. ⁵ assi: assim.',null,'["“veja” e “deseja” (1a estrofe).", "“enganado” e “delgado” (1a estrofe).", "“seja” e “sobeja” (2a estrofe).", "“arte” e “parte” (3a e 4a estrofes).", "“dana” e “humana” (3a e 4a estrofes)."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Língua Portuguesa','“Que como a grave pedra tem por arte O centro desejar da natureza.” (3a estrofe) Em ordem direta, esses versos assumem a seguinte forma:','Leia o poema de Luís de Camões para responder às questões de 29 a 33. SONETO VIII Pede o desejo, dama, que vos veja, Não entende o que pede, está enganado. É este amor tão fino e tão delgado¹, Que quem o tem não sabe o que deseja. Não há cousa a qual natural seja Que não queira perpétuo seu estado, Não quer logo o desejo o desejado, Por que não falte nunca onde sobeja². Mas este puro afeito³ em mim se dana, Que como a grave⁴ pedra tem por arte O centro desejar da natureza. Assi⁵ o pensamento (pela parte Que vai tomar de mim, terrestre, humana) Foi, senhora, pedir esta baixeza. (Luís de Camões. 20 sonetos, 2018.) ¹ delgado: delicado. ² sobejar: sobrar, ter em excesso. ³ afeito: afeto, sentimento. ⁴ grave: pesada. ⁵ assi: assim.',null,'["Como a pedra grave tem que desejar o centro por arte da natureza.", "Que a grave pedra, por natureza, tem como desejar o centro da arte.", "O centro da arte tem que desejar a pedra grave como por natureza.", "O centro grave da pedra tem, por arte, que desejar como a natureza.", "Como por arte da natureza, o centro tem que desejar a pedra grave."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Língua Portuguesa','O gênero textual crônica pode provocar reflexões profundas a partir da apresentação de situações banais do cotidiano. A autora demonstra ter consciência desse aspecto no trecho:','Leia a crônica “Liberdade”, de Clarice Lispector, para responder às questões de 34 a 38. Houve um diálogo difícil. Aparentemente não quer dizer muito, mas diz demais. — Mamãe, tire esse cabelo da testa. — É um pouco da franja ainda. — Mas você fica feia assim. — Tenho o direito de ser feia. — Não tem! — Tenho! — Eu disse que não tem! E assim foi que se formou o clima de briga. O motivo não era fútil, era sério: uma pessoa, meu filho no caso, estava-me cortando a liberdade. E eu não suportei, nem vindo de filho. Senti vontade de cortar uma franja bem espessa, bem cobrindo a testa toda. Tive vontade de ir para meu quarto, de trancar a porta a chave, e de ser eu mesma, por mais feia que fosse. Não, não “por mais feia que fosse”: eu queria ser feia, isso representava o meu direito total à liberdade. Ao mesmo tempo eu sabia que meu filho tinha os direitos dele: o de não ter uma mãe feia, por exemplo. Era o choque de duas pessoas reivindicando — o que, afinal? Só Deus sabe, e fiquemos por aqui mesmo. (Clarice Lispector. A descoberta do mundo, 1999.)',null,'["“Aparentemente não quer dizer muito, mas diz demais” (1o parágrafo).", "“— Tenho o direito de ser feia” (5o parágrafo).", "“E assim foi que se formou o clima de briga” (9o parágrafo).", "“Era o choque de duas pessoas reivindicando — o que, afinal?” (9o parágrafo).", "“Só Deus sabe, e fiquemos por aqui mesmo” (9o parágrafo)."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Língua Portuguesa','Ao se transpor a fala “— Mamãe, tire esse cabelo da testa.” (2o parágrafo) para o discurso indireto, o verbo sublinhado assume a forma:','Leia a crônica “Liberdade”, de Clarice Lispector, para responder às questões de 34 a 38. Houve um diálogo difícil. Aparentemente não quer dizer muito, mas diz demais. — Mamãe, tire esse cabelo da testa. — É um pouco da franja ainda. — Mas você fica feia assim. — Tenho o direito de ser feia. — Não tem! — Tenho! — Eu disse que não tem! E assim foi que se formou o clima de briga. O motivo não era fútil, era sério: uma pessoa, meu filho no caso, estava-me cortando a liberdade. E eu não suportei, nem vindo de filho. Senti vontade de cortar uma franja bem espessa, bem cobrindo a testa toda. Tive vontade de ir para meu quarto, de trancar a porta a chave, e de ser eu mesma, por mais feia que fosse. Não, não “por mais feia que fosse”: eu queria ser feia, isso representava o meu direito total à liberdade. Ao mesmo tempo eu sabia que meu filho tinha os direitos dele: o de não ter uma mãe feia, por exemplo. Era o choque de duas pessoas reivindicando — o que, afinal? Só Deus sabe, e fiquemos por aqui mesmo. (Clarice Lispector. A descoberta do mundo, 1999.)
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Língua Portuguesa','A zeugma é uma das formas da elipse. Consiste em fazer participar de dois ou mais enunciados um termo expresso apenas em um deles. (Celso Cunha. Nova gramática do português contemporâneo, 2001. Adaptado.) Identifica-se, no último parágrafo da crônica, o emprego da zeugma em:','Leia a crônica “Liberdade”, de Clarice Lispector, para responder às questões de 34 a 38. Houve um diálogo difícil. Aparentemente não quer dizer muito, mas diz demais. — Mamãe, tire esse cabelo da testa. — É um pouco da franja ainda. — Mas você fica feia assim. — Tenho o direito de ser feia. — Não tem! — Tenho! — Eu disse que não tem! E assim foi que se formou o clima de briga. O motivo não era fútil, era sério: uma pessoa, meu filho no caso, estava-me cortando a liberdade. E eu não suportei, nem vindo de filho. Senti vontade de cortar uma franja bem espessa, bem cobrindo a testa toda. Tive vontade de ir para meu quarto, de trancar a porta a chave, e de ser eu mesma, por mais feia que fosse. Não, não “por mais feia que fosse”: eu queria ser feia, isso representava o meu direito total à liberdade. Ao mesmo tempo eu sabia que meu filho tinha os direitos dele: o de não ter uma mãe feia, por exemplo. Era o choque de duas pessoas reivindicando — o que, afinal? Só Deus sabe, e fiquemos por aqui mesmo. (Clarice Lispector. A descoberta do mundo, 1999.)',null,'["“O motivo não era fútil, era sério”.", "“uma pessoa, meu filho no caso, estava-me cortando a liberdade”.", "“E eu não suportei, nem vindo de filho”.", "“eu queria ser feia, isso representava o meu direito total à liberdade”.", "“Ao mesmo tempo eu sabia que meu filho tinha os direitos dele”."]'::jsonb,'A',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_i