insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Língua Portuguesa','Em “de ser eu mesma, por mais feia que fosse” (9o pará grafo), a locução conjuntiva “por mais que” pode ser substi tuída, sem prejuízo para o sentido do texto, por:','Leia a crônica “Liberdade”, de Clarice Lispector, para responder às questões de 34 a 38. Houve um diálogo difícil. Aparentemente não quer dizer muito, mas diz demais. — Mamãe, tire esse cabelo da testa. — É um pouco da franja ainda. — Mas você fica feia assim. — Tenho o direito de ser feia. — Não tem! — Tenho! — Eu disse que não tem! E assim foi que se formou o clima de briga. O motivo não era fútil, era sério: uma pessoa, meu filho no caso, estava-me cortando a liberdade. E eu não suportei, nem vindo de filho. Senti vontade de cortar uma franja bem espessa, bem cobrindo a testa toda. Tive vontade de ir para meu quarto, de trancar a porta a chave, e de ser eu mesma, por mais feia que fosse. Não, não “por mais feia que fosse”: eu queria ser feia, isso representava o meu direito total à liberdade. Ao mesmo tempo eu sabia que meu filho tinha os direitos dele: o de não ter uma mãe feia, por exemplo. Era o choque de duas pessoas reivindicando — o que, afinal? Só Deus sabe, e fiquemos por aqui mesmo. (Clarice Lispector. A descoberta do mundo, 1999.)',null,'["porquanto.", "caso.", "conforme.", "todavia.", "embora."]'::jsonb,'E',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Língua Portuguesa','“Tive vontade de ir para meu quarto, de trancar a porta a chave” (9o parágrafo) O emprego de crase na expressão sublinhada é facultativo, assim como em:','Leia a crônica “Liberdade”, de Clarice Lispector, para responder às questões de 34 a 38. Houve um diálogo difícil. Aparentemente não quer dizer muito, mas diz demais. — Mamãe, tire esse cabelo da testa. — É um pouco da franja ainda. — Mas você fica feia assim. — Tenho o direito de ser feia. — Não tem! — Tenho! — Eu disse que não tem! E assim foi que se formou o clima de briga. O motivo não era fútil, era sério: uma pessoa, meu filho no caso, estava-me cortando a liberdade. E eu não suportei, nem vindo de filho. Senti vontade de cortar uma franja bem espessa, bem cobrindo a testa toda. Tive vontade de ir para meu quarto, de trancar a porta a chave, e de ser eu mesma, por mais feia que fosse. Não, não “por mais feia que fosse”: eu queria ser feia, isso representava o meu direito total à liberdade. Ao mesmo tempo eu sabia que meu filho tinha os direitos dele: o de não ter uma mãe feia, por exemplo. Era o choque de duas pessoas reivindicando — o que, afinal? Só Deus sabe, e fiquemos por aqui mesmo. (Clarice Lispector. A descoberta do mundo, 1999.)
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Língua Estrangeira','Según el autor, por lo general, la gente busca las actividades de riesgo debido a','Leia o texto para responder às questões de 39 a 42. Los deportes de riesgo son aquellos que presentan un peligro real o aparente para la integridad física de quienes los practican, incluso un peligro vital. Pueden ser deportes realizados en condiciones difíciles o extremas o, simplemente, actividades de ocio cuyos riesgos no pueden ser controlados totalmente por una preparación técnica o física por extraordinaria que sea esta. Uno de los elementos que podrían definirlos, entre otros, es la búsqueda de inyecciones de adrenalina por parte del deportista. Los deportes arriesgados son sinónimo de creatividad, pasión y experimentación, pero también, como se ha dicho, sinónimo de peligro para la salud o la integridad física, incluso para la vida. Entre las condiciones que los definen como una práctica deportiva extrema, hay dos elementos que suelen ser los más frecuentes: la velocidad y la altitud, pero no son los únicos. Sin duda, detrás de ellos existe un gen que nos hace buscar nuestros límites o una torpe necesidad de diferenciarnos, de autoafirmación. Igual que al viajar cumplimos sueños que a veces sólo están en nuestra imaginación, los deportes de riesgo implican impulsos o atracciones difíciles de regular. Si nos decidimos por alguno, lo mejor es iniciarse en su práctica de la mano de profesionales, esto es, de personas capacitadas que nos aconsejen. Ellos pueden determinar si estamos aptos o no para su práctica o qué actividad se ajusta más a nuestras condiciones físicas y expectativas. Algunas de estas prácticas exigen control y entrenamiento desde pequeños y son casi exclusivas de gente muy joven, otras son propias de personas de edad media, con años de desarrollo técnico y experiencia o cada vez más comunes entre profesionales destacados o altos ejecutivos que buscan experiencias más exigentes, a la altura de su ritmo de vida. (https://doctorvillanueva.com. Adaptado.)',null,'["la necesidad de superar los prejuicios que la rodean.", "la certeza de que la fatalidad es segura.", "las intensas emociones que estas provocan.", "la necesidad de curarse de ciertas enfermedades.", "la alta posición que ocupa en la pirámide social."]'::jsonb,'C',null from public.exams where slug='pmsp-oficial-2024-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
